(window.FREALLY_I18N = window.FREALLY_I18N || {})["ko"] = {"hero.headline":"<span class=\"hl-muted\">스타일에 충실한 MIDI,</span> <span class=\"hl-bright\">당신의 DAW 안에서.</span>","index.0e16857e":"드럼, 멜로디, 카운터멜로디, 808, 코드, 그리고 곡 전체의 편곡 — 특정 아티스트의 스타일로, 원본 MIDI로, <strong>당신 프로젝트 자신의 조성과 템포로</strong> 생성됩니다. 무료, 오프라인, 그리고 100% AI 없음.","hero.chipStandalone":"독립 실행형","hero.chipWeb":"웹","hero.chipLinux":"Linux (편집기 작업 중)","index.a9e41a1f":"현황 — 이제는 플러그인입니다","index.4c860bcf":"Freally MIDI Master는 데스크톱 앱으로 시작했습니다. <strong>v0.2.0</strong>이 그 빌드였습니다. <strong>2026년 7월 29일부로 데스크톱 앱은 퇴역했습니다</strong> — 더 이상 빌드되거나 배포되지 않습니다. 이미 설치된 것은 계속 동작합니다. 다만 업데이트를 더는 찾지 않습니다.","index.986fa10d":"이제는 <strong>CLAP 플러그인이고, VST3와 AU가 거기서 투영됩니다</strong> — 형식 자체를 위해서가 아니라, 플러그인에는 호스트의 템포, 박자, 재생 위치가 전달되기 때문입니다. 생성된 패턴은 아티스트가 마침 적혀 있는 템포가 아니라, 당신이 실제로 쓰고 있는 곡에 떨어집니다.","index.e46c4677":"<strong>Ableton Live&nbsp;12</strong>(VST3)와 <strong>FL&nbsp;Studio</strong>(CLAP)에서 로드되고 생성합니다. Reaper, Bitwig, Logic은 아직 확인하지 않았습니다. 독립 실행 빌드는 같은 플러그인을 DAW 없이 자체 창에서 실행합니다.","see.title":"실제 모습","see.intro":"실행 중인 플러그인: 생성된 멜로디와 그것을 연주하는 건반, 그리고 타임라인 위의 전체 편곡.","features.0cdb36f4":"트랩 멜로디를 생성한 Freally MIDI Master: 위쪽에 늘어선 드럼 패드, 피아노 롤과 그 벨로시티 레인, 그 아래 네 개의 Re-Dream 클립, 그리고 맨 아래의 화면 건반.","features.1ef3563d":"생성된 트랩 멜로디, 그 벨로시티 레인, 그것의 네 Re-Dream, 그리고 그것을 연주해 넣을 수 있는 건반.","features.dacd8e46":"송 모드: 타임라인에 56마디 편곡. INTRO, VERSE, HOOK, OUTRO 구간과 파트마다 편집할 수 있는 클립 하나 — 드럼, 코드, 멜로디, 카운터멜로디 — 각자 자신의 MIDI 칩과 Audio 칩을 가집니다.","features.6fe61d69":"송 모드: 편집할 수 있는 타임라인에 편곡 전체, 파트마다 한 클립, 각자 끌어낼 수 있는 자신의 MIDI와 오디오를 가집니다.","home.inside.title":"담긴 것","index.92530b36":"장르가 아니라 아티스트","index.420c17ef":"대부분의 생성기는 장르로 생각합니다. ‘트랩’은 ‘Metro Boomin’이 아니고, 주류 도구 중 OsamaSon을 들어본 것은 하나도 없습니다. 이름을 입력하면 그 아티스트의 실제 특징을 담은 패턴이 나옵니다.","index.e6a1356b":"DAW를 따라갑니다","index.bab9531a":"플러그인은 블록마다 호스트의 템포와 박자를 읽으므로, 140에서 쓰인 트랩은 92&nbsp;BPM 프로젝트에서 92로 나옵니다. 템포를 고정하면 당신 것이 이깁니다.","index.4a2c8227":"다섯 개의 생성기, 그리고 송 모드","index.bd395814":"드럼, 멜로디, 카운터멜로디, 베이스라인, 코드 — 그리고 송 모드. 여섯 번째 생성기가 아니라, 다섯 개를 모두 채우는 편곡입니다.","index.04c8fb28":"아티스트마다 무드가 있습니다","index.efa5276f":"무드를 하나 골라 거기에 머물러도 되고, <em>아무거나</em>로 두어 누를 때마다 그 아티스트의 폭을 돌게 해도 됩니다. 아티스트는 한 종류의 음반만 쓰지 않으며, 어떤 시드도 그 사이를 넘나들 수는 없습니다.","index.276d670e":"나만의 스타일을 만들기","index.84153fc4":"아무 아티스트에서 출발해 원하는 부분만 손보고 저장하면 — 함께 실린 것들과 나란히 스타일 목록에 놓이고, 완전히 같은 방식으로 동작합니다. 같은 종류의 것이기 때문입니다. 마음에 드는 테이크에 별을 달면, 거기에 스타일을 맞춰 줍니다.","index.5a9ab055":"노트가 트랙에 떨어집니다","index.06309989":"끌어다 놓을 파일도, 찾아야 할 폴더도 없습니다. 플러그인은 당신이 꽂아 넣은 그 자리에서 호스트 자신의 시간으로 MIDI를 내보냅니다.","index.191153d2":"시드로 재현됩니다","index.3bb0362b":"생성마다 시드가 있습니다. 복사해서 붙이면 똑같은 비트가 그대로 돌아옵니다 — 어떤 기기에서든, 어느 날이든. 결정성은 테스트 스위트가 강제합니다.","index.f52c92c0":"AI 없음, 계정 없음, 클라우드 없음","index.21393e5c":"모델 없음, 학습 데이터 없음, 추론 없음, 생성 중 네트워크 호출 없음. 로그인도 원격 측정도 없습니다. 모든 것이 당신의 기기에서 일어납니다 — ‘내 스타일 학습시키기’까지도. 그것은 남겨 둔 테이크를 측정해 숫자를 되써 넣는 일이고, 무엇도 학습하지 않습니다. 의존성 어딘가에 AI나 HTTP 클라이언트가 있는 빌드는 통과하지 못합니다.","index.7f44a4fa":"1.0으로 가는 길","index.99276787":"빌드마다 능력 하나를 온전히 내놓습니다. 절반만 한 것은 내보내지 않습니다.","ladder.rung.v0.3.0":"플러그인으로의 전환. CLAP, 그리고 거기서 투영된 VST3와 AU. Ableton과 FL Studio에서 로드됩니다.","ladder.rung.v0.4.0":"무제한 실행 취소. 세션 변경은 한 번의 키로 되돌립니다 — 깊이 제한 없음.","ladder.rung.v0.5.0":"소리가 난다. 생성기 뒤의 샘플러, 어느 파트에나 올릴 수 있는 자신의 원샷, 그리고 플러그인 안에서 울리는 트랜스포트.","ladder.rung.v0.5.5":"악기를 연주한다. 파트마다 신시사이저, 악기와 장르로 훑을 수 있는 2,729,088개 사운드의 팩토리 라이브러리, 샘플 팩 제작기, 그리고 언제든 연주할 수 있는 건반.","ladder.rung.v0.5.7":"방대하고 매우 사실적인 라이브러리. 스물네 개의 새 합성 엔진과 750개의 새 악기 — 전부 975개. 콘서트 그랜드와 현악 섹션부터 모델링된 아날로그 회로까지, 하나하나 그 이름의 실물과 견주어 측정했습니다. 1,614,600개의 사운드, 그런데도 당신 디스크에는 파일이 하나도 없습니다.","ladder.rung.v0.6.0":"나만의 샘플 라이브러리. 미리 듣기가 되는 폴더 트리, 별표 즐겨찾기, 패드로 끌어 놓기, 역재생 — 그리고 MIDI 파일을 놓으면 안에 어떤 파트가 있는지 스스로 알아냅니다.","ladder.rung.v0.7.0":"DAW 같은 편곡 화면. 자신의 노트로 그려지는 클립, 확대, 다중 선택, 잘라내기와 복제 — 그리고 곡 전체를 밖으로 끌어내기, 파트마다 한 트랙.","ladder.rung.v0.8.0":"67개 장르, 2,000명의 아티스트. 전체 스타일 목록 — 주류 옆의 언더그라운드 — 하나하나 손으로 쓴 스타일 모델입니다. 67개 장르가 완성되어 있고 1,250명의 아티스트와 프로듀서도 그렇습니다. 나머지는 연구 자료에서 한 권씩 부호화하고 있습니다.","ladder.rung.v0.9.0":"다듬기와 견고화. 모든 상태를 설계하고 모든 경계 상황을 처리했습니다: 접근성, HiDPI, 충돌 안전성, 3초 미만의 콜드 스타트.","ladder.rung.v1.0.0-beta":"기능 완성. 1.0이 약속하는 모든 것에 협업 룸과 휴대전화 동반자 Freally MixSir을 더한 것. 여전히 내려받기는 없습니다 — 손으로 검증되는 빌드입니다.","ladder.rung.v1.0.0RC":"릴리스 후보. Re-Dream이 도착합니다 — 생성은 모두 네 개로 옵니다. 지금 가진 테이크와 그 뒤에 꿈꾼 셋, 하나가 파트를 바꿔치기 전에 트랙 안에서 들어 봅니다. 그다음 손으로 하는 테스트 한 바퀴를, 실제 하드웨어의 실제 DAW에서 처음부터 끝까지 돌립니다.","ladder.rung.v1.0.0":"다운로드 시작. 다섯 생성기 전부에 송 모드, 협업 룸, MixSir, 모든 형식, 세 플랫폼 모두에서. 누구나 설치할 수 있는 첫 빌드 — 최적화 한 바퀴, 단순화 한 바퀴, 코드 리뷰, 보안 리뷰를 거치고, 자체 호스팅 지속적 통합 러너 두 개가 모두 초록일 때.","index.daba7f83":"<strong>아직 내려받을 것이 없습니다.</strong> <strong>다음은 v1.0.0RC입니다</strong>. 지금 손으로 테스트하고 있습니다 — 모든 호스트, 모든 OS, 그리고 어떤 테스트 스위트도 판단할 수 없는 것들까지. 누군가의 세션 안에서 반쯤만 동작하는 플러그인은 아예 없는 것보다 나쁘므로, 그 매트릭스가 모두 초록이 되었을 때 배포하며 그 전에는 배포하지 않습니다.","honest.title":"대부분의 사이트가 맨 아래에 적어 두는 것들","index.25a8716e":"엔진은 규칙 기반이며 학습된 것이 아닙니다","index.644f2e23":"이 제품에는 <strong>AI가 없습니다</strong>. 모델 없음, 학습 데이터 없음, 추론 없음, 생성 중 네트워크 호출 없음. 엔진은 공개된 연구에서 끌어낸 손으로 쓴 스타일 매개변수를 읽는 결정론적 절차 코드입니다. 이것은 기술적 설계이면서 동시에 법적 설계입니다: 여기에는 복사된 MIDI도, 샘플링된 오디오도, 누군가의 음반을 옮겨 적은 것도 없고, 특정 곡을 다시 만들어내는 기능도 없습니다. 아티스트 이름은 스타일을 설명하는 참조일 뿐입니다.","index.2419a115.t":"이것으로 만든 음악은 당신 것입니다","index.2419a115.b":"사용료도, 출처 표기 의무도 없습니다. Freally MIDI Master 자체는 독점 소프트웨어로 모든 권리가 보유되어 있고, 소스 코드는 비공개입니다 — 재배포할 수 없습니다. 오픈 소스가 <em>아닙니다</em>.","honest.names.title":"이름은 스타일을 나타냅니다","index.7e9d277b":"Freally MIDI Master의 아티스트와 프로듀서 이름은 음악 스타일을 가리키는 설명적 참조이며 그 이상이 아닙니다. 어떤 제휴, 보증, 저작 관계도 암시하거나 주장하지 않습니다. 모든 패턴은 손으로 쓴 스타일 매개변수에서 절차적으로 생성되며, 어떤 녹음에서도 MIDI, 오디오, 데이터를 복사하지 않습니다. 모든 상표와 이름은 각 소유자의 것입니다. <a href=\"legal/disclaimer.md\">전체 면책 고지 읽기</a>.","index.cf01481f":"개인정보","index.a4c6de24":"계정 없음. 원격 측정 없음. 당신, 당신의 프로젝트, 당신의 결과물에 관한 어떤 것도 전송되지 않습니다. 생성, 재생, 가져오기, 내보내기가 완전히 로컬입니다.","index.6a3c2dd2.t":"플러그인은 바깥으로 나가는 연결을 전혀 만들지 않습니다","index.6a3c2dd2.b":"예전에 있던 둘 — 시작 시 업데이트 확인과 선택적 충돌 보고 — 은 데스크톱 앱의 것이었고 그것과 함께 제거되었습니다. 플러그인은 플러그인을 설치하는 사람이 설치하고 갱신합니다. 약속이 아니라 두 개의 빌드 관문으로 강제됩니다: <strong>플러그인에는 HTTP 클라이언트가 하나도 컴파일되지 않습니다</strong> — 지금도 그렇습니다. 협업 서비스에는 별도의 프로그램이 닿고, 당신의 DAW가 로드하는 플러그인은 결코 닿지 않습니다 — 그리고 화면 자체도 커밋마다 끝까지 돌려지며, 기기 밖으로 요청을 한 번이라도 시도하면 실패합니다. 충돌 보고는 당신의 디스크에 기록되고 어디로도 보내지지 않습니다.","index.1497b93b.t":"웹 앱은 네트워크로 전달되지만, 당신이 만드는 것은 아닙니다","index.1497b93b.b":"페이지는 받아와야 합니다 — 앱 자체와, 그것이 생성에 쓰는 스타일 데이터. 그것이 전부입니다. 생성은 당신의 기기, 당신의 브라우저에서 돌아갑니다. 당신의 비트, 시드, 가져온 모든 것은 거기 남고 절대 올라가지 않습니다. 한 번 방문한 뒤에는 네트워크를 끊어도 탭이 동작하며, 이는 대부분의 소프트웨어가 이루는 것보다 오프라인에 가깝습니다.","index.40df2f36.t":"협업만이 유일한 예외이고, 그마저 당신이 쓸 때만입니다","index.40df2f36.b":"룸은 당신의 기기를 초대한 사람과 직접 연결합니다. 누군가를 친구로 저장하면 작은 서비스가 그가 접속 중인지 알려줄 수 있습니다 — 그 서비스가 듣는 것 중 값나가는 것은 없습니다: 몇 분마다 바뀌는 키와, 둘만 가진 비밀로 암호화된 주소뿐입니다. 그것을 읽을 수도, 누가 있는지 나열할 수도, 누가 누구를 아는지 알아낼 수도 없습니다. 끄거나 친구를 저장하지 않으면 대신 코드를 붙여 넣게 됩니다 — 룸은 원래 그렇게 동작합니다.","index.b5d5c2d0.t":"앞으로 올 한 가지를, 나올 때가 아니라 지금 밝혀 둡니다","index.b5d5c2d0.b":"협업 기능 — 룸. 개발 중이고 오늘은 어떤 것도 이를 설치하지 않습니다 — 은 두 사람이 직접 연결되기 전에 당신 기기의 공개 주소를 알아야 하고, STUN 서버는 바로 그 일을 합니다. 이것이 들어오면 룸을 열거나 들어갈 때 그런 서버에 접속합니다. 이 빌드는 Cloudflare와 Google을 지목합니다. 그런 서버가 알게 되는 것은 어떤 주소가 WebRTC 앱을 쓴다는 사실뿐이며, 누구와 이야기하는지도 무엇을 보내는지도 알지 못합니다. 그리고 룸을 열거나 들어가기 전까지는 아무 곳에도 접속하지 않습니다. 위의 문장은 오늘 배포되는 플러그인에 대해 여전히 사실입니다.","site.tagline":"스타일에 충실한 MIDI를, 지금 작업 중인 트랙 위에 만들어 줍니다.","footer.licence":"독점 소프트웨어 — 모든 권리 보유. © Mike Weaver. 지금은 무료로 사용할 수 있지만, 향후 버전은 판매될 수 있습니다. 오픈소스는 아닙니다.","footer.yours":"이것으로 만든 음악은 당신 것입니다. 사용료도, 출처 표기 의무도 없습니다.","features.512c7b09":"여태 만들어진 가장 완전한 MIDI 생성기 — 그리고 한 푼도 들지 않습니다.","features.d19d4e76":"2,413개의 아티스트·프로듀서 스타일. 1,648개의 악기. 파트마다 9,600만 가지가 넘는 서로 다른 테이크. 어떤 오디오 파일이든 MIDI로. 어떤 아이디어든 넷으로 다시 꿈꾸기. 곡 하나를 통째로 편곡. <strong>모든 기능을, 모두에게, 지금은 무료로.</strong>","features.5e30071b":"여기의 모든 숫자는 배포되는 제품과 그 테스트 스위트에서 센 것입니다. 어림한 것도 없고, 올려 잡은 것도 없습니다.","featuresPage.numbers.models":"스타일 모델","featuresPage.numbers.artists":"아티스트","featuresPage.numbers.producers":"프로듀서","featuresPage.numbers.instruments":"악기","featuresPage.numbers.takes":"파트당 테이크","featuresPage.numbers.languages":"언어","featuresPage.numbers.ai":"AI 모델","featuresPage.numbers.price":"현재 가격","features.2fb7a96e":"지금은 무료입니다. 전부.","features.6b604c8e":"모든 기능을, 모두에게. 유료 등급 없음, 라이선스 키 없음, 앱 내 구매 없음, 구독 없음, 만료되는 체험 없음, 좋은 부분을 붙잡아 두는 ‘Pro’ 버전 없음. 이는 이 버전의 라이선스 계약에 적혀 있습니다: <em>“본 소프트웨어는 완전한 형태로 무료로 제공된다.”</em> <strong>그리고 이것으로 만든 음악은 당신 것입니다</strong>. 사용료도, 출처 표기 의무도 없습니다.","features.a5a8c798":"대표 기능","features.65a59ac5":"장르가 아니라 이름을 검색하세요","features.177ce0e6":"한 칸에 2,413명의 아티스트, 프로듀서, 장르 — 별명으로도, 오타가 있어도 찾습니다. 아무것도 누르기 전에, 그 선택이 무엇을 <em>하는지</em> 알려줍니다: 시대, 템포 범위, 기울어지는 조성, 이름으로 표시된 무드, 그리고 어떤 파트를 쓰고 어떤 파트를 쓰지 않는지. 카운터멜로디를 쓰지 않는 아티스트는 그 탭에 침묵으로 답하지 않고 그렇다고 말합니다.","features.c7e63f3a":"Re-Dream — 같은 아이디어를, 다르게","features.b9301e2e":"다시 굴리면 다른 아이디어가 나옵니다. <strong>Re-Dream</strong>은 같은 아이디어를 다르게 줍니다. 생성은 모두 네 개로 도착하고 — 지금 가진 테이크와 그 뒤에 꿈꾼 셋 — 하나하나를 <em>당신의 트랙 안에서</em>, 당신의 드럼과 808에 맞춰 듣습니다. Re-Dream은 원본 어택의 <strong>79%</strong>를 공유하고, 새 시드 셋은 35%를 공유합니다. 그것은 주장이 아니라 테스트 스위트의 관문입니다. 파일에도 통합니다: 브라우저에서 <code>.mid</code>를 고르면 랙이 생성이 아니라 그 파일에서 채워집니다.","features.a4d9cbed":"어떤 오디오 파일이든 MIDI가 됩니다","features.5a6369dd":"<em>어떤</em> 샘플이든 — WAV, AIFF, FLAC, MP3, M4A, OGG — 생성기에 끌어다 놓으면 노트로 돌아옵니다. 어택, 템포, 루프 자체의 길이, 음높이, 드럼 내용까지 모두 측정합니다. 그리고 각 파트는 <em>왜</em> 그곳으로 보내졌는지 말해 주므로, 잘못된 추측은 나중에 알게 되는 일이 아니라 한 번의 클릭으로 돌리는 일이 됩니다.","features.fdfc6809":"다섯 생성기와 곡 하나 전체","features.fbe4c84f":"드럼 · 멜로디 · 카운터멜로디 · 베이스라인 · 코드 — 그리고 송 모드. 아티스트 <em>자신의</em> 형식 하나를 뽑아 편집할 수 있는 타임라인에 그립니다. 길이를 바꾸고, 복제하고, 마음에 드는 것을 잠그고, 나머지를 건드리지 않고 한 구간만 다시 굴립니다.","features.d4dc7d3d":"악기이기도 합니다","features.5c924fb6":"<strong>69개 장르에 걸친 1,648개 악기</strong>를 가진 폴리포닉 신시사이저이고, 멜로디 계열 생성기는 각자 자기 것을 연주합니다 — 하나를 나눠 쓰는 것이 아니라 동시에 네 목소리. 어느 것도 샘플 라이브러리가 아닙니다: 모든 사운드가 다섯 정수로 된 주소여서, 전체가 프로젝트 파일 안의 숫자 몇 개입니다.","features.3f42ac73":"그리고 연주해 넣을 수 있습니다","features.b9fcfc0e":"화면 건반, 두 번째 건반이 되는 컴퓨터 키, 그리고 채널 필터·트랜스포즈·옥타브·벤드 범위·벨로시티 곡선을 갖춘 자신의 MIDI 컨트롤러. 녹음을 누르면 연주한 것이 그 파트의 클립에 떨어집니다 — 루프 끝을 넘겨 붙잡은 노트는 여전히 <em>하나의</em> 노트이고, 다시 녹음하면 대체가 아니라 겹쳐 쌓입니다. 피치 휠은 <strong>모든</strong> 악기를 구부립니다. 물리 모델링된 것들까지도: 종의 부분음과 기타의 줄은 함께 움직이고, 노트를 따라가지 않는 것들 — 바이올린의 통, 목소리의 포먼트 — 은 있어야 할 자리에 남습니다.","features.f3789702":"같은 엔진이 쓴 5,085개의 MIDI 루프","features.68dac5bc":"팩토리 팩: 멜로디, 베이스라인, 코드, 카운터멜로디, 드럼 루프, 퍼커션 루프, 장르별로. ↑/↓로 훑으면 닿는 것마다 바로 울립니다. 하나를 생성기에 끌어다 놓으면 거기 떨어져 올바른 파트로 나뉘고, 밖으로 끌면 클립으로 DAW에 들어갑니다. 9메가바이트의 <em>노트</em> — 남의 녹음 1기가바이트가 아닙니다. 하나하나 우리 자신의 생성기와 모델이 썼습니다.","features.99073b05":"남의 훅을 건네주지 않습니다","features.77e297a3":"모든 멜로디는 <em>당신이 듣기 전에</em> 잘 알려진 선율 윤곽의 표와 대조되며, 일치하는 테이크는 버려지고 다시 뽑힙니다. 표에는 단방향 지문만 있고 노트 데이터는 전혀 없습니다 — 훅을 조옮김해도 숨길 수 없으며, 다른 누가 쓴 것은 하나도 제품에 들어 있지 않습니다.","features.05de2492":"잠그고, 다시 굴리고, 되찾기","features.8347a3e6":"마음에 드는 것을 잠그고 나머지를 다시 굴립니다 — 잠긴 레인은 생성을 몇 번 눌러도 노트 하나까지 그대로 돌아옵니다. 생성마다 시드가 있습니다: 복사하고, 붙이고, 되찾으세요. 그리고 모든 것에 무제한 되돌리기. 되돌리기 항목이 노트가 아니라 입력값이기 때문입니다.","features.5ec34078":"AI 없음. 모델 하나도 없음.","features.f28580e7":"한계가 아니라 설계입니다. 위에서 아래까지 규칙, 측정, 시드가 있는 무작위성. 그리고 모델을 몰래 들여올 수 있는 의존성을 거부하는 빌드 관문. 그것이 재현성, 설명 가능성, 그리고 변호할 수 있는 출처를 줍니다: 누구의 녹음으로도 학습하지 않았습니다. 애초에 아무것도 학습하지 않았기 때문입니다.","features.79dacbd4":"주요 MIDI 생성기와 나란히","features.c9427ee1":"각 제품이 스스로 공개한 기능 목록에서 정리했습니다.","featuresPage.compare.feature":"기능","features.3e8248e3":"가격","features.97ef455a":"현재 무료","features.dc9d4584":"유료","features.8fde48f3":"구독","features.a036b01a":"이름을 밝힌 아티스트／프로듀서 스타일","featuresPage.compare.legend.yes":"전부","featuresPage.compare.legend.no":"제공하지 않음","features.a52b7c6e":"장르만","featuresPage.compare.legend.partly":"부분","features.37d67e95":"라이선스 명단","features.88048f2f":"드럼 <em>과</em> 멜로디, 베이스, 코드, 카운터멜로디","features.a69f56a4":"다섯 모두","features.0f8398e4":"드럼만","features.5916033f":"편집할 수 있는 타임라인 위의 곡 전체 편곡","features.73ab2ff8":"<strong>오디오 파일 → MIDI</strong>, 어떤 샘플이든","features.400bace7":"감지","features.11963ece":"MIDI 파일 → 다섯 파트로 나뉘고, 각자 이유를 설명","features.cc1b6bf2":"<strong>Re-Dream</strong> — 같은 아이디어를, 다르게","features.b21d091f":"모프","features.75f1827c":"재현되는 시드 — 붙이면 돌아옵니다","features.215a67ab":"그냥 연주해도 되는 내장 신스","features.891ee051":"자신의 샘플을 어느 레인에나","features.1cc2b417":"훅 검사 — 남의 멜로디를 거부","features.ddfa7bdc":"마음에 드는 것을 잠그고, 나머지를 다시 굴리세요","features.2cb5ea83":"<em>당신이</em> 별을 단 테이크로 스타일을 학습","features.dce5f5da":"머신러닝 없음","features.5a67578e":"완전히 오프라인으로 동작, 계정 없음, 원격 측정 없음","features.b3f15e02":"클라우드","features.ceec1655":"<strong>어디에도 AI／머신러닝 없음</strong> — 감사할 수 있는 규칙","features.b72eae1f":"푸시마다 검사","features.716f8c55":"실시간 협업 룸","features.f75444a3":"18개 언어","features.a2295f23":"모든 것에 무제한 되돌리기","features.036b5f21.t":"한 줄로 말하면","features.036b5f21.b":"저 표의 다른 모든 제품은 이 제품이 하는 일의 일부를 하려고 당신에게 돈을 요구합니다. 이 제품은 아무것도 요구하지 않고 전부 합니다.","features.3f4902cc":"비교는 각 제품이 공개적으로 문서화한 기능 목록에서 정리했습니다. 제품은 바뀌므로 정정은 환영합니다.","features.d452e239":"왜 지금의 모습인지","features.87e13091":"재현됩니다","features.75b8dd39":"같은 시드는 같은 노트를 줍니다. 오늘도, 5년 뒤에도. 학습된 것은 그것을 약속할 수 없습니다.","features.20690c04":"설명됩니다","features.8d02c9f7":"어떤 생성이든 자신을 만든 매개변수를 말할 수 있습니다. 가중치가 아니라 매개변수가 있기 때문입니다.","features.4fd9fc99":"변호할 수 있는 출처","features.489d6eaf":"누구의 녹음으로도 학습하지 않았습니다. 애초에 아무것도 학습하지 않았기 때문입니다. 연구 자료가 준 것은 분포뿐이며, 노트 데이터도 오디오도 한 번도 없었습니다.","features.0f211ed0":"당신의 기기에 남습니다","features.94aff5cf":"계정 없음, 로그인 없음, 원격 측정 없음, 클라우드 왕복 없음. 비행기에서도 동작합니다. 당신의 샘플, MIDI, 연주, 프로젝트는 디스크를 떠나지 않습니다 — <strong>샘플 한 바이트도 회선을 건너지 않습니다</strong>. 협업 룸 안에서도 그렇습니다.","features.e6a1356b":"DAW를 따라갑니다","features.e3a8277a":"플러그인은 블록마다 호스트의 템포와 박자를 읽으므로, 패턴은 <em>당신의 곡을 위해</em> 생성됩니다 — 140에서 쓰인 트랩은 92 BPM 프로젝트에서 92로 나옵니다. 직접 템포를 고정하면 당신 것이 이깁니다.","features.7142b88f.t":"그 9,600만에 대하여","features.7142b88f.b":"측정한 값이고 마케팅이 아닙니다. 테스트 스위트는 모델마다 200개의 시드를 렌더하고, 하나의 테이크에서 <strong>200번 뽑아 199개의 서로 다른 Re-Dream</strong>을 측정합니다. 두 숫자 모두 200개 표본에서 바닥나지 않으므로 둘 다 <em>하한</em>입니다: ≥200 생성 × ≥199 Re-Dream ≈ 모델마다 파트마다 40,000 테이크, 그리고 40,000 × 2,413 모델은 9,600만을 넘습니다 — <em>파트당</em>, 게다가 네 멜로디 파트가 서로 조합되기 전의 값입니다. 우리는 일부러 하한만 말하고 총계는 결코 말하지 않습니다: 총계는 코드가 증명할 수 없는 상한이 되고, 바닥나지 않는 영감을 끝을 상상할 수 있는 목록으로 바꿔 버립니다.","features.21cc118f":"아직 오지 않은 것","features.0b765e69":"분명히 적습니다. 빈틈을 감추는 기능 목록은 읽을 가치가 없기 때문입니다.","featuresPage.limits.title":"아직 끝나지 않은 것","features.3311e0fb":"<strong>macOS와 Linux의 바깥으로 끌기</strong>는 작성되어 켜져 있지만 아직 실제 DAW에 놓아 본 적이 없습니다. Windows에서는 해 보았습니다. 내보내기는 어느 쪽에서든 모두 동작합니다.","features.7a359bb4":"협업 룸의 <strong>전역 단축키, 화면 공유, 카메라</strong>.","features.fa2456cd":"<strong>v1.0.0RC가 곧 나오며, 내려받기도 함께 열립니다.</strong> 그때까지 “어디서 받을 수 있나요”에 대한 정직한 답은 <em>아직은 아니다</em>입니다.","documentation.ca365831":"플러그인이 하는 모든 일과, 무엇을 연주할지 어떻게 정하는지.","documentation.e4253178":"형식과 호스트","documentation.e3843261":"설치","documentation.61c43d0a":"핵심 루프","documentation.40f89a05":"스타일 목록","documentation.ba8c0def":"무드","documentation.197723c7":"나만의 스타일, 그리고 학습시키기","documentation.bd31a893":"드럼 패드","documentation.f3aaedd4":"샘플 브라우저","documentation.4a0779eb":"MIDI 파일 끌어다 놓기","documentation.ec0e4ac2":"생성기","documentation.c1e2865a":"송 모드","documentation.04770da9":"악기","documentation.c20403bd":"바운스한 오디오","documentation.a70dab9e":"DAW로 가져가기","documentation.905e63d9":"템포, 조성, 자동 동기화","documentation.05bb0a4d":"시드와 재현성","documentation.e709e76f":"프리셋","documentation.9e2759d7":"패턴 라이브러리","documentation.874a5339":"내 테이크, 그리고 드럼 잠그기","documentation.b7a3d0f4":"세션 상태","documentation.26669547":"키보드 단축키","documentation.148f83d6":"독립 실행 버전","documentation.0d1db92c":"개인정보와 네트워크","documentation.9091f25a":"실제로 자주 묻는 질문","documentation.70252a52":"버그 신고","documentation.fef8e889":"라이선스","documentation.1f0efc8f":"Freally MIDI Master는 <strong>CLAP</strong> 플러그인입니다. VST3와 AU는 따로 구현한 것이 아니라 거기서 투영되며, 그 덕분에 CLAP을 지원하지 않는 호스트에서도 로드할 수 있습니다.","documentation.3960ec4c":"호스트","documentation.041a5dec":"형식","documentation.bae7d5be":"상태","documentation.2a47e9fb":"Ableton Live 12","documentation.20a69fa8":"VST3","documentation.c21b9338":"로드되고 생성됨","documentation.3e592955":"FL Studio","documentation.51df4626":"CLAP","documentation.54e5b246":"Reaper · Bitwig · Logic","documentation.7fa841a9":"CLAP / VST3 / AU","documentation.864e8b1c":"아직 테스트 안 됨","documentation.6141642e":"DAW 없음","documentation.1d10323c":"독립 실행형","documentation.fdd933a8":"자체 창에서 실행","documentation.7d883e08":"플러그인은 당신이 꽂아 넣은 트랙에 노트를 쓰고 <strong>소리도 직접 냅니다</strong> — 드럼은 자체 킷으로, 멜로디 파트는 각자 자신의 악기로. 들으려고 어디로 라우팅할 필요가 없습니다.","documentation.a8d36300":"<strong>내려받기는 1.0에서 열립니다.</strong> 그 전에는 설치 프로그램도, 베타도, 미리보기 빌드도 없습니다 — 누군가의 세션 안에서 반쯤만 동작하는 플러그인은 아예 없는 것보다 나쁘므로, 모든 호스트와 모든 OS에서 QA 매트릭스가 초록이 되었을 때 배포합니다.","documentation.c5ebdb97":"1.0이 나오면 각 형식이 설치되는 위치:","documentation.de8aa862":"OS","documentation.26d9c28d":"Windows","documentation.e59a23ba":"<code>%COMMONPROGRAMFILES%\\CLAP</code>","documentation.72e6c218":"<code>%COMMONPROGRAMFILES%\\VST3</code>","documentation.cd6fdcbf":"macOS","documentation.75bb9363":"<code>~/Library/Audio/Plug-Ins/CLAP</code>","documentation.9e8fc2e4":"<code>~/Library/Audio/Plug-Ins/VST3</code>","documentation.83ad8510":"Linux","documentation.f81f810e":"<code>~/.clap</code>","documentation.48df6728":"<code>~/.vst3</code>","documentation.fdbefea1":"<strong>누군가를 고르세요.</strong> 스타일 목록 칸에 이름을 입력합니다 — 아티스트든 장르든 상관없습니다.","documentation.98f5460e":"<strong>생성하세요.</strong> 패턴은 당신 프로젝트의 템포와 조성에 맞춰 만들어집니다.","documentation.e1f3b866":"<strong>들어 보세요.</strong> DAW에서 재생을 누르세요 — 노트는 이미 트랙 위에 있습니다.","documentation.d9b0f0a8":"<strong>다시 굴리거나 남기세요.</strong> 생성마다 복사해 두었다가 다시 불러올 수 있는 시드가 붙어 있습니다.","documentation.f8d5c8c2":"대부분의 MIDI 생성기는 <em>장르</em>로 생각합니다. ‘트랩’은 ‘Metro Boomin’이 아니고, 주류 도구 중 OsamaSon을 들어본 것은 하나도 없습니다. Freally MIDI Master는 <strong>아티스트</strong>로 생각합니다 — 하나하나가 하이햇 롤의 문법, 808 슬라이드의 움직임, 스윙, 음역, 구간 배치를 기술하는 손으로 쓴 스타일 매개변수의 묶음입니다.","documentation.4f2277e8":"아티스트는 <strong>입력하면 자동 완성되는 칸 하나</strong>로 찾습니다. 입력을 시작하면 치는 대로 좁혀집니다 — 주류 목록, 언더그라운드 목록, 별명, 오타까지 아울러서. 중간에 멈추고 다른 곳을 클릭하면 가장 잘 맞는 것을 고르므로, 아무것도 선택되지 않은 채 남는 일은 없습니다. 대신 화살표를 누르면 전부 보여 줍니다.","documentation.a84eb15c":"같은 칸에 <strong>아티스트와 장르가 함께</strong> 나열되고 행마다 어느 쪽인지 표시되므로, ‘UK Drill’이 사람인지 스타일인지 미리 알 필요가 없습니다. 하나를 고르면 바로 아래에 세부 정보가 나타납니다 — 시대, 활동하는 장르, 기울어지는 <strong>템포 범위</strong>와 조성, 이름으로 표시된 무드, 그리고 <strong>어떤 파트를 쓰고 어떤 파트를 쓰지 않는지</strong> — 생성을 누르기 <strong>전에</strong>. <strong>장르는 둘러보기 필터이지 생성의 단위가 아닙니다</strong> — 다만 장르 자체도 실제 스타일 모델이어서 그 자체로 생성할 수 있습니다.","documentation.2e81e526":"그 마지막 줄은 보기보다 중요합니다. 카운터멜로디를 쓰지 않는 아티스트는 그 탭에 <em>침묵</em>으로 답하며, 그것이 옳습니다 — 그들은 카운터멜로디를 쓰지 않으므로 그들 대신 지어내는 것도 없습니다. 패널이 그렇다고 말해 주기 전에는, 알아내는 유일한 방법이 생성을 누르고 빈 롤을 쳐다보는 것이었습니다.","documentation.c67e0e46":"아티스트 이름은 <strong>스타일을 설명하는 참조일 뿐</strong>입니다. 데이터셋의 어떤 것도 복사된 MIDI, 샘플링된 오디오, 누군가의 음반을 옮겨 적은 것이 아닙니다.","documentation.b0e455fd":"아티스트는 하나의 사운드가 아닙니다. 아티스트 옆에는 <strong>무드</strong>가 있습니다 — 트랩의 <em>dark</em>, <em>bounce</em>, <em>melodic</em>, <em>minimal</em>, 붐뱁의 <em>dusty</em>, <em>jazzy</em>, <em>hard</em>, 퐁크의 <em>cowbell</em>, <em>memphis</em>, <em>brazilian</em>. <strong>아무거나</strong>로 두면 누를 때마다 그 아티스트의 폭을 돌고, 하나를 고정하면 거기에 머뭅니다.","documentation.c4de4112":"무드는 <strong>같은 작가가 다른 종류의 음반을 쓰는 것</strong>이며, 프로듀서들이 자신의 카탈로그를 설명하는 방식도 그렇습니다. 무드는 어떤 생성기가 돌기 전에 적용되므로 모든 파트가 그것을 따릅니다 — 드럼은 한 무드에, 멜로디는 다른 무드에 있게 될 방법은 없습니다.","documentation.4e322996":"<strong>아티스트는 그 아티스트가 실제로 하는 무드만 내놓습니다.</strong> 무드는 다른 모든 것과 같은 계보를 따라 상속되므로, 한 아티스트의 무드가 다른 아티스트에게 제시될 경로는 없습니다. 스타일에 없는 무드를 요청하면, 조용히 다른 것을 생성하는 대신 이름을 들어 그렇다고 말합니다.","documentation.8b53323c":"<strong>나만의 작업 방식</strong>은 왼쪽 레일 맨 위, 모든 것보다 위에 있습니다. 아무 아티스트나 장르에서 출발해 템포 범위, 스윙, 하이햇 밀도, 멜로디 밀도, 음계를 조정하고 당신의 이름으로 저장하세요. 스타일 목록에 <strong>내 것</strong>으로 표시되어 나타나고, 함께 실린 아티스트와 똑같이 생성되고, 잠기고, 다시 굴려지고, 내보내집니다 — 같은 형식의 같은 종류의 것이기 때문입니다.","documentation.63fa26a1":"<strong>당신이 바꾸지 않은 모든 것을 상속합니다</strong>. 바탕으로 삼은 아티스트가 이후 릴리스에서 받는 개선까지도요. 새 스타일은 빈 양식이 아니라 화면에 있는 비트에서 출발해 열립니다.","documentation.22b5f3cc":"마음에 드는 테이크에 그때그때 별을 다세요. 남겨 둔 것이 서른 개가 되면 <strong>학습</strong>이 그것들에 스타일을 맞춥니다 — 한 마디에 어택이 몇 개인지, 어떤 음역인지, 선율이 어떤 모양을 그렸는지 — 그리고 그 범위를 평범한 스타일 모델로 되써 넣습니다. 당신의 <code>.mid</code> 파일도 학습 자료가 될 수 있습니다.","documentation.421a3d31":"<strong>‘학습’은 맞춘다는 뜻이며, 그 안 어디에도 머신러닝은 없습니다.</strong> 다른 누구의 음악에서도 배우지 않고, 어떤 것도 당신의 기기를 떠나지 않으며, 자기 자신만 되풀이하게 될 맞춤은 저장되는 대신 이유와 함께 거부됩니다. 서른이라는 하한은 스타일이 시드 하나의 의견이 아니라 당신의 취향을 담도록 하기 위해 있습니다.","documentation.70a577ec":"<strong>당신의 샘플은 당신이 원할 때만 복사됩니다.</strong> 스타일은 당신이 지정한 원샷을 간직할 수 있어서, 원본을 옮기거나 지운 뒤에도 계속 재생됩니다. 그러면 드라이브에 사본이 하나 더 생기므로, 편집기는 무엇이든 일어나기 전에 파일이 몇 개이고 몇 메가바이트인지 알려 줍니다 — 그리고 확인란은 해제되어 있습니다. 스타일을 저장하는 것만으로는 아무것도 복사되지 않습니다.","documentation.5d689d19":"피아노 롤 위, 스테이지 맨 위쪽에 여덟 개의 패드가 가로로 놓여 있습니다. 하나하나가 드럼 레인이며, 이름과 지금 올라 있는 것, 그리고 들리는지 알려 주는 점이 있습니다 — <strong>들리면 초록, 음소거면 빨강</strong>.","documentation.86cb89b2":"패드를 누르면 음소거하거나 해제합니다. 패드 위쪽 가운데의 <strong>재생</strong>을 누르면 그 소리 하나만 따로 들립니다. 브라우저에서 <strong>샘플을 패드 위로 끌어다 놓으면</strong> 당신의 원샷이 그 자리에 들어가고, 더블클릭하면 파일을 고를 수 있습니다. 셔플 버튼은 지금 둘러보는 폴더에서 그 패드를 다시 뽑고, ✕는 내장 사운드로 되돌립니다.","documentation.aaa1fd33":"패드마다 <strong>레인 이름 자체가 선택기</strong>입니다 — 여덟 개 중 어느 것이든 플러그인이 가진 서른일곱 개 레인 중 어느 것으로든 바꿀 수 있습니다. 두 패드가 한 레인을 함께 쓸 수 있어 스네어를 겹칠 수 있지만, 세 번째는 거부됩니다. 배치는 <strong>아티스트마다</strong> 기억되므로, 만들어 둔 스타일로 돌아오면 패드가 지정한 샘플과 함께 떠날 때 모습 그대로 복원됩니다.","documentation.d25c3d2f":"<strong>카테고리에서 열립니다</strong> — 장소마다 한 행이고, 각 행에 안에 얼마나 들어 있는지 적혀 있으며, 그 안으로 들어갑니다. 악기와 네 개의 팩토리 확장은 내장 라이브러리의 선반이고, 드럼 팩에는 함께 실린 열한 개의 킷과 그 407개 원샷이, 팩토리 팩에는 5,085개의 MIDI 루프가 팩별로 들어 있습니다. 그 아래에 <strong>+ 폴더 추가</strong>와 당신이 추가한 폴더들이 각자의 이름으로 놓입니다.","documentation.40db79d3":"<strong>행의 숫자는 선반 전체</strong>이지 필터를 통과한 수가 아니므로, 칩을 눌러도 바뀌지 않습니다. 행은 열여덟 개 언어 중 지금 쓰는 언어의 사전순으로 정렬됩니다. 드라이브가 뽑힌 폴더는 자리를 지키며 색만이 아니라 글자로 <em>사용할 수 없음</em>이라고 표시되고, 여전히 제거할 수 있습니다 — 샘플 디스크를 뽑은 프로듀서가 라이브러리를 떠난 것은 아니니까요.","documentation.21e024db":"장소 안에서는 목록 위의 화살표로 폴더를 오가고, 브레드크럼으로 원하는 단계에 곧장 건너뜁니다. 라이브러리는 프로젝트가 있든 없든 다음에 앱을 열 때 그대로 돌아옵니다.","documentation.6324e27a":"<strong>화살표 키로 돌아다닙니다.</strong> <kbd>↑</kbd>와 <kbd>↓</kbd>는 행 사이를 움직입니다. 폴더에서는 <kbd>→</kbd>가 열고 <kbd>←</kbd>가 닫습니다 — 이미 닫힌 폴더에서 <kbd>←</kbd>는 그 폴더가 속한 가지를 닫으므로, 밖으로 되돌아 나오는 길이 됩니다. <em>파일</em>에서는 같은 두 키가 그것을 <strong>앞으로, 그리고 거꾸로</strong> 재생합니다. 미리 듣기는 트랜스포트를 시작하거나 멈추지 않습니다.","documentation.33491a5d":"<strong>무엇이든 별표하세요</strong> — 샘플, 원샷, MIDI 파일. 별은 이름 왼쪽에 있습니다: 누르기 전에는 윤곽선, 누르면 꽉 찬 노란색. 별표한 파일은 트리 아래 목록에 모이고, 하나를 클릭하면 루트에서 그 파일까지 사이의 모든 폴더가 열려 그것을 보여 줍니다. 그 폴더가 더 이상 당신이 추가한 폴더가 아니면, 대신 <strong>Windows 탐색기나 Finder</strong>에서 파일 위치를 엽니다 — 그래서 라이브러리가 어디로 옮겨 갔든 즐겨찾기에 닿을 수 있습니다. 별표를 해제하면 잊습니다.","documentation.0a36b11f":"깊이 들어가야 할 때는 브라우저가 <strong>레일 전체</strong>를 차지했다가 다시 돌려줄 수 있습니다. 오디오와 MIDI는 일부러 분리되어 있습니다: <code>.mid</code>에는 그릴 파형이 없고 드럼 패드에 놓을 수도 없으며, 패드는 나중에 실패하는 대신 손을 놓기 전에 그것을 거부합니다.","documentation.5811086b":"<strong>진짜 라이브러리를 감당합니다.</strong> 파일이 이천 개 든 폴더도 네 개 든 폴더만큼 빨리 열립니다. 실제로 보이는 행만 그리기 때문입니다 — 스크롤하면 나머지는 닿는 대로 나타납니다. <strong>필터 칸에 입력하면</strong> 트리가 일치하는 것으로 좁혀지고, 거기로 이어지는 폴더는 남습니다. 폴더 이름을 입력하면 그 아래 모든 것이 나옵니다. 칸 아래 줄은 <em>어떤 폴더를 검색했는지</em> 말해 주며, 말 그대로입니다: 플러그인은 한 번에 폴더 하나씩 읽으므로, 필터는 당신이 열어 본 폴더까지만 닿고 그 너머로는 가지 않습니다. 그렇지 않은 듯 보이는 칸은 자신이 무엇을 살펴봤는지 거짓말을 하는 셈입니다.","documentation.0c96cd67":"<strong>라이브러리 폴더가 있는 드라이브를 뽑으면 그 탭이 그렇다고 알려 주고</strong>, 옆에 <em>다시 확인</em>이 있습니다. 폴더는 라이브러리에서 빠지지 않습니다 — 드라이브를 다시 꽂고 그것을 누르면 트리가 돌아옵니다. 이전에는 그런 폴더가 그냥 열리기를 거부했고, 그것은 빈 폴더와 똑같아 보였습니다.","documentation.3de3cadc":"<strong>먼저 들어 보세요.</strong> <code>.mid</code>를 선택하면 패널에 그 안에 든 것이 나열되고, <strong>재생</strong>을 누르면 소리가 납니다 — 마침 선택해 둔 아티스트가 아니라 평범한 내장 악기로 울리므로, 같은 파일은 내일도 같은 소리를 냅니다. 드럼 레인은 음높이가 아니라 타격으로 들어옵니다. 드럼 레인의 노트 번호는 얼마나 낮은 음인지가 아니라 어떤 패드가 울리는지를 말하기 때문입니다. 소리는 파일을 클릭할 때가 아니라 처음 누를 때 만들어지므로, 루프 폴더를 <kbd>↓</kbd>로 훑어 내려가도 비용이 들지 않습니다. 프로젝트의 트랜스포트에는 절대 손대지 않습니다.","documentation.9acfff56":"브라우저에서 <code>.mid</code>를 <strong>생성기</strong> 위로 끌어다 놓으면 그 노트가 거기 떨어집니다. 대신 <strong>곡</strong> 탭에 놓으면 파일 전체가 편곡으로 들어옵니다 — 위쪽에 가로로 구간, 옆쪽에 세로로 파트 — 그리고 아무 셀이나 클릭하면 그 클립이 자기 생성기에서 열립니다. 생성된 곡을 파고들 때와 똑같습니다. 셀을 고르기 전까지는 이미 가진 어떤 것도 덮어쓰지 않습니다.","documentation.7b266d93":"여러 겹으로 된 파일은 <strong>베이스, 멜로디, 카운터멜로디, 코드, 드럼으로 나뉘고</strong>, 각 파트는 <strong>왜</strong> 그곳으로 보내졌는지 말합니다 — “GM 드럼 채널”, “코드 — 노트가 겹칩니다”, “가장 낮은 성부”, “파일 이름에서”. 잘못된 추측은 두 마디 들어가서야 알게 되는 일이 아니라 한 번의 클릭으로 돌리는 일입니다.","documentation.d544549e":"<strong>파일에 이름을 붙이면 귀담아듣습니다.</strong> <code>…-Bass.mid</code>나 <code>…Drums.mid</code>라는 파일은 이름 그대로 받아들여집니다. 플러그인이 추측하는 것이 아니라 당신이 그것이 무엇인지 말한 것이기 때문입니다. 이것은 들리는 것보다 중요합니다: 808의 MIDI 노트는 얼마나 낮게 울리는지가 아니라 <em>어떤 키가 샘플을 울리는지</em>를 말하므로, 베이스라인은 흔히 멜로디 음역에 놓이고 어떤 측정도 그것을 느린 리드와 구별할 수 없습니다. 구별할 수 있는 단 하나는 당신이 붙인 이름입니다.","documentation.02646e58":"가져온 클립은 <strong>세션의 템포를 따릅니다</strong>. 내보낸 MIDI 대부분은 템포를 전혀 담고 있지 않으며 — 파일 이름의 숫자는 데이터에 없습니다 — 플러그인은 읽지 않은 템포를 주장하지 않습니다.","documentation.2528b54c":"<strong>다섯 개의 파트 생성기, 그리고 송 모드.</strong> 송 모드는 여섯 번째 생성기가 아닙니다 — 편곡을 펼쳐 놓고 나머지 다섯을 채웁니다.","documentation.fe06eb64":"탭","documentation.f6222ac9":"만드는 것","documentation.764cb087":"<strong>드럼</strong>","documentation.d18ca618":"킥, 스네어와 오프 스네어, 클랩, 롤 문법을 갖춘 클로즈드·오픈 하이햇, 라이드, 크래시, 탐, 림, 스냅, 퍼커션, 셰이커, 탬버린, 카우벨, 우드블록 — 그리고 슬라이딩 서브. 그중 무엇을 쓰는지도 그 아티스트의 일부입니다.","documentation.f973941a":"<strong>멜로디</strong>","documentation.86e5726d":"프레이즈 구조 — 리프 루프, 질문/대답, 콜/리스폰스, 긴 아크 — 강박에서의 코드 톤 편향과 장르별 장치","documentation.4e420883":"<strong>카운터멜로디</strong>","documentation.c81554ab":"옥타브 에코, 벨 에코, 아르페지오, 응답 릭, 지속 패드를 멜로디의 빈틈에 배치","documentation.3562e4d3":"<strong>베이스라인</strong>","documentation.6763aa65":"드럼의 서브 움직임에 맞물린 저음역","documentation.677c857e":"<strong>코드</strong>","documentation.d7eb09d9":"세션의 조성과 음계 안의 진행","documentation.7c237ecf":"<strong>곡</strong>","documentation.6d9aaa02":"위의 다섯을 채우는 편곡 — 생성기가 아니라 모드","documentation.ecfc86d6":"<strong>다섯 모두 생성하고, 다섯 모두 편집할 수 있습니다.</strong> 드럼에는 패드 그리드가, 멜로디·카운터멜로디·베이스라인·코드에는 피아노 롤이 있습니다. 808이 <em>곧</em> 베이스라인인 스타일은 두 번째 저음역으로 겹치는 대신 그렇다고 말합니다.","documentation.5acc0069":"음높이는 <strong>음계 도수</strong>로 고른 다음에야 MIDI 노트로 바뀌므로, 조성 안에 머무는 것은 나중에 걸러 내는 것이 아니라 구조적인 것입니다.","documentation.eb60a3b0":"<strong>곡</strong> 탭에서 생성을 누르면 편곡 전체가 나옵니다: 아티스트 자신의 곡 형식 하나, 구간마다 파트마다 클립 하나, 그리고 그것을 음반처럼 들리게 하는 전환 — 훅이 떨어지기 전 한두 박의 침묵, 후반부의 스위치업, 페이드되는 아웃트로.","documentation.967c5bf5":"<strong>구간은 반복되는 클립을 재생합니다.</strong> 열여섯 마디 벌스는 네 마디 루프를 네 번 재생한 것이고, 모든 DAW의 어레인지먼트 뷰가 그렇게 그립니다. 같은 종류의 구간은 클립 하나를 공유합니다. 벌스 1과 벌스 2는 같은 비트이기 때문입니다 — 스위치업은 바로 그것이 규칙이기 때문에 존재합니다.","documentation.fb2dbad1":"할 수 있는 일","documentation.0c81abc8":"방법","documentation.b78ea20d":"클립 크기 조절, 복제, 삭제, 복사/잘라내기/붙여넣기","documentation.f3887844":"양쪽 가장자리 끌기, 구간 머리글 더블클릭, 그리고 일반 단축키","documentation.b4f2f858":"구간 하나 다시 굴리기","documentation.462f801c":"<kbd>R</kbd> 또는 구간 머리글의 주사위. 잠긴 클립은 그대로 둡니다","documentation.6ae2c0bb":"클립, 행, 또는 구간 전체 잠그기","documentation.d51e6c21":"셀, 파트 행, 또는 구간 머리글의 자물쇠","documentation.91c16f4e":"셀 하나만 따로 듣기","documentation.6bb5c318":"클립의 헤드폰. 그러는 동안 화면에 그렇다고 표시됩니다","documentation.7f68250f":"클립을 편집기에서 열기","documentation.9b3b8f91":"더블클릭하세요. 편집한 내용이 편곡에 다시 기록됩니다","documentation.85574b57":"구간 반복, 파트 음소거 또는 솔로","documentation.d174c5c9":"머리글의 반복 아이콘, 행의 스피커와 <kbd>S</kbd>","documentation.22fee5c2":"아티스트의 형식 중 무엇으로 만들지 고르기","documentation.9b4ae385":"구조 행의 선택기. 비워 두면 아티스트가 고릅니다","documentation.f3e4fadb":"내보내기","documentation.4ec1e842":"멀티트랙 <code>.mid</code> 하나, 또는 파트마다 파일 하나씩 폴더로","documentation.0969199e":"<strong>음소거와 솔로는 미리 듣기 컨트롤입니다.</strong> 들리는 것만 바꾸고 곡이나 내보낸 파일은 결코 바꾸지 않습니다 — 레인별 오디오 음소거와 같은 구분입니다. 재생 중에 하나를 토글해도 마커는 그 자리에 있으므로, 곡에서 위치를 잃지 않고 전환을 확인할 수 있습니다.","documentation.24a78f85":"<strong>트랜스포트는 지금 보고 있는 탭을 재생합니다.</strong> 스케줄은 하나입니다: 곡 탭은 편곡 전체를 거기에 올리고, 생성기 탭으로 돌아가면 그 탭의 클립으로 돌려줍니다. 그래서 눈에 보이는 마커가 언제나 움직이는 마커입니다.","documentation.dd323d51":"<strong>다시 굴려도 곡 안에 머뭅니다.</strong> 곡이 생성된 모드, 생성될 때의 템포와 조성, 고정해 둔 스윙을 그대로 지키고 — 다시 굴린 구간의 복제본을 포함해 다른 모든 구간은 그대로 둡니다.","documentation.920e6fd6":"<strong>스템은 MIDI로도 오디오로도, 파트별 또는 레인별로 나옵니다.</strong> 오디오 쪽은 예전에는 불가능했고, 그 이유는 짐작이 아니라 측정한 것이었습니다: 함께 실린 킷에는 네 멜로디 파트를 위한 소리가 없었으므로, 그것들을 렌더하면 무음 <code>.wav</code> 네 개를 써 놓고 스템이라고 불렀을 것입니다. 이제 킷이 생성되는 모든 레인을 맡고, 나머지는 당신의 원샷이 맡습니다. <em>곡</em> 전체는 여전히 파트마다 <code>.mid</code> 하나를 씁니다 — 몇 분 길이의 오디오를 렌더하려면 지켜볼 수 있는 진행 표시와 누를 수 있는 취소가 필요하고, 그것은 네 마디 루프를 렌더하는 것과는 다른 일입니다.","documentation.edc824f0":"<strong>파트를 DAW 트랙으로 곧장 끌어다 놓을 수 있습니다.</strong> 생성된 파트마다 오른쪽 레일에 MIDI 핸들과 오디오 핸들이 있습니다. <strong>레인별</strong>을 켜면 드럼 파트가 레인마다 핸들 하나가 되어, 하이햇만 따로 내보낼 수 있습니다. 편곡 전체도 MIDI로 끌 수 있습니다. 파일은 <code>trap - Snare - 140 BPM - C# Minor</code> 같은 이름으로 도착하고, 클립 자신의 노트가 커서에 따라붙어 무엇을 집었는지 볼 수 있습니다. <strong>지금은 Windows만</strong> — 플러그인 웹뷰 안의 HTML5 드래그는 운영체제의 파일 드래그가 아니므로, 플랫폼마다 자체 네이티브 드래그 소스가 필요합니다. macOS와 Linux는 자기 것이 작성될 때까지 내보내기를 쓰며, 아무것도 떨어뜨리지 못하는 핸들 대신 아예 핸들을 보여 주지 않습니다.","documentation.f6b5ea7d":"<strong>놓은 파일이 있는 곳.</strong> 끌기를 하면 파일을 임시 폴더에 써 두고 DAW에 그 경로를 넘깁니다. 놓은 <code>.mid</code>는 모든 DAW가 프로젝트로 복사하므로 일주일 뒤에 정리되고, 놓은 <code>.wav</code>는 경로로 <em>참조</em>되므로 절대 삭제되지 않습니다 — 계속 간직하려면 DAW의 Collect All and Save를 쓰세요.","documentation.ac9b6565":"<strong>노트뿐 아니라 소리도 냅니다.</strong> 69개 장르에 걸친 225개 악기의 팩토리 라이브러리를 가진 폴리포닉 신시사이저이고, 네 개의 멜로디 계열 생성기는 각자 자기 것을 연주합니다 — 그래서 멜로디, 카운터멜로디, 베이스라인, 코드에 서로 다른 소리를 지정하면 하나를 나눠 쓰는 것이 아니라 동시에 네 목소리를 얻습니다.","documentation.e8595ab4":"여기의 어느 것도 샘플 라이브러리가 아닙니다. 모든 사운드는 작은 주소 — 악기, 장르, 변형, 아티큘레이션, 톤 — 에서 생성되므로, 라이브러리 전체가 디스크의 기가바이트가 아니라 프로젝트 파일 안의 정수 몇 개입니다. 그 뒤에는 열세 개의 합성 엔진이 있습니다: 바이올린은 활로 켜는 현 모델이고 Rhodes는 물리 피아노 모델이며, 그래서 그 컨트롤은 패드의 것과 다르게 동작합니다.","documentation.d72a5e39":"<strong>주소마다 다른 사운드입니다.</strong> 한 장르 안 한 악기의 스물네 가지 변형은 주사위를 스물네 번 굴리는 것이 아니라 그 악기 자신의 폭을 돕니다 &mdash; 막대가 얼마나 오래 울리는지, 해머가 얼마나 세게 치는지, 현의 어디를 뜯는지 &mdash; 그리고 장르는 뒤에 붙은 필터가 아니라 모델 자체에 닿습니다: 트랩 808은 울리고 미끄러지는 반면 하우스 킥은 단단하고, 재즈 피아노는 메탈의 것보다 부드러운 해머로 칩니다. 2,729,088개 전부를 렌더해서 확인합니다.","documentation.72640dda":"SYNTH 탭","documentation.4a4148dd":"지금 다듬고 있는 생성기의 필터, 두 엔벨로프, 이펙트, 마스터 컨트롤. 위쪽의 버튼 네 개로 어느 생성기인지 고릅니다 — SYNTH 탭은 그 자체가 파트가 아닌 유일한 탭이라서 물어봐야 합니다.","documentation.9e3449fc":"악기 선반 안에서","documentation.dd09491c":"<strong>악기</strong>나 네 개의 <strong>팩토리 확장</strong> 중 하나를 열면 그 선반을 장르와 계열로 둘러봅니다 &mdash; 장르는 사전순으로 놓이고 목록은 <strong>Trap</strong>에서 열립니다. 페이지로 나뉘어 있습니다: 계열 필터 없는 장르 하나가 5,400행입니다. <strong>선반이 목록을 좁히므로</strong>, 팩토리 확장 2를 열고 건반을 고르면 제품의 모든 건반 악기가 아니라 그 팩의 건반 악기만 보입니다.","documentation.6034b304":"<strong>행을 클릭하면 재생만 하고 그 이상은 하지 않습니다.</strong> 들리는 클립은 그 악기가 가장 그 악기다운 소리를 내는 노트에서의 소리이며, 브라우저 아래 미리 듣기 플레이어에 재생헤드와 진행 시간과 함께 파형으로 그려집니다. <kbd>&uarr;</kbd>와 <kbd>&darr;</kbd>는 목록을 오가며 닿는 것마다 재생하므로, 마우스에 손대지 않고 한 계열을 귀로 훑을 수 있습니다.","documentation.a1eb5eff":"<strong>생성기에 올리는 것은 따로 누르는 일입니다</strong> &mdash; 목록 아래의 <em>&hellip;에 사용</em> 버튼, 또는 <kbd>Ctrl</kbd>/<kbd>&#8984;</kbd> + <kbd>&#9654;</kbd>. 둘 다 지금 보고 있는 탭에 떨어집니다. 악기를 고르면 <em>이전</em> 악기가 걸치고 있던 리버브, 드라이브, 게인, 엔벨로프가 지워지므로, 생성기가 연주하는 것은 미리 듣기가 연주한 것과 같습니다. 방금 들은 소리를 얻으려고 노브에 손을 뻗어야 해서는 안 됩니다.","documentation.7c97bb07":"<strong>드럼은 드럼으로, 악기는 생성기로 갑니다.</strong> 기본 악기는 신스 패치이고 드럼 레인은 원샷을 재생하므로, 단축키는 그 짝을 두고 뜻밖의 일을 하는 대신 거부합니다. <kbd>Ctrl</kbd> + <kbd>&#9664;</kbd>는 미리 듣기에서 샘플을 거꾸로 재생하며, 그런 식으로 생성기에 넣지는 않습니다 &mdash; 노트를 뒤집는 것은 피아노 롤의 일입니다.","documentation.7f76c6b2":"건반","documentation.2d0fa842":"어느 탭에서든 켜고 끌 수 있습니다. 건반 위를 클릭하고 끌거나 — 건반의 어느 높이를 누르는지가 벨로시티를 정합니다 — 타이핑 건반을 쓰세요. 텍스트 칸에 포커스가 있는 동안 타이핑 건반은 물러나 있으므로, 아티스트를 검색하는 동안 노트가 울리지 않습니다.","documentation.7a1b9f14":"옥타브나 범위를 옮기면 올 노트 오프가 전송되므로, 아래의 건반이 바뀌어도 누르고 있던 노트가 남겨지는 일은 없습니다.","documentation.5b1002aa":"건반이 창의 가운데 전체에 걸쳐 펼쳐집니다. 3, 5, 7옥타브 모두 스크롤 없이, 모든 건반에 이름이 붙습니다. C는 굵게 표시하고, 가로로 쓰기엔 너무 좁은 건반에는 이름을 건반을 따라 세로로 씁니다. 옥타브 화살표와 옥타브 수는 건반 위 막대에 있으며, 건반 버튼은 건반이 열려 있는 동안 켜집니다.","documentation.30f9d8d3":"하드웨어로 연주해 넣기","documentation.ee7a9278":"<strong>설정 &rarr; MIDI 입력.</strong> 채널 필터(또는 기본값인 모든 채널), 반음 단위 트랜스포즈, 그와 겹쳐 쌓이는 옥타브 이동, 피치 벤드 범위, 그리고 벨로시티 곡선 — 가운데보다 아래면 가볍게 쳐도 더 크게 나오고, 위면 더 세게 눌러야 합니다.","documentation.4d68e35d":"건반 끝을 넘어 트랜스포즈된 노트는 <strong>감싸 돌리지 않고 버립니다</strong>. 감싸 돌린 노트는 틀린 노트이고, 화면의 어떤 것도 그런 일이 있었다고 알려 주지 않을 것이기 때문입니다.","documentation.874b0424":"<strong>연주해 넣은 노트는 당신 것입니다.</strong> 분석되지 않고, 스타일의 일부가 되지 않으며, 무엇도 학습시키지 않습니다 — 가져온 MIDI 파일이 따르는 것과 같은 규칙입니다.","documentation.004f6eb1":"생성기 페이지의 노브","documentation.a9a17e79":"보고 있는 파트의 리버브, 딜레이, 드라이브, 볼륨, 팬. 오른쪽 레일의 파트별 편집기에도 같은 숫자가 있습니다. 두 번 보이는 한 벌의 컨트롤이지, 서로 맞춰 줘야 하는 두 벌이 아닙니다.","documentation.aac58205":"볼륨, 팬, 엔벨로프는 <em>레인</em>에 속하므로, 그 파트가 팩토리 악기를 연주하든 당신의 원샷을 연주하든 동작합니다. 리버브, 딜레이, 드라이브는 악기 자체의 이펙트에 적용되므로 팩토리 사운드가 로드되어 있을 때만 나타납니다 — 당신의 샘플 위에서는 닿을 대상이 없고, 아무것도 바꾸지 않는 컨트롤은 아예 없는 것보다 나쁩니다.","documentation.7eff58e8":"사운드 저장하기","documentation.bd3b5639":"악기를 다듬은 다음, 직접 고른 카테고리와 이름으로 저장하세요. SYNTH 탭에서 그 카테고리 아래에 나열됩니다.","documentation.857fd301":"<strong>사운드는 프리셋이 아닙니다.</strong> 오른쪽 레일의 <em>프리셋</em>은 저장된 세션 — 아티스트, 시드, 그리고 고정값들 — 입니다. <em>사운드</em>는 악기입니다. 둘은 따로 보관되며 한 목록에 함께 나오지 않습니다.","documentation.a64f42d4":"PACK — 샘플 랙","documentation.75928332":"장르와 악기를 고르고 개수를 정한 뒤 생성하세요. 원샷이 최대 25개까지 오프라인으로 렌더되며, 하나하나 클릭이 나지 않도록 다듬고 페이드를 입히고, 거의 무음으로 나온 것은 랙에 닿기 전에 버립니다.","documentation.30f4f34e":"아무 슬롯이나 재생해 들어 보세요. <strong>교체</strong>는 다른 슬롯은 건드리지 않고 한 슬롯을 다시 뽑고, <strong>&times;</strong>는 하나를 지우며, 내보내기는 남은 것을 씁니다 — 원하면 노멀라이즈와 함께. 렌더는 진행 표시줄과 취소 버튼을 갖추고 백그라운드에서 일어나므로, DAW 창은 그리기를 멈추지 않습니다.","documentation.3fb1265f":"<strong>설정 &rarr; MIDI 입력</strong>, 입력 설정 아래 — 둘 다 이 플러그인과 당신의 장비 사이를 오가는 것에 관한 것입니다. WAV 또는 AIFF, 16비트, 24비트 또는 32비트 부동소수점, 44.1, 48, 88.2, 96, 176.4 또는 192 kHz.","documentation.0682be26":"선택","documentation.769bb19e":"언제","documentation.0a30f217":"WAV 16비트","documentation.e77855ff":"기본값이며, 이 플러그인이 늘 써 온 형식입니다.","documentation.7d81c5bd":"WAV 24비트","documentation.6ce283a3":"대부분의 프로듀서가 바운스에 기대하는 것. 쓸 수 있는 범위가 6dB 더 넓습니다.","documentation.a40ce484":"WAV 32비트 부동소수점","documentation.34ccd0a3":"풀 스케일을 넘어선 것도 간직하므로, 뜨겁게 바운스한 것도 나중에 다시 끌어내릴 수 있습니다.","documentation.7f9266a3":"AIFF 16 또는 24비트","documentation.2c807357":"그것을 원하는 작업 흐름을 위해. 정수만 — 여기서 AIFF에는 부동소수점 형식이 없습니다.","documentation.30e94467":"<strong>DAW로 끌어다 놓는 루프는 이 설정과 상관없이 언제나 16비트 WAV입니다.</strong> 끌어 놓은 루프는 자기 템포를 담고 있어야 프로젝트의 속도가 아니라 올바른 속도로 워프되어 떨어지며, 그것을 담을 수 있는 것은 WAV뿐입니다. 이 설정은 목적지를 직접 고르는, <em>저장하는</em> 파일을 위한 것입니다.","documentation.e667e4fb":"<strong>길은 셋이고, 어느 것을 원하는지는 무엇을 하고 있는지에 달려 있습니다.</strong> 플러그인은 자기 트랙에서 연주하거나, 파일을 끌어내거나, 폴더로 내보냅니다.","documentation.3ac408e8":"1. 그냥 재생하기","documentation.9eccb298":"플러그인은 자신이 놓인 트랙으로 MIDI를 내보내고, 소리도 직접 냅니다 — 드럼은 자체 킷으로, 멜로디 파트는 각자 자신의 악기로. DAW에서 재생을 누르면 아무것도 라우팅하지 않고 비트가 들립니다.","documentation.25c81dca":"노트를 당신의 악기가 연주하길 원한다면, 호스트가 하는 방식대로 플러그인의 MIDI 출력을 그 악기로 라우팅하고, 그 파트에 악기를 지정하지 않은 채로 두어 파트 자체의 소리를 끄세요.","documentation.a651299f":"2. 클립 끌어내기","documentation.ba47208c":"파트 칩을 잡아 트랙 위로 끌어다 놓으세요. 기본으로는 <code>.mid</code>가 나오고, 칩을 바꾸면 오디오가 나옵니다. 편곡 전체를 끌면 파트마다 파일 하나가 나옵니다.","documentation.74b1c304":"<strong>끌어내기는 지금은 Windows에서만 됩니다.</strong> macOS와 Linux에서는 칩이 그것을 제공하지 않습니다. 동작할 수 없는 컨트롤은 아예 없는 것보다 나쁘기 때문입니다. 대신 내보내기를 쓰세요 — 같은 파일을 만듭니다.","documentation.3df20937":"끌어낸 <em>오디오</em> 루프는 자기 템포를 담고 있으므로, 프로젝트의 속도가 아니라 만들어진 속도에 맞춰 워프되어 떨어집니다. 이것은 특히 WAV의 기능이고, 그래서 끌어낸 루프는 내보내기 형식이 무엇으로 설정되어 있든 언제나 16비트 WAV입니다.","documentation.ff72e267":"3. 폴더로 내보내기","documentation.5d91da4a":"폴더를 고르면 파트마다 파일 하나를 얻습니다 — MIDI, 또는 설정한 형식의 오디오. 모든 플랫폼에서 동작하는 길이며, 편곡 전체에 쓸 길입니다.","documentation.29940c77":"호스트별","documentation.9f733253":"설치할 형식","documentation.dc3decbb":"세부 정보","documentation.e6225dc8":"Live는 CLAP을 읽지 않습니다. <code>.mid</code>를 MIDI 트랙에 놓으세요. Live는 멀티트랙 파일에서 트랙마다 클립 하나를 만듭니다.","documentation.d976ad22":"FL Studio 21.2+","documentation.c0fb74c6":"CLAP (또는 VST3)","documentation.c7b038df":"CLAP을 기본으로 읽습니다. 멀티트랙 <code>.mid</code>는 플레이리스트에 별도의 채널로 떨어집니다.","documentation.d1100b6d":"Reaper","documentation.fc15247e":"CLAP 또는 VST3","documentation.ce4fa0e2":"둘 다 받습니다. Reaper는 멀티트랙 파일을 어떻게 가져올지 추측하는 대신 물어봅니다.","documentation.82653a52":"Bitwig","documentation.600bbc6d":"CLAP이 기본 형식입니다.","documentation.fd6889aa":"Logic Pro","documentation.acdf4173":"AU","documentation.a74dbbef":"macOS 전용. Logic은 CLAP도 VST3도 읽지 않습니다.","documentation.1f04dbe6":"<strong>이 중 두 행은 확인되었고 세 행은 아닙니다.</strong> Ableton Live 12와 FL Studio에서는 로드하고 생성해 보았습니다. Reaper, Bitwig, Logic은 아직 열어 보지 않았으므로, 그 행들은 누군가 직접 지켜본 것이 아니라 각 호스트가 문서화한 내용을 설명합니다. 그중 하나를 실행해 보면 그 결과는 <code>docs/daw-matrix.md</code>에 기록됩니다.","documentation.c076a592":"플러그인은 블록마다 호스트의 템포와 박자를 읽습니다. 140에서 쓰인 트랩은 <strong>92&nbsp;BPM 프로젝트에서 92로</strong> 나옵니다 — 아티스트의 템포로 생성된 클립은 당신이 요청한 곡에 맞지 않기 때문입니다.","documentation.ab86fb82":"우선순위","documentation.15955a81":"<strong>당신의 고정값이 이깁니다.</strong> 세션 칩에서 템포를 고정하면 무엇보다 우선합니다.","documentation.32319078":"<strong>그다음은 호스트.</strong> 자동 동기화가 켜져 있으면 DAW의 템포를 씁니다.","documentation.5e24a1af":"<strong>그다음은 아티스트.</strong> 자동 동기화가 꺼져 있으면 모델 자신에 쓰인 템포가 유지됩니다.","documentation.1125e7e4":"<strong>고정값은 아티스트가 활동하는 범위 안에 묶입니다.</strong> BPM 칸은 패널에 표시된 범위에서 멈춥니다 &mdash; 끌거나 입력해서 넘어가면 가장자리에 자리 잡습니다 &mdash; 그리고 당신의 고정값에 닿을 수 없는 아티스트로 바꾸면, 그들이 결코 연주하지 않는 것을 생성하는 대신 가장 가까운 템포로 옮깁니다. 입력은 칸을 벗어날 때만 바로잡히므로, <kbd>140</kbd>으로 가는 도중의 <kbd>1</kbd>이 커서 아래에서 고쳐 쓰이지 않습니다. <strong>호스트는 결코 거기에 묶이지 않습니다:</strong> 프로젝트의 템포는 프로젝트의 것입니다.","documentation.f2eb4b94":"<strong>음계 칩은 그 아티스트가 쓰는 음계를 제시합니다.</strong> 그들의 개성을 담는 것은 선법이므로, 한 아티스트에서 고른 음계는 그것을 쓰지 않는 다른 아티스트로 옮겨 가면 모델에 되돌려집니다. 조성 칩은 일부러 제한하지 않습니다 &mdash; 조성은 조옮김, 즉 같은 음악을 다른 음높이로 연주하는 것이기 때문입니다.","documentation.638c602e":"자동 동기화는 프로젝트와 함께 저장되는 세션 설정이며, 두 가지가 아니라 세 가지 상태가 있습니다. 실행 중인 프로젝트 안에서 아티스트에 쓰인 템포에 닿으려면 그것을 끄면 됩니다.","documentation.ac4e2b0c":"생성마다 <strong>시드</strong>가 있습니다. 같은 시드, 아티스트, 세션은 언제나 바이트까지 동일한 패턴을 만듭니다 — 어떤 기기에서든, 어느 날이든. 칩에서 시드를 복사하고 다시 붙여 넣으면 비트가 돌아옵니다.","documentation.f8ac4ea5":"시드 칸을 비워 두면 매번 새 시드를 얻습니다. 그러면 칩에 실제로 쓰인 시드가 표시되므로, 숫자를 한 번도 입력하지 않았어도 마음에 든 생성을 복사할 수 있습니다.","documentation.c902e125":"결정성은 단지 의도된 것이 아니라 테스트 스위트가 강제합니다 — 저장된 프로젝트가 노트 하나 저장하지 않고 비트를 되살릴 수 있는 것도 그 때문입니다.","documentation.5d19dc54":"프리셋은 이름 붙은 세션입니다 — 아티스트, 시드, 마디 수, 고정값. 팩토리 프리셋은 바이너리에 컴파일되어 있고, 당신의 프리셋은 플랫폼의 사용자별 데이터 디렉터리에 기록되므로 어느 한 프로젝트보다 오래 남습니다.","documentation.6c29a0d2":"<strong>어떤 팩토리 프리셋도 템포를 고정하지 않습니다.</strong> 고정값은 사용자의 지시이고, 함께 실린 파일은 사용자가 아닙니다 — 템포를 고정한 팩토리 프리셋은 불러오는 순간 당신의 DAW를 무시해 버릴 것입니다.","documentation.4df575be":"마음에 드는 패턴에 이름을 붙이면 다음에도 거기 있습니다 — 어느 곡에서든, 어느 DAW에서든. 패턴 하나하나가 플랫폼의 사용자별 데이터 디렉터리에 있는 자기만의 JSON 파일이므로, 잘못 저장해도 선반 전체가 아니라 루프 하나만 잃으며, 파일을 복사하는 것만으로 백업하고, 동기화하고, 다른 사람에게 건넬 수 있습니다.","documentation.6053a251":"<strong>저장된 패턴은 소리가 아니라 노트입니다.</strong> 킷은 일부러 저장하지 않으며, 그 덕분에 &ldquo;원하는 어떤 소리로든 쓰세요&rdquo;가 주장이 아니라 사실이 됩니다: 패턴을 불러오고 킷을 바꾸면 같은 연주가 다른 샘플로 울립니다. 패턴이 충돌에서 살아남는 방법이기도 합니다 — 플러그인은 남의 프로세스 안에 살고 그것과 함께 죽으니까요.","documentation.c6f3d453":"이것은 프리셋도 아니고 프로젝트도 아닙니다. <em>프리셋</em>은 출발점이며 노트를 전혀 저장하지 않습니다. 엔진이 노트를 다시 생성하기 때문입니다. <em>프로젝트</em>는 이 곡을 기억합니다. 저장된 패턴은 당신이 남겨 둔 테이크입니다.","documentation.ca18c184":"세션의 모든 생성은 처음 것부터 간직되고, 생성기마다 따로 셉니다. <kbd>&#9664;</kbd>와 <kbd>&#9654;</kbd>로 오가며, 뒤로 가면 숫자만이 아니라 설정 전체가 돌아옵니다: 아티스트, 무드, 시드, 마디 수, 고정값.","documentation.8dc74fe7":"표시창에는 <strong>실제로 쓰인</strong> 템포와 조성이 나오며, 이는 당신이 고정한 값과 늘 같지는 않습니다: DAW가 92에 있을 때 만든 비트는 92에서 만들어졌고, 템포는 노트를 바꿉니다.","documentation.d7bad06c":"<strong>그리고 세션보다 오래 남습니다.</strong> 테이크 카운터 — 화살표 사이의 &ldquo;3 / 40&rdquo; — 를 클릭하면 지금까지 만든 모든 생성이 아티스트별로 묶여 나오고, 각 행에 길이, 빠르기, 만든 때가 적혀 있습니다. 하나를 고르면 돌아옵니다. 화살표는 &ldquo;하나 뒤로&rdquo;에 답하고, 이것은 시드를 적어 두지 않은 화요일 밤의 비트를 위한 것입니다.","documentation.1223e0b4":"프로젝트 안이 아니라 사용자별로 보관됩니다 — 어디서 생성해 왔는지는 당신에 관한 사실이지, 레이블에 보내는 곡 안에 실어 보낼 것이 아니니까요 — 그리고 업데이트 후에도 남습니다. 아티스트마다 자기 테이크 목록을 따로 가지므로, 한 아티스트로 보낸 저녁이 다른 아티스트에서 저장한 것들을 밀어낼 수 없습니다. <strong>언제든 원할 때 지우세요</strong>: 이것은 당신이 만들어 온 것의 기록이며, 비울 수 있다는 것은 단순한 편의가 아닙니다.","documentation.13e89cca":"테이크를 고르면 화살표와 마찬가지로 그것을 <em>복원</em>합니다 — 그래서 현재 클립에 손으로 그린 것은 모두 대체됩니다. 미리 듣기가 아닙니다.","documentation.5415794a":"<strong>레인을 잠그면 다시 굴려도 건드릴 수 없습니다.</strong> 아무 드럼 행의 자물쇠를 클릭하거나, 행에 포커스를 두고 <kbd>L</kbd>을 누르면, 생성은 그 주변의 나머지를 노트 하나하나 다시 만듭니다. 잠금은 내보내는 것에 아무 변화도 주지 않습니다.","documentation.99bec605":"플러그인은 아티스트, 시드, 마디 수, 고정값, 창 크기를 <strong>DAW 자체의 프로젝트 파일 안에</strong> 저장합니다. 곡을 다시 열면 세션이 돌아옵니다. 관리할 파일도, 고를 경로도 없습니다.","documentation.2c40e200":"패턴 자체는 저장되지 않습니다 — 입력값이 저장되고 엔진은 결정론적이므로, 복원은 곧 다시 생성하는 것입니다. 저장된 프로젝트가 수백 킬로바이트의 노트가 아니라 몇 바이트만 차지하는 것도 그 때문입니다.","documentation.3e527f79":"플러그인과 독립 실행 버전에 있는 모든 단축키를, 앱 안의 패널이 묶는 방식대로 묶었습니다. 앱에서 <kbd>Shift</kbd> + <kbd>?</kbd>를 누르면 이 페이지로서는 알 수 없는 당신만의 키 재지정까지 반영된 같은 목록을 볼 수 있습니다.","documentation.876884a2":"행에 <kbd>Ctrl</kbd> / <kbd>⌘</kbd>가 보이면, Ctrl(Windows/Linux) 또는 ⌘(macOS)를 뜻합니다.","documentation.e5651c68":"키","documentation.97c89a4d":"동작","documentation.c10d76c9":"트랜스포트","documentation.86247409":"<kbd>Space</kbd>","documentation.fe13ca09":"재생 또는 일시정지","documentation.a1e10fc7":"<kbd>F9</kbd>","documentation.7fa3a667":"녹음 시작 또는 정지","documentation.4b2adf96":"<kbd>F10</kbd>","documentation.b32e9662":"메트로놈 켜기 또는 끄기","documentation.dba91bb2":"<kbd>K</kbd>","documentation.7dda588a":"오른쪽 레일 표시 또는 숨기기","documentation.523bc70d":"<kbd>E</kbd>","documentation.0b4b9af3":"파일 탐색기와 스타일 목록 사이 전환","documentation.df9030e9":"<kbd>Shift</kbd> + <kbd>?</kbd> 또는 <kbd>F1</kbd>","documentation.1f06ac86":"이 패널 표시","documentation.e9789990":"보기 및 레이아웃","documentation.e14c9778":"<kbd>V</kbd>","documentation.1d83fd23":"패널 표시 또는 숨기기","documentation.d4d84f89":"<kbd>Shift</kbd> + <kbd>V</kbd>","documentation.09faca1e":"집중 모드 - 레일과 탭 숨김","documentation.fc45f9b7":"생성","documentation.285be7d3":"<kbd>Enter</kbd>","documentation.0c77ce7a":"스타일 목록 검색","documentation.04522798":"<kbd>G</kbd>","documentation.ac1fc67e":"이 파트 생성","documentation.627c2d8c":"<kbd>Shift</kbd> + <kbd>G</kbd>","documentation.3767cc00":"모든 파트 생성","documentation.ed629d67":"<kbd>1 – 6</kbd>","documentation.5ee84ca1":"생성기 선택","documentation.51462405":"<kbd>R</kbd>","documentation.9a7a1f12":"선택한 클립 다시 굴리기","documentation.5eafac83":"<kbd>L</kbd>","documentation.81eb04cd":"다시 굴려도 이 드럼 유지","documentation.9018d7e2":"<kbd>←</kbd> / <kbd>→</kbd>","documentation.cdf3fbba":"테이크 넘겨보기","documentation.3b9ba1a2":"편집","documentation.fd138353":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>A</kbd>","documentation.913afff1":"모두 선택","documentation.ebad6201":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>C</kbd>","documentation.af74f7c5":"복사","documentation.b737693a":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>X</kbd>","documentation.38d13bda":"잘라내기","documentation.098d9ba7":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>V</kbd>","documentation.db248300":"붙여넣기","documentation.414f88f4":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Z</kbd>","documentation.39fc7212":"실행 취소","documentation.fc1e31a5":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Shift</kbd> + <kbd>Z</kbd> 또는 <kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>Y</kbd>","documentation.471b94d4":"다시 실행","documentation.08b1c0d8":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>D</kbd>","documentation.972d5737":"복제","documentation.f66bceff":"<kbd>Delete</kbd>","documentation.f6fdbe48":"삭제","documentation.07fdb121":"<kbd>Esc</kbd>","documentation.04d948a3":"선택 해제","documentation.70440046":"노트","documentation.5d4723bf":"<kbd>↑</kbd> / <kbd>↓</kbd>","documentation.8c532548":"반음 조옮김","documentation.6cac4df7":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>↑</kbd> / <kbd>↓</kbd>","documentation.2b308ba3":"옥타브 조옮김","documentation.d47af99e":"시간 축으로 살짝 이동","documentation.ac264590":"<kbd>*</kbd>","documentation.be758f68":"두 배 길이로 늘이기","documentation.a9253744":"<kbd>/</kbd>","documentation.dd9f8fd9":"절반 길이로 줄이기","documentation.8382840e":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>R</kbd>","documentation.3ee05a25":"선택한 노트를 거꾸로 재생","documentation.7c37d8f8":"드럼 그리드","documentation.9e4e8841":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>3</kbd>","documentation.4157bd81":"이 셀에 셋잇단음표","documentation.43a310f9":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>5</kbd>","documentation.7e966ffc":"이 셀에 다섯잇단음표","documentation.a5878dde":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>7</kbd>","documentation.1f5d282a":"이 셀에 일곱잇단음표","documentation.7ec8386d":"<kbd>Alt</kbd> + <kbd>클릭</kbd>","documentation.ebfc4304":"1마디를 이 마디에 복사","documentation.2ff1c1cd":"<kbd>Shift</kbd> + <kbd>드래그</kbd>","documentation.fb11f8c2":"상자를 드래그해 셀 선택","documentation.4fe7447c":"<kbd>Ctrl</kbd> / <kbd>⌘</kbd> + <kbd>클릭</kbd>","documentation.54e8dccd":"선택에 셀 추가","documentation.1a36d4f6":"<kbd>오른쪽 클릭</kbd>","documentation.0aeadb3b":"이 셀의 롤 팔레트","documentation.c9889415":"<kbd>오른쪽 클릭</kbd> + <kbd>드래그</kbd>","documentation.394a6a30":"드래그로 지나간 셀 모두 지우기","documentation.dcd5f1f8":"샘플 브라우저","documentation.94d34d10":"샘플을 거꾸로 / 앞으로 재생","documentation.d604eafc":"되돌리기는 세션 안에서 무제한이며 아티스트, 시드, 마디 수, 고정값, 각 생성, <strong>그리고 편곡</strong>까지 다룹니다 — 어느 탭에 있든 하나의 스택입니다. 텍스트 칸 안에서는 시스템 자체의 실행 취소가 단축키를 가져가므로, 시드 칸에서도 입력한 글자 하나를 되돌릴 수 있습니다.","documentation.e90cfbee":"같은 플러그인을 DAW 없이 자체 창에서 실행합니다 — 무언가를 빠르게 시험해 볼 때나, 음악 작업을 하지 않는 기기에서 유용합니다.","documentation.c1864be2":"<strong>DAW와 동기화할 수 없고, 앞으로도 그럴 것입니다</strong> — 호스트가 없으니 동기화할 대상이 없습니다. 명령줄에서 고정 템포를 설정할 수 있고 이는 같은 경로를 거치지만, 실제 호스트의 템포, 박자, 재생 위치에는 실제 호스트가 필요합니다.","documentation.fb858c80":"<strong>그리고 요청하지 않으면 프로젝트 템포를 알리지 않습니다.</strong> <code>--tempo</code>가 없으면 프로젝트가 없으므로 아무것도 아티스트를 덮어쓰지 않습니다: 모델을 고르면 그것이 쓰인 템포로 들립니다. <code>--tempo</code>를 넘기면 그 고정값은 호스트의 템포와 똑같이 동작합니다.","documentation.58c0f8e2":"계정 없음. 원격 측정 없음. 당신, 당신의 프로젝트, 당신의 결과물에 관한 어떤 것도 전송되지 않습니다. 생성, 재생, 가져오기, 내보내기가 완전히 로컬입니다.","documentation.6dae90a7":"<strong>플러그인은 바깥으로 나가는 연결을 전혀 만들지 않습니다.</strong> 예전에 있던 둘 — 시작 시 업데이트 확인과 선택적 충돌 보고 — 은 데스크톱 앱의 것이었고 그것과 함께 제거되었습니다. 플러그인은 플러그인을 설치하는 사람이 설치하고 갱신하며, 거기에는 HTTP 클라이언트가 하나도 컴파일되지 않습니다. 두 개의 빌드 관문이 그 주장을 믿는 대신 커밋마다 이를 확인합니다: 하나는 의존성 그래프를 읽고 HTTP 클라이언트가 조금이라도 링크되면 실패하고, 다른 하나는 실제 화면으로 생성을 끝까지 돌려 브라우저가 기기 밖으로 요청을 한 번이라도 시도하면 실패합니다.","documentation.bef6f4df":"<strong>웹 앱은 네트워크로 전달되지만, 당신이 만드는 것은 아닙니다.</strong> 페이지는 받아와야 합니다 — 앱 자체와, 그것이 생성에 쓰는 스타일 데이터. 그것이 전부입니다. 생성은 당신의 기기, 당신의 브라우저에서 돌아갑니다. 당신의 비트, 시드, 가져온 모든 것은 거기 남고 절대 올라가지 않습니다. 한 번 방문한 뒤에는 네트워크를 끊어도 탭이 동작합니다.","documentation.410bfc53":"<strong>협업만이 유일한 예외이고, 그마저 당신이 쓸 때만입니다.</strong> 룸은 당신의 기기를 초대한 사람들과 직접 연결합니다. 누군가를 친구로 저장하면 작은 서비스가 그가 접속 중인지 알려줄 수 있습니다 — 그 서비스가 듣는 것 중 알 가치가 있는 것은 없습니다: 몇 분마다 바뀌는 키와, 둘만 가진 비밀로 암호화된 주소뿐입니다. 그것을 읽을 수도, 누가 있는지 나열할 수도, 누가 누구를 아는지 알아낼 수도 없습니다. 끄거나 친구를 저장하지 않으면 대신 코드를 붙여 넣게 됩니다. 협업 서비스에는 별도의 프로그램이 닿고, 당신의 DAW가 로드하는 플러그인은 결코 닿지 않습니다. 그래서 위의 문장이 사실로 남습니다.","documentation.0b27ac6b":"충돌 보고는 당신의 디스크에 있는 폴더에 기록되고 어디로도 보내지지 않습니다. 원할 때 버그 신고에 첨부할 것이 있도록 존재할 뿐이며 — 그 폴더를 읽는 것은 당신뿐입니다.","documentation.6d222977":"여기의 모든 답은 라이선스, <a href=\"legal/disclaimer.md\">이름 면책 고지</a>, 또는 크레딧에 이미 적혀 있는 것을 다시 말한 것입니다. 이 페이지의 어떤 것도 새로운 약속이 아닙니다.","documentation.daf9a79b":"이거 AI인가요?","documentation.2458a52d":"아닙니다. 그것도 “우리는 그렇게 부르지 않는다”는 약한 의미에서가 아닙니다. 제품 어디에도 머신러닝은 없습니다 — 모델도, 학습 데이터도, 추론도, 어떤 종류의 신경망도 없습니다. 엔진은 손으로 쓴 숫자와 규칙의 묶음을 읽고 시드가 있는 난수 생성기로 패턴을 만듭니다. 그 숫자는 읽어 볼 수 있습니다: 평범한 JSON이며, 하나하나가 템포 범위, 스윙 비율, 노트 밀도, 롤 문법, 또는 코드 경향입니다.","documentation.3bf82a34":"그럼 어떻게 특정 아티스트처럼 들릴 수 있나요?","documentation.9412c301":"프로듀서의 습관은 설명할 수 있기 때문입니다. 하이햇이 얼마나 자주 겹치는지, 스네어가 어디 떨어지는지, 808이 미끄러지는지와 얼마나 멀리 미끄러지는지, 어떤 코드 계열이 나오고 어떤 것이 절대 나오지 않는지 — 그것을 공개된 인터뷰, 기법 기사, 그리고 듣기로부터 손으로 적었습니다. 셔플을 가르쳐 주는 드럼 레슨과 같은 종류의 문서이며, 같은 이유로 통합니다.","documentation.fa02d276":"아티스트들이 참여했나요? 그들이 승인했나요?","documentation.ac411997":"아닙니다. <strong>이 소프트웨어에 이름이 나오는 어떤 아티스트, 프로듀서, 레이블, 출판사도 이를 보증하거나 후원하거나 승인하거나 검토하지 않았고, 어떤 식으로도 관련이 없습니다.</strong> 그들의 이름은 알아볼 수 있는 스타일을 설명하는 참조로만 나오며 그 이상은 아닙니다 — 코드 차트에 “보사노바”라는 이름표가 붙을 수 있는 것과 같은 방식입니다. 어떤 이름도 이 소프트웨어나 그것이 생성하는 것의 상표나 출처 표시로 쓰이지 않습니다.","documentation.af1c7364":"그들의 음악이 들어 있나요?","documentation.bb221e18":"아닙니다. 스타일 모델에는 MIDI도, 오디오도, 어떤 녹음을 옮겨 적은 것도, 어떤 곡의 선율이나 가사 내용도 없습니다. 특정 트랙을 다시 만들어내는 기능은 없고 앞으로도 없을 것입니다 — 그것은 아직 만들지 않은 것이 아니라 영구적인 설계 결정입니다.","documentation.92ebf1ef":"만든 것을 발매할 수 있나요? 팔 수 있나요?","documentation.02c55f87":"네. 생성기가 쓰는 것은 구조상 원본입니다: 규칙과 숫자 하나로 조립되었고 그 과정 어디에도 녹음이 없으므로, 그 안에 다른 누군가의 작업에서 온 것은 없습니다. 결과물은 당신 소유이며 그에 대해 누구에게도 빚진 것이 없습니다 — 정확한 문구는 아래 라이선스를 보세요.","documentation.1d3f4df2":"일반적인 단서가 적용되며, 이 소프트웨어와는 상관이 없습니다: 권리가 없는 샘플을 패드에 놓으면 그 샘플은 여전히 당신 것이 아닙니다. 노트는 당신 것이고, 가져온 녹음은 원래 그것이던 그대로입니다.","documentation.114f1c77":"이미 존재하는 멜로디를 우연히 쓰면 어떻게 되나요?","documentation.e79791f6":"그것을 걸러 냅니다. 모든 멜로디와 카운터멜로디는 그 모양 — 음정의 연속과 그 사이의 간격 — 으로 지문이 떠지고, 당신이 듣기 전에 잘 알려진 멜로디의 표와 대조됩니다. 일치하는 것은 버려지고 다시 뽑힙니다.","documentation.9e84e0da":"<strong>그것이 무엇을 다루는지 솔직하게 말하자면.</strong> 표에는 퍼블릭 도메인 멜로디 — 전래곡, 찬송가, 클래식 — 가 들어 있습니다. 다른 것으로 표를 만들면 이 소프트웨어가 남의 노트를 싣고 다니게 되고, 그것은 결코 해서는 안 되는 단 한 가지이기 때문입니다. 그래서 이 검사는 유명한 곡을 우연히 인용하는 것을 잡아내며, 그것은 잡아낼 가치가 있습니다. 그것이 당신의 결과물이 원본인 이유는 <em>아닙니다</em>. 그 이유는 위의 두 답에 있는 모든 것입니다.","documentation.13eef4e4":"외부로 몰래 연락하나요?","documentation.772074f7":"아닙니다. 실제로 네트워크에 닿는 두 가지 — 웹 앱을 받아오는 것, 그리고 당신이 쓰기로 했을 때의 협업 — 와 그 이유까지 포함한 전체 답은 위의 <a href=\"#privacy\">개인정보와 네트워크</a>를 보세요.","documentation.58fc0ea4":"드럼 루프와 원샷은 어디서 왔나요?","documentation.ccf41857":"둘 다 우리 것입니다. 함께 실린 5,085개의 MIDI 루프는 이 제품 자신의 생성기가 자신의 스타일 모델로 썼습니다 — 누구의 오디오나 MIDI에서도 루프를 추출하지 않았습니다. 미리 듣기용 원샷은 오실레이터와 필터를 거친 노이즈로 합성되므로, 녹음된 소재는 전혀 들어 있지 않고 제3자 라이선스도 붙어 있지 않습니다.","documentation.1f932b39":"오프라인에서 쓸 수 있나요?","documentation.a812ebd9":"플러그인과 독립 실행 버전은 애초에 네트워크가 필요한 적이 없습니다. 웹 앱은 자신을 한 번 받아온 뒤에는 네트워크를 끊어도 동작합니다.","documentation.a1904ba7":"몰래 외부로 보고하는 기능은 없으며, 앞으로도 없을 것입니다. 대신 폴더가 있습니다: 플러그인의 어느 쪽이든 쓰러지면 무슨 일이 있었는지를 당신의 디스크에 기록하고, 보낼지는 당신이 정합니다.","documentation.801c98db":"보고가 있는 곳","documentation.9cacc2d0":"<code>%APPDATA%\\Freally MIDI Master\\crashes\\</code>","documentation.3b993d8d":"<code>~/Library/Application Support/Freally MIDI Master/crashes/</code>","documentation.1a91a6c1":"<code>$XDG_DATA_HOME/freally-midi-master/crashes/</code> 또는 <code>~/.local/share/freally-midi-master/crashes/</code>","documentation.90d83808":"파일 이름이 어느 쪽이 쓰러졌는지 말해 줍니다: <code>-panic</code>은 백트레이스가 담긴 오디오 엔진, <code>-page</code>는 화면, 그리고 Windows에서 <code>-fault</code>는 접근 위반 같은 하드웨어 오류입니다. 가장 최근 스무 개만 남기므로 폴더가 끝없이 커지지 않고, 전부를 버그 신고에 첨부할 수 있습니다.","documentation.4ec55525":"망가진 것이 <em>화면</em>이라면, 죽은 사각형 대신 세션으로 돌아가는 길이 있는 패널이 보입니다 — 편곡은 충돌한 부분 바깥에 있으므로, 버튼을 누르면 당신의 작업이 다시 그려집니다. 그래도 신고해 주세요. 로그는 이미 디스크에 있습니다.","documentation.cd05c2a9":"그러니 보고할 때는 어떤 호스트인지, 어떤 형식(CLAP 또는 VST3)인지, 어떤 OS 버전인지 적고 위 폴더의 최신 파일을 첨부하세요. 충돌로 DAW 전체가 종료되었다면 DAW가 남긴 로그도 함께 첨부하세요. 호스트가 죽으면 저희가 기록할 창이 남아 있지 않을 수 있습니다.","documentation.f7ca8294":"독점 소프트웨어, <strong>모든 권리 보유</strong>. 소스 코드는 비공개입니다. 재배포하거나 파생물을 배포할 수 없습니다. 오픈 소스가 <strong>아닙니다</strong>.","documentation.5d361274":"<strong>이것으로 만든 음악은 당신 것입니다</strong>. 사용료도, 출처 표기 의무도 없습니다.","roster.827703c6":"플러그인이 모델링하는 모든 아티스트, 프로듀서, 장르.","roster.numbers.genres":"장르","roster.8d0c67df":"<strong>이것은 손으로 쓴 매개변수이며 학습 데이터가 아닙니다.</strong> 이 중 어떤 것을 만들기 위해서도 누구의 오디오도 분석하지 않았습니다. 각 항목은 사람이 공개된 연구에서 적어 둔 숫자 묶음입니다 — 템포 범위, 스윙, 킥이 떨어지는 박 — 그리고 이름은 장르 이름을 쓰는 방식과 똑같이, 어떤 스타일이 어떻게 들리는지 말하기 위해 쓰입니다. 여기 누구로도 학습한 모델은 없고, 플러그인은 녹음을 재현하는 대신 원본 패턴을 생성합니다.","roster.fb1a2b56":"<strong>어떤 제휴, 보증, 저작 관계도 암시하거나 주장하지 않습니다.</strong> 여기 실린 어떤 아티스트, 프로듀서, 레이블, 출판사, 권리자도 이 소프트웨어를 보증하거나 후원하거나 승인하거나 검토하지 않았고, 어떤 식으로도 관련이 없습니다. 아래의 어떤 이름도 이 소프트웨어나 그것이 생성하는 것의 상표, 제품명, 출처 표시로 쓰이지 않습니다. 모든 상표와 이름은 각 소유자의 것입니다. <a href=\"legal/disclaimer.md\">전체 면책 고지 읽기</a>.","roster.40f89a05":"스타일 목록","roster.e13848fc":"이름, 장르 또는 시대","roster.bce06414":"검색","roster.3deb7456":"종류","roster.6a720856":"전체","roster.1528d87e":"아티스트","roster.a44fa04f":"프로듀서","roster.96817ade":"장르","roster.5bd44ebe":"등급","roster.ab64ea9b":"대표","roster.2dfa6607":"표준","roster.2a864697":"스타일","roster.f37a89cb":"시대","roster.55ac5448":"스타일 목록을 불러오는 중…","roster.type.artist":"아티스트","roster.type.producer":"프로듀서","roster.type.genre":"장르","roster.shown":"{total}개 중 {shown}개 일치","roster.none":"일치하는 항목이 없습니다.","roster.failed":"스타일 목록을 불러오지 못했습니다. 페이지를 새로 고쳐 보세요.","roster.file":"이 페이지는 로컬 파일로 열려 있으며, 브라우저는 file:// 페이지에서 스타일 목록을 불러오지 않습니다. 대신 HTTP로 여세요.","kit.skip":"본문으로 건너뛰기","kit.nav.site":"사이트","kit.nav.home":"홈","kit.nav.features":"기능","kit.nav.documentation":"문서","kit.nav.roster":"목록","kit.nav.changelog":"변경 로그","kit.nav.language":"언어","kit.nav.allApps":"모든 Freally 앱","kit.badge.progress":"v1.0.0-beta 완료 · 다음은 v1.0.0RC","kit.cta.features":"모든 기능 보기","kit.cta.docs":"문서 읽기","kit.price":"Freally MIDI Master는 지금은 무료이지만 영원히 무료가 아닐 수도 있습니다. 향후 버전은 판매될 수 있습니다.","kit.noDownloads":"아직 다운로드는 없으며, 소스 코드는 비공개입니다.","kit.label.overview":"개요","kit.label.inAction":"실제 모습","kit.label.inside":"내부","kit.label.roadmap":"로드맵","kit.ladder.done":"완료","kit.ladder.planned":"예정","kit.ladder.goal":"목표","kit.label.honesty":"정직함","kit.family.label":"Freally 패밀리","kit.family.title":"<span class=\"hl-muted\">하나의 패밀리.</span> <span class=\"hl-bright\">여덟 개의 앱.</span>","kit.cta.label":"달라진 점","kit.cta.title":"<span class=\"hl-muted\">모든 버전을,</span> <span class=\"hl-bright\">기록으로.</span>","kit.cta.lede":"변경 로그에는 Freally MIDI Master에서 바뀐 모든 것이 버전별로, 18개 언어 모두로 담겨 있습니다.","kit.cta.changelog":"변경 로그 읽기","kit.footer.thisApp":"이 앱","kit.footer.family":"Freally 패밀리","kit.status.devVersion":"개발 중 · v1.0.0-beta","kit.head.features":"<span class=\"hl-muted\">할 수 있는 모든 것을,</span> <span class=\"hl-bright\">나란히 비교.</span>","kit.label.numbers":"숫자로 보기","kit.label.free":"지금은 무료","kit.label.compare":"비교","kit.label.principles":"원칙","kit.label.limits":"한계","kit.states.title":"상태의 의미","kit.states.done":"빌드하고 태그까지 달았지만, 이 사이트에서 내려받을 수는 없음","kit.states.planned":"아직 만들어야 함","kit.states.goal":"이 길이 향하는 버전","kit.states.ladder":"길의 모든 단계 보기","kit.head.documentation":"<span class=\"hl-muted\">작동 방식을,</span> <span class=\"hl-bright\">단계별로.</span>","kit.search.placeholder":"문서 검색","kit.docs.contents":"목차","kit.head.roster":"<span class=\"hl-muted\">모든 스타일을,</span> <span class=\"hl-bright\">하나의 목록에.</span>","kit.numbers.lead":"모든 수치는 앱 자체에서 센 것입니다. 추정한 것도, 올려 잡은 것도 없습니다.","kit.label.styles":"스타일","kit.head.changelog":"<span class=\"hl-muted\">모든 변경을,</span> <span class=\"hl-bright\">버전별로.</span>","kit.changelog.lede":"최신순: Freally MIDI Master에서 바뀐 모든 것을, 이 사이트의 모든 언어로.","kit.changelog.versions":"버전","kit.changelog.unreleased":"미출시","kit.search.none":"이 사이트에는 일치하는 것이 없습니다.","changelog.69c6a54708de":"<span class=\"release__meta\"><span class=\"release__ver\">미출시</span></span>","changelog.2a6141e43be0":"변경","changelog.e872b6a54c3f":"<strong><code>freally-encode</code>와 <code>freally-drag</code>가 독립된 크레이트가 됩니다</strong>(공유 태그 <code>shared-v2</code>, Freally Unloop의 분리 작업 A). <code>acid</code> 템포 청크를 쓰는 WAV/AIFF 작성기, WAV 프로브, 그리고 단 하나의 <code>rubato</code> 리샘플링 입구가 <code>freally_library::encoder</code>와 <code>plugin/src/audio/resample.rs</code>에서 <code>encode/</code>(<code>freally-encode</code>)로 옮겨졌고, OLE / Cocoa / GTK 드래그 소스는 <code>plugin/src/drag/</code>에서 <code>drag/</code>(<code>freally-drag</code>)로 옮겨져 제품에 대해 제네릭이 되었습니다. MIDI Master는 둘 다 사용하며 바이트는 그대로입니다: 같은 WAV와 AIFF 파일, 모든 비트 깊이에서 같은 <code>acid</code> 청크, 같은 드래그 스풀 폴더. 라이브러리의 세션 청크는 <code>freally_library::encoder</code>에 남고, 나머지는 거기서 다시 내보냅니다.","changelog.57c8863aec4f":"<strong>FLAC과 MP3, 기능 플래그 뒤에.</strong> <code>freally-encode</code>는 Unloop의 Print를 위해 FLAC(<code>flacenc</code>, 기능 <code>flac</code>, <code>BPM=</code> Vorbis 주석)과 MP3(<code>rusty_mp3</code>, 기능 <code>mp3</code>, ID3v2.3 <code>TBPM</code>/<code>TIT2</code>)를 추가합니다. MIDI Master는 아직 둘 다 켜지 않습니다. 저수준 작성기는 오디오의 레이블을 절대 바꿔 달지 않습니다: 담을 수 없는 샘플레이트는 거부되고, 리샘플링 입구가 먼저 변환합니다. 이제 <code>ci:local</code>, CI, <code>cargo deny</code>가 모든 기능을 켠 채로 이 크레이트를 빌드하고, 테스트하고, 라이선스를 검사합니다.","changelog.e418959c78ca":"<strong>웹뷰 어댑터가 자신의 데이터 폴더 이름을 정합니다</strong>(<code>WebViewEditor::with_data_dir_name</code>, 기본값은 그대로 <code>Freally MIDI Master</code>). 에디터의 화면 맞춤(<code>system_scale</code>, <code>work_area</code>)은 어댑터의 <code>screen</code> 모듈로 옮겨졌습니다. 잘못된 이름은 기본값으로 돌아갑니다.","changelog.28724e313f97":"<strong><code>engine</code>이 자기 완결적이 됩니다</strong>: <code>data/humanize/groove.json</code>과 그 README, <code>data/novelty/hooks.hash</code>가 <code>engine/data/</code> 아래로 옮겨져, 크레이트가 전체 체크아웃에서만이 아니라 벤더링되거나 게시된 사본에서도 빌드됩니다.","changelog.7542eeec97e8":"<strong><code>engine::smf_read::read_facts</code></strong> — MIDI 파일의 노트, 포맷, 템포, PPQ, 트랙, 박자, 길이. Unloop의 Loop Library를 위한 것입니다.","changelog.5af8a9a4077e":"<strong><code>freally-extract</code>가 독립된 크레이트가 됩니다</strong>(공유 태그 <code>shared-v3</code>, Freally Flipcopy의 TASK-020과 Freally Unloop의 TASK-090을 위해). 추출기 — 온셋, 그리드, 드럼, 음높이가 있는 라인, 보컬 테스트, 크로마 — 가 <code>plugin/src/extract/</code>에서 <code>extract/</code>(<code>freally-extract</code>)로 옮겨졌고, 그 앞의 디코드 입구(<code>plugin/src/audio/import.rs</code>, 이제 <code>freally_extract::decode</code>), 피치 트래커(<code>plugin/src/audio/pitch.rs</code>), <code>midi_hz</code>, <code>SILENCE_PEAK</code>도 함께 옮겨졌습니다. 예전 경로는 모두 옮겨진 것을 다시 내보내므로, MIDI Master의 추출, 원샷 가져오기, 라이브러리 스캔은 같은 파일을 같은 방식으로 읽습니다. 워커에서 추출을 돌리는 작업만 플러그인에 남습니다. 크레이트는 <code>wasm32</code>(Unloop의 웹 앱)용으로도 빌드되며, 이제 <code>ci:local</code>과 CI가 이를 확인합니다.","changelog.a04385060482":"<strong><code>freally_extract::decode::decode_facts</code></strong>(그리고 <code>decode_file_facts</code>) — 같은 디코드 입구이면서, 모노로 접기 전에 파일이 담고 있던 것도 돌려줍니다: 채널 수, 비트 깊이, 그리고 모든 채널에 걸친 피크와 RMS. Flipcopy의 인쇄된 페이지를 위한 것입니다. 패킷이 지나가는 동안 하나의 리더가 집계하며, 기존 입구들은 예전과 정확히 같은 것을 돌려줍니다.","changelog.6cb361b3247a":"<strong><code>freally_library::audition::NoteRenderer</code></strong>(Flipcopy 계획의 <code>render_notes</code>, <code>shared-v3</code>) — 클립의 노트를 라이브러리 프리셋으로, 또는 GM 드럼 레인마다 보이스 하나를 둔 드럼 머신으로 렌더링합니다. 피치 벤드와 서스테인 페달을 반영하고 마지막 노트 뒤에 꼬리를 남깁니다. 보이스는 <code>SynthEngine</code>의 것, 드럼은 <code>drumkit</code>의 것이고, 이벤트는 해당 프레임에 적용되며, 프리셋 렌더링은 프리셋에서 시드를 얻으므로 같은 노트는 같은 바이트로 렌더링됩니다. 어떤 레인도 응답하지 않는 드럼 노트는 세어 둘 뿐 절대 추측하지 않습니다. Flipcopy의 MIDI → 오디오를 위한 것이며, MIDI Master에서는 아직 아무것도 이를 호출하지 않습니다.","changelog.86cdd25e66f0":"<strong><code>engine::smf_read::read_facts</code>가 모든 피치 벤드와 컨트롤러를 보고합니다</strong>(<code>Facts::controls</code>, <code>shared-v3</code>). 시간 순서대로, 최대 20,000개까지이며 상한에 걸리면 <code>controls_capped</code>가 그렇다고 알립니다 — 거부가 아니라 상한이므로, 예전에 가져와지던 파일은 모두 예전과 정확히 같이 가져와집니다.","changelog.ed6c4224859d":"<strong>값으로서의 거부</strong>(<code>shared-v3</code>): 디코드 입구의 <code>decode_facts</code>와 <code>read_bounded</code>, 그리고 <code>engine::smf_read::read_facts</code>는 타입이 있는 <code>Refusal</code>(너무 큼, <em>파일 자체의 샘플레이트에서</em> 너무 김, 무음, SMPTE, 노트가 너무 많음…)로 거부하며, 그 <code>Display</code>는 그 입구들이 늘 돌려주던 문장입니다 — 그래서 모든 <code>String</code> 입구는 예전과 정확히 같은 말을 합니다. 영어 문장을 대조하는 대신 각 거부를 그 한도와 함께 프로듀서의 언어로 인쇄하는 Freally Flipcopy를 위한 것입니다. <code>shared-v2</code>에서 <code>read_facts</code>는 <code>String</code>을 돌려주었습니다.","changelog.980fad0ffb14":"<strong><code>NoteRenderer::set_sample_rate</code></strong>(<code>shared-v3</code>): 새 샘플레이트에서도 예열된 엔진을 다시 만들지 않고 유지합니다(각 엔진은 다음에 쓰일 때 새 레이트로 맞춰집니다).","changelog.e9ddffd5fc76":"<strong><code>freally_extract::decode::frame_budget</code></strong>(<code>shared-v3</code>): 어떤 레이트의 디코드가 초 단위 상한에 대해 담는 프레임 수 — 입구 자체의 규칙이 이제 공개되어, 입구로 다시 읽어 들일 파일을 렌더링하는 제품(Freally Flipcopy의 사본)이 입구가 거부할 렌더링을 할당하기 전에 거부합니다.","changelog.013f4389933a":"<strong><code>read_bounded</code>가 실제로 읽은 양으로 제한됩니다</strong>(<code>shared-v3</code>, Freally Flipcopy의 코드 리뷰): 장치는 한 바이트도 읽기 전에 거부되고, 크기를 확인한 뒤에 커지는 파일은 <code>MAX_FILE_BYTES</code>까지 읽힌 뒤 거부됩니다 — 크기 확인만으로는, 길이를 0으로 보고하는 <code>/dev/zero</code>가 호스트의 메모리가 바닥날 때까지 읽혔습니다.","changelog.2d1ace37beb0":"<strong>한 프레임보다 짧은 노트도 릴리스됩니다</strong>(<code>NoteRenderer</code>, <code>shared-v3</code>): 릴리스는 스트라이크와 같은 프레임이 아니라 그 한 프레임 뒤에 놓입니다 — 같은 프레임에서는 릴리스가 먼저 처리되므로, 시작과 끝이 같은 프레임으로 반올림된 노트는 꼬리 내내 울렸습니다.","changelog.3649549ac755":"<strong><code>drums::proposal_name</code>이 공개됩니다(문서에서는 숨김)</strong>. 드럼 벤치가 새 크레이트 경계 너머에서도 닿을 수 있도록.","changelog.87e36c5e8277":"<strong>nih-plug가 커밋 하나 앞으로 갑니다</strong>(<code>shared-v3</code>): 포크의 <code>ProcessContext::process_mode()</code> 덕분에, CLAP 호스트가 다시 초기화하지 않고 모드를 바꾼 경우에도 플러그인은 블록이 오프라인 렌더링임을 압니다(Freally Flipcopy의 기계 소리는 절대 바운스에 들어가면 안 됩니다). 어댑터와 두 플러그인 매니페스트가 함께 옮겨 갑니다: 빌드 안의 <code>nih_plug</code>는 하나뿐입니다.","changelog.807f6de9d0ba":"<strong><code>nih-plug-webview</code>가 OS에서 끌어다 놓은 파일을 받을 수 있습니다</strong>(<code>WebViewEditor::with_file_drop_handler</code>, <code>shared-v3</code>, Freally Flipcopy의 유리판을 위해) — 경로가 담긴 wry의 파일 드롭 이벤트를 에디터의 UI 스레드에서 받습니다. 선택 사항입니다: 핸들러가 없으면 웹뷰는 원래 동작을 유지하며, MIDI Master의 에디터는 핸들러를 설정하지 않습니다.","changelog.99613a84e077":"<strong>화면 건반이 창의 가운데 전체에 걸쳐 펼쳐지고, 모든 건반에 이름이 붙었습니다.</strong> 옥타브 화살표와 옥타브 수를 건반 위 막대로 옮겨 건반 옆에는 아무것도 없습니다. 3, 5, 7옥타브를 스크롤 없이 제공하며(이전에 저장한 9나 10은 7로 돌아옵니다), 이름을 가로로 담기엔 너무 좁은 건반은 이름을 세로로 씁니다. 건반 버튼은 건반이 열려 있는 동안 켜집니다.","changelog.810e5edf6d32":"<strong><code>npm run plugin:install</code>이 호스트가 찾는 곳에 설치합니다</strong>. Windows에서는 사용자 폴더와 함께 시스템 VST3·CLAP 폴더에도 링크 대신 복사로 설치하며, 호스트가 대신 불러올 오래된 사본이 있으면 그 이름을 알리고 실패합니다.","changelog.1246fc93bca0":"수정","changelog.464aedef592b":"<strong>끝나지 않는 노트온으로 된 MIDI 파일은 읽히지 않고 거부됩니다</strong>: 노트 한도는 닫힌 노트뿐 아니라 열린 노트도 세고, 노트오프는 로그 시간 안에 자신의 노트를 찾습니다 — 길 잃은 노트오프가 백만 개인 파일도 더는 몇 초씩 걸리지 않습니다.","changelog.22e2ad641345":"<strong>드래그 스풀의 일주일 지난 파일 정리는 하위 폴더의 오디오를 절대 지우지 않고</strong>, 링크를 절대 따라가지 않으며, 스풀·스필·파일 드래그는 평범한 이름이나 경로가 아닌 것을 거부합니다.","changelog.59ff0563db02":"<strong>렌더링과 다른 샘플레이트로 내보낸 오디오가 정확히 있어야 할 길이로, 있어야 할 자리에 놓입니다.</strong> 리샘플러는 모든 변환에서 마지막 프레임들을 잃었고(48 kHz의 48,000 프레임이 44.1 kHz에서 44,100이 아니라 44,098로 나왔습니다) 모든 것을 최대 세 프레임 어긋나게 놓았습니다 — 44.1→96 kHz에서는 +1.17 프레임 늦게, 96→48 kHz에서는 반 프레임 일찍. 이제 길이는 가장 가까운 프레임으로 맞춘 <code>frames × to / from</code>이고, 위치는 모든 내보내기 레이트에서 50분의 1 프레임 이내입니다. 이는 네이티브가 아닌 레이트로 내보내거나 끌어낸 모든 것의 바이트를 바꾸며, 자신과 다른 장치 레이트로 변환된 킷 원샷은 이제 마지막 프레임들을 유지합니다. 자기 레이트 그대로인 것은 바뀌지 않습니다.","changelog.186e93b3edac":"<strong>모든 드롭다운 목록을 모든 테마와 스킨에서 읽을 수 있습니다.</strong> 옵션이 시스템의 흰 목록 위에 앱의 밝은 글자로 그려져, 강조된 항목만 읽을 수 있었습니다.","changelog.5788a29cdee7":"<strong>화면 건반의 흰건반에 이름이 보입니다.</strong> 어두운 테마에서 흰건반 끝의 흰 바탕에 밝은 글자로 그려져 있었습니다.","changelog.958aa1bbe8f9":"<strong>스타일 편집기의 스타일 저장 버튼이 옆 버튼들과 같은 크기가 되었습니다.</strong>","changelog.db671325856c":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0RC</span><time class=\"release__date\" datetime=\"2026-09-17\">2026-09-17</time></span>","changelog.2d4bc1529072":"<strong>첫 릴리스 후보</strong>, 0.4.0 이후 153개 항목. 내려받기용이 아닙니다: 이 바이너리는 소유자가 Ableton, FL Studio, Reaper, Freally Oscillate에서 직접 테스트하기 위한 것이며, 그 테스트가 끝나기 전에는 사이트에 어떤 링크도 나타나지 않습니다.","changelog.2140e4134a93":"<strong>이제 네 곳에서 돌아갑니다</strong> — 이 플러그인, 독립 실행 버전, wasm으로 컴파일된 같은 생성기를 돌리는 브라우저 탭, 그리고 휴대전화의 MixSir. <strong>새로운 것:</strong> 협업 룸, 팩토리 확장 팩 네 개(악기 1,400개, 루프 5,085개, 아티스트 189명 추가), 클립 페이드, 실제 오디오 그 자체인 오디오 클립 보기, 노트별 확률과 벨로시티, 내보낸 파일 안에 담겨 함께 이동하는 세션, 그리고 초록색 제품.","changelog.89b5266eb048":"<strong>알려진 사항:</strong> 아직 Linux 에디터가 없어 여기서는 Linux를 빌드하지 않습니다. 바이너리는 방침상 서명되지 않으며 옆에 체크섬이 있습니다. 그리고 리뷰에서 나온 발견 열한 개가 <code>docs/product-roadmap.md</code>에 기록되어 있고 고쳐지지 않았지만, 그 어느 것도 충돌이나 데이터 손실은 아닙니다.","changelog.68f004440417":"수정 - 콜드 상태의 개발 서버에서 e2e 관문이 시간 초과되던 문제, 2026-09-17","changelog.9656ae419100":"접근성 스펙 네 개가 페이지에는 아무 문제가 없는데도 <code>page.goto</code>에서 실패했습니다: 콜드 상태의 <code>vite</code>는 첫 브라우저 요청 때 모듈 그래프를 컴파일하고(측정값 19.5초), 워커가 넷이면 스펙 넷이 그 비용을 동시에 치렀습니다. 이제 <code>e2e/warm.setup.ts</code>가 스위트 전에 앱을 한 번 컴파일합니다 — a11y는 실패 4/불안정 3에서 <strong>9/9</strong>가 되었고, 전체 실행도 7.1분에서 4.7분으로 빨라졌습니다.","changelog.aeb4521d29c5":"⚠ 첫 시도는 제외 설정을 엉뚱한 구성 계층에 넣어 갤러리를 조용히 <strong>수집된 테스트 0개</strong>로 줄였고, 관문은 이를 통과로 보고합니다.","changelog.730e1894b827":"변경 - 이제 제품은 초록색이고, 그것도 아이콘의 초록색입니다, 2026-09-16","changelog.b34d121fa3fb":"앱, 플러그인, 문서 사이트의 보라색이 모두 사라졌습니다. <code>#79D920</code>은 <code>images/freally-icon.png</code>에서 <strong>샘플링한</strong> 색입니다 — 밝은 초록 픽셀들의 가중 중심 — 그래서 UI와 작업 표시줄 아이콘이 거의 같은 초록이 아니라 같은 초록입니다.","changelog.b9820271dd5a":"⛔ 라이트 테마는 아이콘의 그림자 초록인 <code>#1A6B02</code>를 씁니다. <code>#79D920</code>은 흰색 위에서 <strong>1.79:1</strong>이기 때문입니다. 같은 계산이 실제 버그 하나를 잡았습니다: 흰 레이블이 하드코딩되어 새 초록 위에서 읽을 수 없던 브랜드 버튼이 이제 <code>--color-on-primary</code>를 씁니다.","changelog.17307457bdf8":"⚠ 중립색은 휘도가 아니라 색조만 옮겨졌으므로, 112개의 대비 단언 중 어느 것도 바뀌지 않았습니다. 청록색 재생 헤드 색은 의도적으로 손대지 않았습니다.","changelog.97e593faa953":"추가 - 창 상단에서 이름이 회전합니다, 2026-09-16","changelog.a5f5f81eb744":"앱 상단 가운데에서 Y축으로 회전하는, 깎아 새긴 “FREALLY MIDI MASTER v1.0.0RC”. 뒤집기가 아니라 돌출입니다 — Z축을 따라 열 장을 겹쳤습니다. <code>rotateY</code> 하나만으로는 90°에서 머리카락 같은 선으로 사라져 이름이 깜빡 꺼지는 것처럼 보이기 때문입니다. <code>prefers-reduced-motion</code>에서는 깊이가 살아 있도록 비스듬한 각도로 그 자리에 멈춥니다.","changelog.84bc48ed5549":"추가 - 클립이 페이드 인/아웃하며, 그 커브를 휠 수 있습니다, 2026-09-16","changelog.ef9458203075":"송 어레인지먼트의 모든 클립에는 페이드 인과 페이드 아웃이 있고, 각각 길이를 정하는 핸들과 모양을 정하는 점이 있습니다 — 그래서 아티스트의 편곡을 당신만의 것으로 휘어 바꿀 수 있습니다.","changelog.2cb75c827e48":"⛔ 두 경로는 절대 교차할 수 없습니다: 교차한 한 쌍은 어떤 엔벨로프도 나타내지 않으므로, 겹치게 될 때는 하나가 다른 하나를 조용히 지우는 대신 둘 다 <em>비례하여</em> 줄어듭니다. 페이지의 <code>fadeGain</code>은 엔진의 <code>Fade::gain_at</code>을 정확히 그대로 따르므로, 그림과 오디오가 하나의 공식입니다.","changelog.3dfc5811a505":"추가 - 클립의 오디오 보기가 이제 실제 오디오입니다, 2026-09-16","changelog.6279a3048ed5":"편곡을 오디오 클립으로 전환하면 각 클립이 자신의 악기로 렌더링된 모습이 보이므로, DAW로 끌어 넣기 전에 어떤 소리인지 알 수 있습니다.","changelog.ee37a55bde55":"⛔ 에디터 스레드는 절대 렌더링하지 않습니다 — 클립 320개를 각각 0.5초씩 렌더링하면 호스트가 멈춥니다. 플러그인은 캐시에서 답하거나 작업을 대기열에 넣고, 타임라인은 그림이 도착할 때까지 노트 스케치를 유지합니다. “실시간”은 캐시 키가 클립 <em>그리고 그 소리</em>라는 데서 저절로 따라 나오므로, 노브를 돌리면 새로 렌더링되고 아무것도 폴링하지 않습니다.","changelog.a9a5cc1bf02a":"⚠ 브라우저 탭은 노트 스케치를 영원히 유지합니다: 그곳에서는 오디오가 준비되지 않습니다.","changelog.7f09fbbe15e8":"추가 - 노트별 확률과 벨로시티 범위, 2026-09-16","changelog.750b30239ec8":"<strong>피아노 롤의 어떤 노트에든 연주될 확률과 흔들리는 벨로시티를 줄 수 있습니다.</strong> Mike: <em>“B5-2 — 노트별 확률”</em>, <em>“B5-3 — 노트별 벨로시티 편차/범위”</em>. 확률은 노트가 얼마나 채워졌는지로 그려지고, 범위는 벨로시티 레인에서 막대 머리 주위의 띠로 그려집니다.","changelog.38ee53053857":"⛔⛔ 내보내기는 결과를 확정하며, 매번 똑같이 확정합니다","changelog.a910d8608bd3":"<code>.mid</code>가 한 번의 굴림을 확정하면 두 번의 내보내기가 서로 달라지거나 — 골든 스냅샷과 바이트 단위로 동일해야 하는 <code>web_parity</code> 관문이 깨집니다 — 아니면 이 기능은 미리 듣기 전용이 되어 당신이 받게 될 것에 대해 거짓말을 합니다.","changelog.a2258c7138d5":"▶ <strong>딜레마의 양쪽 모두 확정이 무작위라고 가정합니다. 그렇지 않습니다.</strong> 굴림은 클립의 시드, 패스, 노트 인덱스의 해시이고 모든 내보내기는 패스를 고정하므로, 파일은 확정되면서 <em>동시에</em> 두 번의 내보내기가 동일합니다. Ableton은 비결정적으로 확정합니다. 이쪽이 확실히 더 낫고 비용도 들지 않습니다. 손대지 않은 노트는 늘 이기는 것이 아니라 굴림 자체를 건너뛰므로, 모든 스냅샷이 바이트 단위로 동일하게 유지됩니다.","changelog.431581274355":"수정 - 독립 실행 버전의 아이콘이 존재한 적 없는 파일에서 왔던 문제, 2026-09-16","changelog.a1f30e06011e":"<code>plugin/build.rs</code>는 읽는 모든 이에게 <code>images/freally_app_icon.png</code>에서 <code>icon.ico</code>를 다시 생성하라고 했는데, 그 파일은 이 저장소에 있었던 적이 없습니다. 이제 실제 제품 아이콘인 <code>images/freally-icon.png</code>를 가리킵니다.","changelog.d910c7246ee7":"⚠ <code>.ico</code> 항목은 DIB이고 하나하나 검증됩니다: PNG로 압축된 항목이 있으면 리소스 컴파일러가 <em>조용히</em> 기본 Rust 아이콘으로 되돌아갑니다.","changelog.1ec023a53376":"추가 - 세션이 파일 안에 담겨 함께 이동합니다, 2026-09-16","changelog.fd23b1eb34b6":"내보낸 <code>.mid</code>나 <code>.wav</code>는 이제 그것을 만든 세션 전체를 담고 있습니다. DAW에서는 평범한 파일이지만, 여기서 열면 아티스트, 시드, 고정값, 무드, 잠금, 음소거, 패드 배정이 모두 돌아옵니다 — 그래서 파일이 누군가의 노트가 아니라 <strong>당신의</strong> 것으로 다시 열립니다. MIDI는 리더가 건너뛰어야 하는 <code>FF 7F</code>를 쓰고, 오디오는 이미 템포를 담고 있는 <code>acid</code> 청크 옆의 RIFF 청크를 씁니다. 이 제품이 바운스한 <code>.wav</code>를 다시 놓으면, 1분간의 분석으로 근사하는 대신 세션이 즉시 돌아옵니다.","changelog.906d755eff63":"⛔ 누군가 보낸 파일은 신뢰할 수 없습니다: 블롭에는 버전과 길이 상한이 있고, 필드 하나가 잘못된 문서는 <strong>통째로</strong> 거부됩니다. 반쯤 적용된 세션은 남의 고정값 위에 얹힌 당신의 아티스트 이름이기 때문입니다. <code>midly</code>는 잘린 파일도 불평 없이 파싱하므로 — 200바이트로도 그럴듯한 문서가 나옵니다 — 블롭이 자신의 길이를 스스로 밝힙니다.","changelog.7294c9f3bc34":"수정 - 브라우저의 내보내기 버튼이 파일을 쓸 수 없던 문제, 2026-09-16","changelog.f9ee85761134":"브라우저에서 곡 탭의 내보내기를 누르면 매번 <em>“쓸 생성 결과가 없습니다”</em>라고 했습니다: 하나의 스토어가 플러그인과 탭을 함께 맡아 <code>{ song }</code>을 보내는데, 탭의 파일 계층은 아무도 보내지 않는 <code>files</code> 목록을 읽었습니다. 이제 드래그가 이미 쓰던 명령으로 렌더링하므로, 내려받는 파일과 끌어내는 파일이 같은 바이트입니다.","changelog.98dc5d6ecb9c":"수정 - 브라우저의 곡 탭에 <code>.mid</code>를 놓으면 엉뚱한 것이 저장되던 문제, 2026-09-16","changelog.f322f30777de":"<code>explorer_song</code>, <code>explorer_midi_split</code>, <code>explorer_midi_audition</code>이 모두 <em>분할</em> 결과로 응답받아, 곡 탭은 편곡이 들어갈 자리에 파트 목록을 받았습니다.","changelog.cd2c30298eab":"⚠ 두 버그 모두 그대로 출시되었습니다. 그 버튼들을 다루는 스펙이 올바르게 응답하는 목(mock)을 상대로 돌기 때문입니다. 탭의 파일 계층에는 테스트가 아예 없었습니다. 이제는 이름이 아니라 <strong>형태</strong>를 단언합니다. 두 버그 모두에서 이름 관문은 초록이었기 때문입니다.","changelog.992288d62132":"수정 - 방장의 강제 음소거가 아무에게도 동작하지 않던 문제, 2026-09-15","changelog.91b56d408438":"강제 음소거, 강제 카메라 끄기, 룸에서 내보내기는 아무것도 하지 않고 아무것도 보고하지 않는 세 버튼이었습니다: 페이지는 작성된 이래 줄곧 <code>collab_force</code>와 <code>collab_remove</code>를 요청했지만, 플러그인은 어느 쪽에도 응답하지 않았습니다. 페이지는 모든 거부를 <em>“사이드카가 없음”</em>으로 읽으므로, 누구도 오류를 본 적이 없었습니다 — 멈춰 버린 열린 마이크를 닫으려던 방장조차도. 이제 둘 다 응답하며, 형식이 잘못된 인자는 기본값으로 처리하지 않고 거부합니다. 여기서의 모든 기본값은 다른 사람의 카메라에 관한 결정이기 때문입니다.","changelog.63b986d4078b":"수정 - 다크 테마에서 아무도 읽을 수 없던 법적 고지, 2026-09-15","changelog.362a34927497":"로스터 콤보박스 아래의 이름 표기 고지는 약 10.9px인데, 팔레트가 큰 글자용으로 남겨 둔 <strong>흐린</strong> 단계로 칠해져 있었습니다. 측정값은 <strong>4.33:1</strong>로, 작은 글자에 필요한 4.5:1에 못 미쳤습니다. 이제 본문 단계를 씁니다.","changelog.29cb2a06fe81":"⚠ 접근성 스위트는 라이트 테마로 돌아가는데, 거기서는 같은 선언이 5.78:1로 측정되어 통과했습니다. 그래서 이제 단위 단언이 세 테마를 모두 확인합니다.","changelog.97a64162696b":"수정 - 죽은 컨트롤을 감시하는 관문이 협업 기능을 보지 못하던 문제, 2026-09-15","changelog.b5db170b03d8":"<code>bridge_names.rs</code>는 프런트엔드의 모든 <code>invoke('name')</code>을 긁어모았습니다 — 그런데 협업 모듈은 모두 헬퍼를 통해 <em>상수</em>를 넘깁니다. 바로 철자 하나가 세 호출 지점에서 따로 놀지 않게 하려는 것입니다. 그 이름들을 안전하게 만든 관례가 바로 그 이름들을 숨겼고, <strong>출시된 컨트롤이 호출하는데 아무것도 응답하지 않는 명령이 일곱 개 있었습니다.</strong> 이제 관문은 상수를 해석합니다. 둘은 위에서 고쳤고, 나머지 다섯은 각각 아직 만들어지지 않은 이유와 함께 테스트에 나열되어, 그 빈틈이 잊히는 대신 실행 가능한 형태로 이름 붙어 있습니다.","changelog.2296e280a445":"변경 - 내보낸 패턴의 트랙 이름이 “스타일”이라고 말합니다, 2026-09-12","changelog.b9aa73561b5e":"<code>.mid</code> <strong>안에</strong> 쓰이는 트랙 이름은 <code>trap — Drums</code>였는데, 이제 <code>trap style — Drums</code>입니다. 인터페이스와 파일 이름이 이미 하고 있는 구분입니다. 연주자의 이름은 스타일을 설명할 뿐, 이 앱을 떠나는 파일에 붙는 출처 표시가 결코 아닙니다.","changelog.a1c7a1a5e076":"⚠ 노트는 하나도 움직이지 않았습니다: 네 개의 골든 스냅샷은 각각 텍스트 6바이트만 다릅니다.","changelog.9d55f9efea57":"추가 - 파일 탐색기가 숫자와 함께 카테고리에서 열립니다, 2026-09-11","changelog.8fe51cad16bc":"예전에는 엔진이 들고 있던 순서 그대로, 개수도 없이 악기 계열에서 열렸고 — 라이브러리 선반, 루프 팩, 드럼 킷은 악기 브라우저 <em>안에</em> 그려진 폴더 트리여서, 팩토리 팩에는 맨 위에서 아예 닿을 수 없었습니다.","changelog.0297cd02ea56":"이제는 <strong>카테고리</strong>에서 열립니다. 장소마다 한 줄이고, 각 줄은 그 안에 얼마나 있는지 말해 줍니다: <strong>악기</strong>와 네 개의 <strong>팩토리 확장</strong>(각각 248과 350), <strong>드럼 팩</strong>(킷 11개, 원샷 407개, 처음으로 미리 들을 수 있음), 그리고 <strong>팩토리 팩</strong>(MIDI 루프 5,085개). 줄은 열여덟 개 언어 중 어떤 언어를 쓰든 그 언어의 사전순으로 정렬되며, 연결이 끊긴 드라이브는 자리를 지키면서 색만이 아니라 글자로도 <strong>사용할 수 없음</strong>이라고 표시됩니다.","changelog.830c1bfc1fee":"개수는 엔진에서 필터 없이 옵니다 — 칩을 거치고 남은 것이 아니라 선반에 있는 것 — 그래서 <em>베이스라인</em>을 눌러도 바뀌지 않습니다.","changelog.371bd3942abc":"⛔ 같은 변경으로 고쳐진 것: 선반들이 서로 새어 들어가 있었습니다. <em>팩토리 확장 2 → 건반</em>이 다섯 선반 모두의 건반 악기를 전부 나열했습니다. 선반이 화면에서는 폴더였지만 쿼리에서는 아무것도 아니었기 때문입니다.","changelog.30193f2cd07f":"변경 - 인터페이스가 “아티스트”가 아니라 “스타일”이라고 말합니다, 2026-09-11","changelog.61bd40930314":"남아 있던 레이블 아홉 개가 <em>스타일</em>을 뜻하면서 <em>아티스트</em>라고 말하고 있었습니다 — <em>“아티스트의 템포 사용”</em>, <em>“아티스트가 쓰는 대로”</em>. 그중 여덟은 실존 인물에 대한 주장을 하고 있었습니다. 이제 아홉 개 모두 열여덟 개 언어 전부에서, 각 언어의 고유한 단어로 스타일을 가리킵니다.","changelog.094d4fef1e50":"추가 - 열여덟 개 언어로 된 문서 사이트, 2026-09-11","changelog.3ec2581c410e":"모든 페이지에 언어 선택기가 있어, 플러그인과 같은 열여덟 개 언어를 각자의 이름으로 제공합니다.","changelog.d7aa7f80c47a":"수정 - 내보내기 이름을 정해도 더는 브라우저 탭의 설정이 깨지지 않습니다, 2026-09-11","changelog.8269f52c0420":"내보내기 이름 패널이 탭에 이름 템플릿을 요청했다가 자신이 읽는 것과 다른 형태를 받아, 설정 패널 전체를 함께 무너뜨렸습니다. 탭에는 이름 템플릿이 없으므로 — 그 내려받기 이름은 엔진에서 정해집니다 — 이제 그렇다고 말하고 그 섹션을 뺍니다.","changelog.756e358cd7bf":"수정 - 종이 짧게 끊기지 않고 종답게 울립니다, 2026-09-10","changelog.f454ead481c6":"교회 종은 자신의 부분음들이 9초 동안 울리도록 조율되어 있는데도 3.2초만 울렸습니다: 건반을 놓으면 댐퍼가 걸렸는데, 탑의 종에는 댐퍼가 없습니다. 공, 오케스트라 벨, 스틸 팬, 핸드팬도 마찬가지였습니다. 이제 교회 종은 6.6초 울리며, 실제로 댐핑되는 악기는 건드리지 않았습니다. 그 악기들은 소리를 짧게 끊는 것이 핵심이기 때문입니다.","changelog.bf56e0465d30":"이 수정이 드러낸 결함 두 가지: <em>모두 멈추기</em>가 그 악기들에서 동작하지 않아 패닉이 공을 최대 음량으로 울린 채 남겨 두었습니다 — 이제 패닉과 건반 놓기는 서로 다른 것입니다 — 그리고 타격 악기를 벤드하면 음량이 최대 7 dB까지 바뀌었습니다. 울리고 있는 공명기를 다시 조율하면 레벨도 함께 움직이기 때문입니다.","changelog.721f6099a36a":"⚠ 알려져 있고 고치지 않은 것: <em>Bell</em>이나 <em>Chime</em>이라는 이름의 라이브러리 악기 118개 중 107개는 종의 비화성 부분음이 아니라 화성 오실레이터로 만들어져 있습니다. 생성기는 모델링된 것만 사용합니다.","changelog.a3790f42036f":"수정 - 피치 벤드 노브가 이제 실제로 벤드하고, 놓은 자리에 머뭅니다, 2026-09-10","changelog.7eae79e5967e":"<strong>열세 개 악기 엔진 중 열두 개가 피치 휠을 완전히 무시했습니다</strong> — 모든 벨, 기타, 찰현 악기, 금관 악기, 피아노, 오르간, 보이스, 드럼 머신, 캐릭터 악기가, 화면의 노브<em>와</em> 하드웨어 컨트롤러 양쪽 모두에서. 모델링된 악기는 음높이를 한 번 전달받을 뿐, 그 뒤로 휠 값을 전해 주는 것이 없었습니다. 이제 벨의 부분음, 기타의 현 길이, 가수의 목소리가 모두 움직이고, 노트를 따르지 않는 부분은 그대로 있습니다 — 바이올린의 몸통, 보컬의 포먼트, 칼림바의 울림통.","changelog.28b122d799de":"<strong>그리고 노브가 더는 당신이 한 것을 되돌리지 않습니다.</strong> 놓으면 가운데로 튕겨 돌아갔는데, 그것은 숨겨진 스프링 휠이 하는 일이지 값이 표시되는 화면 노브가 하는 일이 아닙니다. 이제 위치를 유지하며, 다른 모든 노브처럼 더블클릭하면 가운데로 돌아갑니다.","changelog.bfc70626288e":"⚠ 그 결과 두 번째 결함에 닿을 수 있게 되었고, 그것도 여기서 고쳤습니다: 공명 코드 뱅크 악기에서 휠을 잡은 채 연주한 프레이즈의 <em>두 번째</em> 노트가 완전5도 높게 나왔습니다. 전에는 다음 건반이 눌릴 때 휠이 여전히 잡혀 있을 수 없었으므로, 아무것도 이를 찾을 수 없었습니다.","changelog.5acc9d14ec6b":"수정 - 가상 건반이 주어진 공간을 채웁니다, 2026-09-10","changelog.d414fd02f3e7":"피아노가 가로로 중간까지만 가다 멈추고 오른쪽 가장자리에 붙어 있었습니다: 그 행은 자식의 크기를 각자의 내용에 맞추므로, 건반의 너비가 앱의 너비가 아니라 그 위의 작은 옥타브 컨트롤만 했습니다. 이제 어떤 크기에서든 컨테이너를 채웁니다.","changelog.06900e6126d2":"추가 - 팩토리 팩 루프를 패턴으로 바로 끌어 넣기, 2026-09-10","changelog.e811e0ddcc9f":"팩 브라우저에는 MIDI 루프 5,085개가 들어 있고 하나하나 재생하고 <strong>밖으로</strong> 끌어 DAW에 넣을 수 있었지만 — <strong>안으로</strong> 들여올 방법은 없어서, 원하는 비트를 듣고 나서 손으로 다시 만들어야 했습니다. 이제 모든 루프 행이 드래그 소스입니다: 생성기에 놓으면 파일 탐색기의 <code>.mid</code>와 똑같이 올바른 파트들로 나뉘어 들어갑니다.","changelog.aa75d339c210":"⚠ 곡 탭은 루프를 거부하고 커서로 그렇다고 알립니다: 곡 탭은 파일의 구간들로 편곡을 만드는데, 네 마디짜리에는 구간이 없습니다.","changelog.470ee0ab09bc":"수정 - 상대방의 공유 폴더를 열 수 있고, 배지가 사실을 말합니다, 2026-09-09","changelog.184268a38575":"공유 탐색기는 지난 릴리스에서 클라이언트를 얻었지만 동작할 수가 없었습니다. 결함은 세 가지였고 모두 보이지 않았습니다. 목 브라우저에는 <em>페이지</em> 형태의 행이 손으로 먹여졌고, 그것을 플러그인이 보낸 것과 비교하는 것이 없었기 때문입니다.","changelog.a159c8fdb762":"<strong>어떤 폴더도 열 수 없었습니다.</strong> 플러그인은 <code>isDir</code> 없이 <code>kind: &quot;folder&quot; | &quot;sound&quot;</code>로 응답했는데, 창은 바로 그 값을 읽어 펼침 삼각형을 그립니다 — 그래서 모든 공유 루트가 파일로 그려졌고, “이것을 가지고 있나요?”라는 질문이 디렉터리를 두고 던져지고 있었습니다.","changelog.806039630970":"<strong>모든 파일이 1초도 안 되는 길이라고 주장했습니다.</strong> 행의 길이 필드는 길이가 아닙니다: 원샷과 네 마디 루프를 비교할 수 있도록 길이를 로그로 0~1에 접어 넣은 값입니다. 그것이 “0.35s”로 그려졌습니다. 이제 실제 정체대로 이름 붙고 단위 없이 표시됩니다.","changelog.56c9265a4563":"<strong>“비슷한 것을 가지고 있습니다”가 결코 나타날 수 없었습니다.</strong> 그러려면 소리를 묘사하는 네 개의 숫자가 필요한데 지문만 보내졌으므로, 상대가 WAV로 가진 팩을 FLAC으로 가진 프로듀서가 그것을 가지고 있지 않다는 말을 들었습니다.","changelog.ddf9187bb139":"⚠ 소유자의 규칙은 그대로입니다: <strong>두 사람 사이에 샘플 바이트는 하나도 건너가지 않습니다</strong> — 지문 16바이트와 숫자 넷뿐입니다.","changelog.67c4f1f163e5":"수정 - Wi-Fi가 잠깐 끊겨도 더는 협업 세션이 끝나지 않습니다, 2026-09-09","changelog.658c8087a2ab":"패킷 하나가 빠지거나 노트북이 절전에서 깨어나는 것이 상대방이 떠난 것으로 취급되었습니다. 연결은 아직 시도 중일 때 “disconnected”를 보고하는데 — 명시적으로 일시적인 상태이고 보통 저절로 풀립니다 — 사이드카는 그 첫 보고에서 링크를 끊어 버렸습니다. 이제 가진 주소를 8초 동안 다시 확인하므로, 짧은 끊김은 보이지 않습니다. 그보다 길면 여전히 진짜 떠남입니다: 자리, 핸들, 색은 예전처럼 2분 동안 유지됩니다.","changelog.b55b8659f982":"수정 - 악기를 불러오면 건반과 노브가 나타납니다, 2026-09-09","changelog.0b543bd7a5ca":"생성기에 샘플을 놓거나 <code>Ctrl</code>+<code>Arrow</code>로 샘플을 연결하면 파트에 목소리가 생겼지만 — 그것을 다듬는 노브 줄은 탭을 바꿨다 돌아올 때까지 나타나지 않았습니다. 리버브, 딜레이, 드라이브, 피치 컨트롤이 “이 파트가 이제 소리를 내는가?”에 대한 묵은 답을 읽고 있었기 때문입니다. 이제 악기를 불러오면 화면 건반도 열리므로, 그것을 연주할 수단이 생깁니다.","changelog.1af1ee74267d":"변경 - 두 가지 드럼 동작이 그것을 위해 만들어진 아티스트에게 닿습니다, 2026-09-09","changelog.ec4815846944":"컴핑하는 스네어와 클랩으로 치는 백비트는 둘 다 만들어져 있었지만 어느 것에도 닿을 수 없었습니다 — 어떤 아티스트도 요청하지 않았기 때문입니다. 이제 Art Blakey가 컴핑합니다. 그의 연구 항목이 그렇게 묘사합니다. Trina와 Trick Daddy는 백비트를 클랩에 둡니다. 그들의 항목에 따르면 그것이 Miami bass가 하는 일입니다.","changelog.6858345a1f88":"수정 - 같은 프리셋이 이제 두 번 들어도 같은 소리입니다, 2026-09-06","changelog.daafbdc5a835":"프리셋을 미리 들으면 클릭할 때마다 조금씩 다른 소리가 났습니다 — 넓게 디튠된 텍스처 패드에서는 최대 <strong>네 배의 레벨</strong>까지. 새 소리를 시작하면 딜레이와 리버브는 초기화되었지만 모든 보이스의 무작위성은 계속 돌아갔고, 그 무작위성은 오실레이터가 주기의 어디에서 시작하는지<em>이자</em> 드럼을 이루는 노이즈이기도 하므로, 패드의 보이스들이 연주할 때마다 서로 다른 정도로 상쇄되었습니다. 이제 프리셋에서 시드를 얻습니다: 같은 소리를 두 번 내면 같은 소리이고, 노트끼리는 여전히 서로 다릅니다.","changelog.3f7eb09bb886":"⚠ 측정을 믿을 수 있게 되자 프리셋 두 개 — <em>Pluck Coin</em>과 <em>Frozen Cloud</em> — 가 미리 듣기에는 정말로 너무 조용하다는 것이 드러났고, 둘 다 조금 올렸습니다.","changelog.449f05332b7d":"수정 - 이제 중심에서 벗어난 악기가 없습니다, 2026-09-05","changelog.e606f1a76e95":"일부 사운드가 <strong>DC 오프셋</strong>이 들어간 채로 렌더링되어 있었습니다 — 파형이 중심선을 축으로 흔들리지 않고 중심선에서 벗어나 있었습니다. 미터에서는 음량으로 읽히고 귀에는 아무것도 아니며, 헤드룸을 잡아먹고, 화면의 어떤 것으로도 설명되지 않는 이유로 믹스를 이상하게 만듭니다. 가장 심한 것은 풀 스케일의 −0.26인 <em>Current Pad</em>였고, 확장 팩 전체에서 마흔 줄이 같은 모양을 공유했습니다. 모든 신스는 출력에서 이를 제거하며, 이제 Freally도 그렇습니다.","changelog.a6132c39d808":"⚠ 몇몇 패드가 더 조용해졌는데, 그것은 수정이 제대로 동작하는 것입니다 — 레벨의 일부는 오프셋이 새추레이터를 더 세게 밀어붙인 결과였습니다. 다시 보이싱한 것은 없습니다: 그 패드들은, 스웰이 끝나는 데 1.25초만 주고 스웰의 5분의 1 지점에서 측정한 레벨 검사에 걸렸던 것입니다. 이제 미리 듣기 플레이어처럼 4초 동안 듣습니다.","changelog.a91d6c053bff":"수정 - 노브, 건반, 그리고 다른 모든 드래그 컨트롤, 2026-09-05","changelog.c585e5feb470":"<strong>신스</strong> 페이지의 노브를 돌려도 아무 일도 일어나지 않을 수 있었습니다: 불이 켜지고, 포커스를 받고, 숫자를 보여 주었지만, 소리는 결코 바뀌지 않았습니다.","changelog.8794dd5d5b82":"모든 드래그 컨트롤은 제스처가 이어지는 동안 포인터를 붙잡아 달라고 OS에 요청하므로, 커서가 노브를 벗어나도 드래그가 살아남습니다 — 그런데 그 요청이 컨트롤이 스스로 준비되기 <em>전에</em> 이루어졌습니다. 요청이 거절되는 기기에서는 컨트롤이 아예 듣기 시작하지 않았고 제스처는 버려졌습니다. 열두 개 컨트롤이 이 결함을 공유했습니다: 노브, 건반 키, 드럼 그리드, 피아노 롤, 벨로시티 레인, 눈금자, 엔벨로프 편집기, 패드 편집기, 킷 행, 미리 듣기 스트립, 레일 크기 조절기, 곡 타임라인. 이제 먼저 준비하고 그다음에 요청합니다.","changelog.1ba8e646a9fb":"수정 - 피아노가 피아노처럼 들립니다, 2026-09-05","changelog.e02d9461473c":"모든 피아노가 건반 타격 대신 시작 부분에 웅웅거림이 있었습니다. 결함은 두 가지였고, 둘 다 추측이 아니라 측정한 것입니다:","changelog.0f157fbd683f":"<strong>노트가 최대 음량으로 도착해 그대로 머물렀습니다.</strong> 타격된 현은 첫 순간부터 잦아드는데, 이것은 그렇지 않았습니다 — 두 번째 5밀리초가 첫 번째보다 <em>더 컸습니다</em>. 현의 빠른 감쇠가 3초로 설정되어 있어 어택 근처에 꺾임을 둘 수 없었기 때문입니다.","changelog.96ba7fca5dbd":"<strong>배음이 거의 없었습니다.</strong> 가운데 C의 그랜드는 에너지의 0.5%만 2 kHz 위에 실었고 사인파에 아주 가까웠습니다. 10번째 배음은 60밀리초 만에, 30번째는 14밀리초 만에 사라졌습니다.","changelog.85ae339fad0a":"이제 해머는 더 크고 밝으며, 업라이트보다 그랜드에서 더 밝습니다. 그것이 두 액션의 차이입니다. 유니슨 현들은 더 가깝게 조율되었습니다 — 예전의 퍼짐은 노트마다 충분히 들쭉날쭉해서 흔들림으로 들렸습니다.","changelog.7f16b5debe9e":"수정 - 파일 브라우저 아래의 재생 버튼, 2026-09-05","changelog.032dc3a33890":"브라우저 아래의 재생 버튼과 안쪽의 재생 버튼이 서로 다른 일을 했고, 바깥쪽이 틀렸습니다: MIDI 파일에서 그것은 마지막으로 미리 들은 <code>.wav</code>를 MIDI 파일의 이름으로 재생했습니다. 이제 둘 다 같은 입구를 거칩니다.","changelog.6e3d80e0d484":"수정 - 리버스가 클립을 거꾸로 보여 줍니다, 2026-09-05","changelog.7fc0fa7a1923":"<strong>리버스</strong>를 켜면 소리는 바뀌었지만 그림은 그대로여서, 분명하게 보이는 것이 임무인 바로 그 컨트롤이 아무것도 보여 주지 않았습니다. 이제 리버스가 켜져 있는 동안 파형은 끝부터 그려지고, 재생 헤드는 여전히 왼쪽에서 오른쪽으로 움직이며, 피크를 클릭하면 클릭한 그 피크가 재생됩니다.","changelog.a67a54c25c17":"추가 - 음성 채팅이 마이크와 스피커를 찾을 수 있습니다, 2026-09-05","changelog.10fcf618e62d":"협업의 음성 쪽에는 하드웨어만 빼고 다 있었습니다: 에코 캔슬러, 노이즈 게이트, 코덱, 지터 버퍼가 모두 만들어져 있었지만 아무것도 그것들을 구동하지 않았습니다. 이제 세션 도우미가 기기가 보고하는 마이크와 출력 장치를 나열하고, 고른 한 쌍을 열고, 음성을 끄는 순간 닫습니다 — 그래서 인터페이스의 불빛이 꺼져야 할 때 꺼집니다. 출력은 마이크와 별개로 고릅니다. 모니터와 헤드폰은 다른 것이기 때문입니다.","changelog.0772f73fd745":"⚠ 음성 채팅에는 장치가 48 000 Hz여야 합니다. 그렇지 않으면 Freally는 조용히 실패하는 대신 장치와 레이트를 밝힙니다.","changelog.1ff4564ad0c5":"수정 - 창이 바쁠 때도 재생 헤드 표시가 더는 멈추지 않습니다, 2026-09-05","changelog.a38a827fadc1":"독립 실행 버전의 제목 표시줄을 끌면 놓을 때까지 재생 헤드가 멈췄다가 앞으로 건너뛰었습니다 — 재생이 멈췄다 다시 시작한 것과 똑같아 보였습니다. 그렇지 않았습니다. 소리는 내내 재생되었습니다. 표시는 1초에 서른 번 플러그인에 위치를 묻고 <em>기다렸는데</em>, Windows에서 창을 옮기면 앱의 창 루프가 막히므로, 오디오 스레드는 한 박자도 놓치지 않는 동안 답이 도착하지 않았습니다. 이제 답과 답 사이에는 템포로 계속 움직이고, 답이 도착하면 스스로 바로잡습니다.","changelog.8360bb400211":"⚠ 같은 멈춤은 DAW의 창이 바쁠 때면 언제든 일어날 수 있었으므로, 이것은 드래그만의 문제가 아닙니다.","changelog.df274a80a110":"추가 - 당신의 샘플을, 당신의 선반에, 2026-09-05","changelog.10a7ad8818d9":"원샷을 보관하는 폴더를 Freally MIDI Master에 알려 주면, 그중 어느 것을 악기로 연주할 수 있는지 알아냅니다. 카테고리에서 <strong>내 폴더에서 악기 찾기</strong>를 누르세요. 진행 상황을 알려 주며 언제든 멈출 수 있습니다. 바뀌지 않은 폴더를 다시 훑는 것은 즉시 끝납니다. 찾은 것은 네 개의 팩토리 확장 아래, 당신의 이름이 붙은 당신만의 선반에 놓입니다.","changelog.9d27db12ab2d":"⚠ 조용한 샘플도 유지됩니다 — 조용함은 당신의 선택이고, 소리가 전혀 없는 파일만 거부됩니다. 10초를 넘는 것은 빠집니다: 샘플을 낮게 연주하면 <em>늘어나므로</em>, 8초짜리 패드를 한 옥타브 낮추면 노트마다 16초를 붙잡게 됩니다.","changelog.6209b0e7418a":"⚠ 스캔에는 플러그인이나 독립 실행 버전이 필요합니다. 브라우저 탭은 한 번에 폴더 하나만 열 수 있고 새로 고치면 잊어버리므로, 훑을 라이브러리가 없습니다.","changelog.376464b49a86":"추가 - 앱이 선반 이름을 묻습니다, 2026-09-05","changelog.f7195bf33438":"Freally MIDI Master를 처음 열면 라이선스 바로 다음에 선반 이름을 무엇으로 할지 묻고, 답하기 전에는 생성하지 않습니다. 저장하는 모든 것은 그 이름 아래에 놓이고, 이름을 바꾸면 선반 이름이 바뀝니다 — 아무것도 옮겨지지 않고 아무것도 잃지 않습니다.","changelog.f38da5062167":"⚠ 기기가 앱이 이름을 저장하도록 허락하지 않으면, 세션 동안만 유지하고 그렇다고 말한 뒤 계속하게 해 줍니다. 쓸 수 없었던 파일 때문에 막히는 일은 결코 없습니다.","changelog.bf9a5273bae3":"추가 - KIT 패널이 샘플이 미끄러질 때 알려 줍니다, 2026-09-05","changelog.53f56fa197ef":"라이저나 미끄러지는 808을 멜로딕 패드에 놓으면, 앱은 예전에 그 안에서 자신 있게 노트 하나를 찾아낸 뒤 모든 건반에서 그 슬라이드를 연주했습니다 — 건반마다 다른 음정으로. 이제 샘플이 음높이를 <em>유지하는지</em> 측정하고 패드 아래에 그렇게 알립니다: <strong>“이 샘플은 한 음높이를 유지하지 않으므로, 모든 건반이 그 슬라이드를 연주합니다.”</strong> 파일을 거부하지 않고 알려 줍니다: 슬라이드도 연주할 가치가 있으며, 다만 악기가 아닐 뿐입니다.","changelog.74c665daca9f":"추가 - 사람 드러머 뒤에 있는 숫자들, 2026-09-05","changelog.6f4d1b6a2a74":"<code>data/humanize/groove.json</code>은 실제 드럼 연주 1,150개가 실제로 하는 것을 담고 있습니다 — 스타일마다 스윙 비율, 그리고 드럼마다 킷의 나머지에서 얼마나 떨어져 있는지, 얼마나 흔들리는지, 고스트·메인 타격·악센트가 각각 얼마로 측정되는지. <strong>당신이 만든 것은 아무것도 바뀌지 않습니다</strong>: 출시된 아티스트 중 새 숫자를 쓰는 것이 없으므로, 모든 시드는 예전에 다시 만들던 비트를 그대로 다시 만듭니다.","changelog.6ad4570e7118":"⚠ 들리는 발견이 하나 있습니다: 측정한 모든 스타일에서 드러머의 하이햇 페달은 킷의 나머지보다 7–20 ms 앞서 떨어집니다. 그리고 의도적으로 빠진 것이 하나 있습니다 — 드러머가 흔들리는 정도는 재즈든 펑크든 약 15 ms이므로, 장르별 느슨함 표가 없습니다. 장르별 느슨함이란 없기 때문입니다.","changelog.21279277c064":"추가 - 스타일을 만드는 동안 들어 보기, 2026-09-05","changelog.95e2355db08d":"트랜스포트가 돌아가는 동안 스타일 편집기는 당신이 만드는 것을 만드는 그대로 연주합니다 — 스윙 슬라이더를 움직이거나 스네어 위치를 바꾸면 다음 루프는 방금 묘사한 스타일입니다. 그러는 동안 아무것도 저장되지 않으며, 편집기를 닫는 순간 스타일을 저장했든 안 했든 당신의 테이크가 돌아옵니다. 미리 듣기는 소리일 뿐, 변경이 아닙니다.","changelog.23f920ae884b":"추가 - 휴대전화가 데스크에 MP3를 요청할 수 있습니다, 2026-09-04","changelog.e2666ce60865":"MixSir는 언제나 자신의 재생을 WebM으로 녹음할 수 있었고, 이는 어디서나 동작하지만 무엇으로도 고칠 수 없는 결함이 하나 있습니다: <strong>실시간</strong>으로 녹음하므로, 3분짜리 곡은 3분이 걸렸습니다. 이제 데스크와 같은 네트워크에 있으면, 오디오를 가진 기기에서 오프라인으로 인코딩된 <strong>MP3</strong>를 그냥 내려받을 수 있습니다. 스템마다 자신의 버튼이 있어서, 누군가에게 베이스라인을 보내는 일이 40 MB WAV가 아니라 한 번의 탭입니다.","changelog.a0fab848af1f":"⛔ 파일 셋, 의미 셋, 버튼 아래에 이름이 적혀 있습니다: <em>믹스 저장</em>은 방금 맞춘 밸런스를 휴대전화에서 렌더링하고, <em>작게 저장</em>은 그 밸런스를 실시간으로 WebM에 담으며, <em>데스크 믹스 — MP3</em>는 <strong>생성된 그대로의</strong> 테이크로, 모든 페이더가 유니티입니다. 이들을 헷갈리면 10분 들인 믹스를 조용히 버리게 됩니다. 스템은 예외이고, 그래서 가장 좋습니다: 유니티의 스템이 <em>곧</em> 스템입니다.","changelog.a33866df627b":"⚠ 플러그인에는 아무것도 추가되지 않았습니다 — 인코더는 동반 프로그램 안에서 자체 기능 플래그 뒤에 있으며, 그렇지 않게 되면 검사가 실패합니다.","changelog.fef58795ee93":"변경 - 새로움 가드가 7개가 아니라 47개 멜로디를 대조합니다, 2026-09-04","changelog.cada7f45de77":"생성기가 쓰는 모든 멜로디는 그 <em>모양</em> — 음정과 온셋 사이 간격의 연속 — 으로 지문이 찍히고, 당신이 듣기 전에 함께 실린 표와 대조됩니다. 일치하면 버리고 다시 뽑습니다. 처음에는 퍼블릭 도메인 멜로디 일곱 개와 지문 104개로 출시되었는데, 스위치는 동작하지만 뒤에 거의 아무것도 없었습니다. 이제 <strong>멜로디 47개와 지문 834개</strong>를 담고 있으며, 여전히 약속한 5밀리초 안에 끝납니다.","changelog.43f8d897f696":"⛔ <strong>이것이 아닌 것.</strong> 표의 모든 멜로디는 영구적으로 퍼블릭 도메인입니다: 상업적인 훅과 대조하려면 그 훅의 윤곽을 끌어내야 하는데, 윤곽 목록은 <em>곧</em> 노트 데이터입니다 — 이 제품이 절대 실어서는 안 되는 단 한 가지. 가드는 잘 알려진 멜로디를 우연히 인용하는 것을 잡아냅니다. 출력이 독창적인 이유는 이것이 <strong>아닙니다</strong>. 그 이유는 엔진이 규칙 기반이고 사슬 어디에도 녹음이 없다는 데 있습니다.","changelog.239a6df00f04":"추가 - 팩토리 확장 팩 네 개, 음높이를 바꿀 수 있는 새 악기 1,400개, 2026-09-04","changelog.0790681bb3a3":"<strong>라이브러리가 악기 248개에서 1,648개로, 프리셋 410,688개에서 2,729,088개로 늘어납니다</strong> — 여전히 디스크에는 파일이 하나도 없습니다. 모든 프리셋이 주소로부터 계산되기 때문입니다. 익숙한 폴더에 쏟아붓는 대신 새 선반 넷으로 도착합니다: 감산 아날로그, FM과 초기 디지털, 텍스처·테이프·더스트, 그리고 보이스와 월드 악기의 몸통에 다른 무엇도 쓰지 않는 두 음역.","changelog.fb5ae337c7b0":"<strong>프리셋이 아니라 기계처럼 들립니다</strong>. 첫 초안에는 그렇게 만드는 네 가지가 하나도 없었습니다: 오실레이터가 <strong>자유롭게</strong> 돌아 두 노트가 똑같이 시작하지 않고, 필터가 <strong>건반을 추적하며</strong>, <strong>벨로시티가 필터를 엽니다</strong> — 레벨만 올리는 것은 합성 악기임을 드러내는 가장 흔한 표시입니다 — 그리고 두 번째 LFO가 음높이에 1~2센트의 드리프트를 얹습니다. 비브라토가 아니라, 그저 패치가 살아 있다는 것.","changelog.23d9f8efe0a6":"어떤 것도 다른 것처럼 들리지 않으며, 이는 측정됩니다: 기존 관문은 모든 악기를 69개 장르 전부에서 모든 변주로 렌더링하고, 두 개라도 같은 지문에 떨어지면 실패합니다.","changelog.63aed5e7b3ac":"추가 — Freally MIDI Master가 브라우저에서 돌아갑니다, 2026-09-03","changelog.6392d72ebb78":"<strong>앱 전체가, 탭 하나에, 설치할 것 없이</strong> — 데모도 아니고 축소판도 아닙니다. 브라우저는 WebAssembly로 컴파일된 <strong>플러그인과 같은 크레이트</strong>를 돌리므로, 탭에서 생성한 비트와 DAW에서 생성한 비트는 같은 바이트입니다. 이것은 약속이 아니라 관문입니다: <code>web_parity</code>는 양쪽에서 생성해 <code>.mid</code>를 거부까지 포함해 바이트 단위로 비교합니다.","changelog.29825d1f51d3":"⛔ <strong>브라우저가 할 수 없는 두 가지</strong>를, 힘들게 알아내기 전에 밝혀 둡니다: 탭에는 호스트 트랜스포트가 없으므로 <strong>DAW 따르기</strong>가 없고, 클립을 DAW 트랙에 바로 놓을 수 없습니다. 두 한계 모두 앱 안과 설정 → 정보에 나옵니다.","changelog.db4a975527be":"라이브러리는 탭에 온전히 — <strong>프리셋 410,688개</strong> — 도착하며, 전달에 드는 비용이 없습니다. 하나하나가 저장된 것이 아니라 계산되기 때문입니다. 한 번 방문한 뒤에는 네트워크가 꺼진 상태에서도 생성하고, 자신만의 창으로 설치됩니다. <strong>오프라인 헌장도 같은 변경에서 수정됩니다</strong>: 페이지는 네트워크로 <em>전달되지만</em>, 생성은 당신의 기기에서 일어나고, 당신이 만든 것은 무엇도 업로드되지 않습니다.","changelog.7fc622405ce4":"<strong>생성 입구가 <code>engine</code>으로 옮겨졌습니다.</strong> <code>generate</code>, <code>generate_song</code>, <code>reroll_section</code>은 <code>plugin/src/bridge.rs</code>의 앞쪽 절반이었는데, 이제 두 표면이 함께 호출하는 <code>engine::compose</code>이므로 탭과 DAW가 따로 놀 수 없습니다.","changelog.24935964d5ea":"<strong>악기 라이브러리가 독립된 크레이트가 됩니다.</strong> <code>freally-library</code>가 프리셋, 분류 체계, 파트별 보이스, WAV 인코더, 드럼 킷을 담습니다. 플러그인은 예전에 있던 자리에서 이를 다시 내보냅니다.","changelog.acd41991926e":"<strong>두 로컬 CI 러너 모두에 새 관문 둘</strong>: wasm 타깃이 빌드되고, 탭이 데스크톱과 휴대전화 크기의 실제 브라우저에서 처음부터 끝까지 구동됩니다.","changelog.4aec523a2a62":"추가 — 이제 악기가 음반처럼 들립니다, 2026-09-02","changelog.6d0a65060c37":"팩토리 악기들을 전문 샘플의 측정값에 맞춰 다시 조율했습니다 — 하이햇이 얼마나 오래 울리는지, 킥의 무게가 어디에 있는지, 말렛이 어떻게 감쇠하는지. 프로듀서들은 그중 몇몇을 건너뛰고 다른 것을 골라 왔는데, 숫자가 그 이유를 말해 줍니다: 드럼 머신 하이햇이 <strong>실제보다 3~5배 짧아서</strong>, 햇이 아니라 클릭으로 들렸습니다.","changelog.b042e5f2df6f":"<strong>더 큰 이야기는 네 엔진 밑에 있던 버그였습니다.</strong> 모달, 타악기, 월드 타악기 엔진의 <code>decay</code>와 임팩트 엔진의 <code>length</code>는 각각 중립값이 1.0인 <em>배수</em>로 문서화되어 있는데 — 모두 상한 1.0으로 잘려 있었습니다. <strong>라이브러리의 어떤 소리도 실제 악기보다 오래 울릴 수 없었습니다.</strong> 마림바는 기준값 510 ms에 대해 250 ms로 측정되었고, 모델이 아무리 밀어도 움직이지 않았습니다. 넷 모두 고쳤고, 상한이 돌아오면 실패하는 관문도 두었습니다.","changelog.ef8652a0758c":"이제 <strong>악기 248개</strong>(225개에서 늘어남), <strong>프리셋 410,688개</strong>입니다. 피치 변조를 찾을 수 있습니다: 91개는 반응하고 157개는 반응하지 않으며, 라이브러리가 이것으로 필터링하고, 이를 가진 모든 행에 표시가 붙습니다.","changelog.3632677bb11b":"추가 — 팩토리 팩의 MIDI 루프 5,085개, 2026-09-02","changelog.81f74a7b5aa1":"생성하고, 듣고, 다시 생성하는 대신 드럼, 퍼커션, 베이스, 코드, 멜로디, 카운터멜로디 루프를 훑어보고 들어 보세요. <strong>하나하나가 이 앱의 생성기가 자신의 스타일 모델로 쓴 것입니다</strong> — 남의 녹음 1기가바이트가 아니라 노트 9메가바이트. 루프를 고르면 재생되고 목록은 화면에 남으므로, 폴더 하나를 처음부터 끝까지 죽 훑을 수 있습니다.","changelog.00e23d8a58a2":"<strong>먼저 고쳐야 할 것이 둘 있었습니다.</strong> 브라우저는 폴더를 그렸지만 행을 클릭해도 아무 일도 없었습니다 — 렌더러와 파일 리더가 둘 다 완성되어 있었는데 어느 쪽도 연결되지 않았습니다. 그리고 연결하고 나니 모든 루프가 폴더와 상관없이 <em>드럼</em> 루프로 읽혔는데, 이는 생각보다 나쁩니다: 표준 맵에서 베이스라인은 킥, 스네어, 클랩, 햇이 있는 바로 그 자리에 놓이므로, 파일과는 다른, 완전히 그럴듯한 비트로 재생되었습니다.","changelog.c666d6acd7c9":"추가 — 아티스트와 프로듀서 189명 추가, 2026-09-02","changelog.b172c11f2b00":"dancehall 리딤 빌더, amapiano, Jersey club, drum &amp; bass, house, reggaeton, 그리고 Detroit와 Michigan 계열. 이제 <strong>스타일 모델 2,413개</strong>가 실립니다.","changelog.1f6f98bb4f11":"수정 — 누른 건반이 멈추지 않던 문제, 2026-09-02","changelog.efe64f0af95b":"생성기의 피아노 롤 옆 건반을 누르면 끝나지 않는 노트가 울렸습니다. 이제 마우스를 놓으면 멈추고, 끌어서 벗어나거나 창이 포커스를 잃거나 패널이 닫혀도 멈춥니다. 건반 레이블도 제대로 표시됩니다: 두 건반 모두에서 검은 건반에는 흰 글씨, 흰 건반에는 검은 글씨.","changelog.0e9f1cb9b77e":"수정 — 루프 브라우저가 빈 채로 출시될 뻔한 문제, 2026-09-02","changelog.f2656c4e7099":"루프 팩이 앱에 두 번 컴파일되던 것 — 모든 빌드에서 9메가바이트 — 을 막은 변경이 루프 팩을 아예 찾지 못하게도 만들었습니다. 브라우저는 빈 트리를 그렸을 것입니다. 코드를 믿지 않고 파일 수를 세는 테스트가 잡아냈습니다.","changelog.203799973680":"변경 — 테스트 스위트가 훨씬 짧은 시간에 돕니다, 2026-09-02","changelog.f050d1cd9b2a":"프로듀서가 보는 것은 없지만, 실수를 몇 분 만에 잡느냐 한 시간 만에 잡느냐의 차이입니다. 한 관문은 모든 모델의 마디를 비교 대상인 다른 모델마다 한 번씩 다시 생성했습니다 — <strong>435초에서 1초로</strong>. 이제 다양성 스위트는 모든 코어를 씁니다: 멜로디 <strong>576s → 60s</strong>, 카운터멜로디 <strong>800s → 66s</strong>. 로컬 CI 러너는 저렴한 검사를 먼저 돌리므로, 서식 실수는 Rust 스위트 전체가 끝난 뒤가 아니라 몇 초 만에 보고됩니다.","changelog.fc2bc79afd01":"수정 — 다양성 관문이 69개 장르 중 하나만 다루던 문제, 2026-08-31","changelog.909b99ff0cc9":"관문은 House만 돌렸습니다. Trap에는 똑같이 들리는 서브 베이스가 있었는데, 그 근처를 전혀 보지 않았으니 아무것도 찾지 못했습니다. 이제 <strong>장르마다 <code>#[test]</code> 하나</strong> — 69개 — 가 <strong>프리셋 372,600개</strong>를 훑습니다. 모두 초록으로 만드는 데 네 차례가 걸렸습니다:","changelog.128cc96e56d9":"<strong>여덟 쌍의 악기가 같은 매개변수의 모델 변형을 공유했습니다</strong> — 그중에는 <code>Bell</code>/<code>ChurchBell</code>, <code>GrandPiano</code>/<code>AcousticPiano</code>가 있습니다. 비슷한 것이 아니라 이름 둘을 단 같은 패치였고, 이제 각각 실제로 그 둘을 구분하는 것으로 갈라졌습니다.","changelog.b445820a134e":"<strong>지터를 넓히는 것은 세 번이나 틀린 직감이었습니다.</strong> 실패한 장르가 56개에서 13개로 줄었지만, 마지막 13개는 두 번의 뽑기가 우연히 가깝게 떨어진 것이었습니다 — 지터를 늘리면 그럴 가능성이 줄어들 뿐 결코 불가능해지지 않습니다. 이제 각 변주는 악기의 두드러진 범위에서 자신만의 <strong>조각</strong>을 가집니다.","changelog.34ce292c4fde":"⚠ 관문의 해상도는 보고된 것 — 1.0000으로 상관된 <code>Sub808</code>의 스물네 개 — 을 잡을 만큼 정밀하지만, 귀로 들어 다른 두 마림바가 <em>충분히</em> 다른지까지 판정하지는 않습니다.","changelog.e0c180b1af50":"수정 — 악기가 69개 장르 모두에서 같은 소리를 내던 문제, 2026-08-31","changelog.36341f1261ab":"측정 결과는 냉혹했습니다: <code>Sub808</code>의 대표 프리셋은 Trap과 House 사이에서 <strong>0.9938</strong>로 상관되었고, 어쿠스틱 피아노는 전체 로스터에 걸쳐 <strong>0.974–0.997</strong>이었습니다. <code>apply_genre</code>의 모델링 분기는 <code>filter.cutoff</code>, <code>filter.drive</code>, FX 체인에만 닿을 수 있었습니다 — 물리 모델이 거의 쓰지 않는 필터와 그 <em>뒤에</em> 있는 체인 — 그래서 그것이 하는 어떤 일도 악기를 치고, 켜고, 부는 방식을 바꾸지 못했습니다.","changelog.43cbc2d5c9d0":"<code>colour_modelled</code>는 장르를 각 엔진 <strong>자신의</strong> 매개변수에 대응시킵니다. 808은 디케이와 글라이드입니다: 트랩 808은 한 마디 이상 울리며 노트로 미끄러져 들어가고, 하우스 킥은 짧고 그러지 않으며, 프로필은 이미 이를 <code>weight</code>로 담고 있었습니다 — Trap <strong>0.88</strong> 대 House <strong>0.60</strong>. 피아노는 해머 경도이고, 보이싱 문헌이 말하는 것도 바로 그것입니다: Jazz는 <code>drive</code> 0.10, Metal은 0.70. 더 밝은 장르는 Hammond의 위쪽 드로바를 끌어올리고, 더 거친 장르는 브리지에 더 가까운 곳에서 현을 뜯습니다.","changelog.5e368038fb52":"⚠ 각 밀어붙임은 프로필의 차원 하나가 아니라 여럿으로 만들어집니다: 차원 하나를 ±0.30 움직이는 것은 청취자나 지문이 구별할 수 있는 수준보다 작습니다.","changelog.151c57cb8bd1":"추가 — 장르 축의 관문, 그리고 그것이 금지하지 않고 세는 이유","changelog.0976e9520f58":"<code>an_instrument_sounds_different_in_every_genre</code>는 모든 악기의 대표 프리셋을 69개 장르 전부에서 렌더링하고 — 렌더링 15,525회 — 각 악기가 적어도 <strong>62</strong>개 장르에서 구별되는 소리를 내도록 요구합니다.","changelog.171a63bd1519":"⛔ <strong>쌍마다의 금지가 아니라 개수.</strong> 2,346개 장르 쌍이 모두 다르도록 요구하면 <code>Jungle == Breakbeat</code>와 <code>Cinematic == Downtempo</code>에서 실패했습니다. 실제로 성격을 공유하는 장르들입니다 — 그리고 테스트를 초록으로 만들려고 그 사이에 차이를 만들어 넣는 것은 되돌려진 396개 아티스트 모델 뒤에 있던 바로 그 실수입니다. 요청받은 것은 악기가 69개의 레이블을 단 <strong>하나의</strong> 소리가 아니어야 한다는 것이었고, 구별되는 개수에 하한을 두면 아무것도 지어내지 않고 그것을 말할 수 있습니다.","changelog.a04ef14ec8d1":"수정 — 미리 듣기를 매번 처음부터 렌더링하던 문제, 2026-08-31","changelog.642ec6d63dec":"⛔ <strong>이 라이브러리는 미리 구워 둘 수 없고, 숫자가 그 이유입니다.</strong> 악기 225개 × 장르 69개 × 변주 24개는 프리셋 <strong>372,600</strong>개입니다. 22 kHz 모노 4초씩이면 <strong>61 GB</strong>이고, 플레이어가 읽는 48 kHz float로는 266 GB입니다. 그래서 클립은 한 번 렌더링된 뒤 미리 구운 것처럼 동작합니다: 렌더링은 <strong>평균 23.79 ms, 최악 42.5 ms</strong>, 보관된 사본을 돌려주는 데는 약 0.1 ms. 클립 서른두 개, 약 24 MB — 목록을 화살표로 오르내리면 같은 몇 줄을 다시 찾게 되므로, 작은 캐시로 거의 모든 반복을 잡습니다.","changelog.10eb1736b8c9":"추가 — ↑/↓로 라이브러리를 훑으며 닿는 것을 재생합니다, 2026-08-31","changelog.43b3eb09cc47":"파일 트리에 8월부터 있던 것과 같은 동작인데, 라이브러리는 패널에서 모든 행을 클릭해야 하는 유일한 목록이었습니다. ⚠ 창이 아니라 목록 상자에 묶여 있으므로, 피아노 롤이 같은 키로 노트를 미세 이동할 때는 절대 발동하지 않습니다.","changelog.6a4614d116ae":"수정 — 프리셋 라이브러리의 절반이 같은 소리의 반복이던 문제, 2026-08-31","changelog.0f63f6bd0158":"⛔⛔ **<code>modelled_defaults</code>는 <code>let _ = rng;</code> 위에서 <em>“프리셋마다 약간의 휴머나이즈”</em>를 약속했습니다** — 아무도 작성하지 않은 동작을 묘사하는 주석이었습니다. 그것이 호출한 다시 굴리기는 <em>웨이브테이블</em>만 변화시킬 줄 알았고, 물리 모델은 웨이브테이블을 전혀 읽지 않습니다. 측정해 보니 <code>Sub808</code>의 변주 0–5는 <strong>바이트 단위로 동일, 상관 1.0000</strong>이었고, 패치의 웨이브테이블만 충실히 바뀌었습니다. 라이브러리의 약 절반이 모델링된 것이므로, 조합마다 24개 변주 중 절반이 한 소리를 스물네 번 반복한 것이었습니다. <code>randomize_modelled</code>는 각 엔진 <strong>자신의</strong> 매개변수를, 새로 굴리는 대신 종류의 기본값 주위로 흔들어 움직입니다. 변주는 다른 악기가 아니라 같은 악기에 대한 다른 <em>테이크</em>이기 때문입니다.","changelog.aafb4b3e7173":"⛔ <strong>서브는 사인파이고, 그것을 바꿔치는 것은 변주가 아닙니다.</strong> 팩 다시 굴리기는 서브를 톱니파로 바꾸고 디튠된 보이스 아홉 개를 쌓았습니다. 32 Hz에서 그것은 모서리, 맥놀이, 에일리어싱입니다 — 보고된 잡음 그대로.","changelog.99d2732af475":"⛔ <strong>Slap Bass와 Pluck Bass가 한 갈래를 공유해</strong> 이름 둘을 단 같은 패치였습니다. 이제 둘 다 일렉트릭 베이스 현이며, 연주자가 구분하는 지점에서 갈라집니다.","changelog.c9eec0781f88":"추가 — 한 장르의 프리셋 5,400개를 모두 듣는 관문, 2026-08-31","changelog.d954c7fae943":"<code>no_two_presets_in_a_genre_render_the_same_sound</code>는 House에서 모든 악기 × 변주 — 225 × 24 — 를 렌더링하고, 각각을 길이, 레벨, 어택 기울기, 여덟 개의 배음 비율로 지문을 찍어, 어떤 둘도 충돌하지 않음을 단언합니다. 24초.","changelog.f1e878d4342a":"⛔ <strong>패치를 읽는 것이 아니라 들어야 합니다</strong>: 808 Sub의 변주들은 서류상으로는 달랐으므로, <code>Patch</code>에서 뽑은 지문이었다면 스물네 개 모두 통과했을 것입니다. 관문은 그 버그를 <em>상대로</em> 검증되었습니다 — <code>randomize_modelled</code>를 끄면 즉시 실패하고 충돌하는 쌍들의 이름을 댑니다.","changelog.e32c895d315b":"수정 — 미리 듣기가 생성기가 연주하는 것을 약속하지 않던 문제, 2026-08-31","changelog.d0db0dc79e31":"<strong>패치</strong>는 결코 문제가 아니었습니다: 미리 듣기와 생성기는 같은 프리셋을 만듭니다. 갈라진 것은 그 위에 쌓인 모든 것이었습니다 — <code>PartSound</code>는 리버브, 딜레이, 드라이브, 피치 변조, 게인, 팬, ADSR을 담고 있는데, 생성기는 일곱 가지를 모두 적용하고 미리 듣기는 하나도 적용하지 않았으므로, 이전 악기의 리버브를 여전히 걸친 파트가 새 악기를 그 리버브를 통해 연주했습니다. 이제 악기를 고르면 다듬기가 초기화되며, <code>Use in …</code> 버튼과 <code>Ctrl</code>+→가 함께 지나는 단 하나의 입구를 통합니다.","changelog.25007f86466f":"⚠ 브라우저에서 그 위의 규칙과는 의도적으로 다릅니다. 그 규칙은 파트에 저장된 소리를 먼저 읽으므로, 파트를 그저 <em>건드리는</em> 것만으로 편집이 지워지지 않습니다. 새 악기를 고르는 것은 다른 행위입니다.","changelog.89099f78768b":"변경 — 라이브러리가 Trap에서 열리고, 장르가 알파벳순으로 정렬됩니다, 2026-08-31","changelog.49d670380403":"⚠ <code>genre</code>는 스토어의 기본값이 쓰일 때는 아직 존재하지 않는 목록의 인덱스이므로, <code>0</code>은 결코 어떤 장르를 뜻한 적이 없습니다 — 분류 체계가 맨 처음에 나열한 것이 무엇이든 그것을 뜻했습니다. 분류 체계가 도착하면 Trap으로 옮겨 가며, 손대지 않은 <code>0</code>에서만 그렇습니다. 정렬은 그려지는 것에만 적용되고 저장되는 것에는 절대 적용되지 않습니다: 라이브러리는 분류 체계 인덱스로 자르므로, 목록 자체를 정렬하면 모든 주소가 조용히 다른 곳을 가리키게 됩니다.","changelog.28cf77745a93":"⚠ 목은 <code>Genre 1 … Genre 69</code>로 응답했습니다 — 이미 알파벳순이고 Trap도 없으니, 두 규칙 어느 것도 테스트할 수 없었습니다. 이제 실제 이름으로 응답합니다.","changelog.07bc5a7db520":"수정 — 모든 악기가 1초도 안 되는 똑같은 짧은 소리로 미리 들리던 문제, 2026-08-31","changelog.3de906154cb6":"증상은 실제였지만 합성의 문제는 아니었습니다: 실제 렌더링 경로로 측정하면 어쿠스틱 피아노의 스펙트럼 중심은 1.32, 클라비넷은 2.87이고, 라우팅도 올바릅니다.","changelog.b68a797d6d3c":"⛔⛔ <strong>그들이 공유한 것은 모양이었습니다.</strong> 미리 듣기는 <strong>샘플러용 원샷</strong>의 크기를 정하는 렌더러를 빌려 썼습니다 — 0.6초 게이트와 1.4초 꼬리. 0.5초는 마림바를 듣기에는 충분하지만, 어택 뒤에 일어나는 일이 <em>곧</em> 성격인 계열 — 오르간, 바이올린, 패드 — 을 듣기에는 턱없이 짧습니다. 그래서 225개 모두가 같은 음높이와 거의 같은 피크의 1초 미만 짧은 소리로 돌아왔습니다.","changelog.c87553afd32f":"이제 미리 듣기는 자신의 노트를 1.5초 + 2.5초 붙잡습니다: 모두 0.6–1.0초이던 길이가 클라비넷은 0.64초, 오르간은 1.84–1.91초가 됩니다. ⚠ 타격 악기는 무음 하한에서 잘리므로 아무 비용도 치르지 않습니다.","changelog.6fffbb4dd6a9":"수정 — 미리 듣기 플레이어가 악기 재생을 한 번도 보여 주지 않던 문제, 2026-08-31","changelog.06945748a71f":"재생 헤드 폴링은 <code>selected === null</code>을 물었습니다 — 그런데 <code>selected</code>는 <strong>파일</strong>을 가리키고, 악기를 미리 들으면 MIDI 패널이 더는 들을 수 없는 <code>.mid</code>를 묘사하지 않도록 일부러 그 값을 비웁니다. 그래서 미리 듣는 악기는 클립 내내 “재생 중인 것 없음”으로 읽혔습니다: 재생 헤드도, 경과 시간도, 탐색도 없이. 이제는 <strong>파형</strong>이 로드되었는지를 묻고, 이는 두 경로 모두에서 참입니다.","changelog.bfe82ac019ab":"수정 — 독립 실행 버전의 모든 생성이 120 BPM으로 나오던 문제, 2026-08-31","changelog.e1391ea65a06":"⛔ <strong>nih-plug의 독립 실행 버전은 템포를 보고하는데, 그것은 <code>--tempo</code>의 기본값 120입니다.</strong> 파일 자체의 헤더는 동기화할 <em>대상</em>이 없다고 말하는데도, 트랜스포트는 매 블록 120이라고 말했습니다 — 그래서 고정값 없는 자동 동기화가 로스터의 모든 아티스트를 이기는 120 덮어쓰기가 되었습니다: suicideboys는 125–160으로 쓰는데 120으로 생성되었고, Drake는 130–150인데 120으로 생성되었습니다.","changelog.5d84da78d405":"한 줄로 고쳐집니다: 호스트 템포는 기본적으로 우선합니다. DAW의 템포는 절대 의심받아서는 안 되기 때문입니다. 그리고 독립 실행 버전에서는 지워집니다 — <code>--tempo</code>로 <strong>사용자가 직접 템포를 지정하지 않는 한</strong>. 그 경우에는 정확히 요청한 그대로입니다.","changelog.d7a7889636c7":"변경 — 스타일 인스펙터가 왼쪽 레일을 떠났습니다, 2026-08-31","changelog.df3b5905432c":"왼쪽 아래 패널은 이제 스타일의 이름, 장르, 스케일, 템포만 보여 주고 다른 것은 없습니다 — <code>ArtistPane</code>이 이미 그리던 것입니다. 그 아래의 매개변수 덤프는 사라졌습니다. 그 레이블을 두 번이나 다듬었지만 불만에 대한 답이 되지 못했습니다. 매개변수 자체가 원하는 것이 아니었기 때문입니다.","changelog.95bc4d0e3982":"⚠ <code>StyleInspector</code>는 마운트되지 않은 채 남아 있어 한 줄이면 되살릴 수 있습니다 — 그리고 그와 함께 매개변수별 덮어쓰기와 그 자체의 “내 스타일로 저장”도 사라집니다. 스타일 편집기 대화상자에서는 여전히 나만의 스타일을 저장할 수 있습니다.","changelog.d0654c4b85c2":"수정 — 악기를 클릭해 들으면 패치까지 만들던 문제, 2026-08-31","changelog.4d2ba450de39":"라이브러리 행은 <code>select</code>를 호출했는데, 이는 Rust에서 패치를 만들고 <strong>또한</strong> 신스 페이지를 다시 불러옵니다 — 행마다 왕복 두 번, 그저 목록을 훑으며 듣고 있던 사람이 치르는 비용. 미리 듣기에는 둘 다 필요 없었습니다. 이제 행은 미리 듣고 강조 표시만 하므로, 악기가 생성기에 닿는 것은 정확히 한 가지 동작으로입니다: <code>Use in …</code> 버튼 또는 <code>Ctrl</code>+→.","changelog.bc2c85aa41fb":"⛔ 그리고 그 버튼은 이제 행들이 말하는 곳에 놓입니다. 버튼은 <code>activeTab</code>을 읽고 행들은 <code>targetPart</code>를 읽었는데, SYNTH 페이지에서는 둘이 다릅니다 — 그래서 버튼은 한 생성기를, 그 옆 목록은 다른 생성기를 가리켰습니다. 이제 버튼은 패치도 <strong>불러옵니다</strong>. 그렇지 않으면 다시 생성할 때까지 이전 악기를 들었습니다.","changelog.8d96a9b23a8a":"수정 — 생성이 아티스트가 결코 쓰지 않는 스케일을 쓸 수 있던 문제, 2026-08-30","changelog.0aa78e305fb2":"엔진은 이미 고정되지 않은 스케일을 모델 자신의 목록에서 뽑으므로, 구멍은 <strong>고정값</strong>에 있었습니다: 고정값은 설계상 아티스트를 바꿔도 살아남는데, 새 아티스트가 그 스케일로 쓰는지 묻는 것이 없었습니다. 트랩에서 마이너 펜타토닉을 고르고 UK Drill로 옮기면 드릴이 쓰지 않는 모드로 드릴을 생성했습니다 — 그리고 칩이 이를 쉽게 만들었습니다. 엔진이 아는 <strong>41</strong>개 모드를 모두 제공했는데, 트랩이 쓰는 것은 그중 넷입니다. 이제 칩은 아티스트 자신의 스케일만 제공하며, 아티스트를 바꾸면 새 아티스트가 쓰지 않는 고정값은 <strong>버려집니다</strong>.","changelog.8f482a9b2c0b":"⚠ 옆의 템포는 범위 안으로 당겨지지만, 이것은 대체되지 않고 버려집니다: 범위에는 가장 가까운 허용값이 있지만 집합에는 없습니다. 프리지안에 “가장 가까운” 모드란 없으며, 하나를 지어내는 것은 앱이 아티스트의 소리를 고르는 일이 됩니다. 키 칩은 그대로입니다 — 키는 조옮김이지만, 모드는 성격 그 자체입니다.","changelog.2f2d6d4a01f2":"변경 — “작성하지 않는 파트”가 아티스트 창에 돌아왔습니다, 2026-08-30","changelog.7983a70d1982":"이것은 침묵을 막는 쪽 절반입니다: 베이스, 코드, 멜로디, 카운터 생성기는 모델이 블록을 작성하지 않았으면 각각 <em>빈</em> 트랙을 돌려주므로, 베이스라인을 쓰지 않는 아티스트는 그 탭의 생성에 아무것도 없이 답합니다.","changelog.4e9d74d07396":"⚠ 부정의 절반만입니다. “작성하는 파트 …”는 탭에서 짐작할 수 있는 목록이지만, “작성하지 않는 파트 …”는 다음에 할 일을 바꾸는 것이며, 무언가 빠져 있을 때만 그려집니다.","changelog.3ebd75dbc890":"수정 — 시드가 STYLE 패널 위에 겹쳐 있던 문제, 2026-08-30","changelog.60812270f2e2":"<code>.stage__controls</code>는 고유 너비가 740px인데 <code>nowrap</code>이었고 모든 자식에 <code>flex-shrink: 0</code>이 걸려 있었습니다 — 각각 560px까지 끌 수 있는 두 레일 사이의 <code>1fr</code> 트랙 안에서 움직이지 않는 물체였습니다. 열 방향 flex 컨테이너에서 너무 큰 항목은 <em>시작</em> 쪽으로 넘치므로, 레일을 가로질러 왼쪽으로 그려졌습니다.","changelog.3d60f1aa0052":"⛔ <code>SeedChip.css</code>는 이미 이 문제의 절반을 풀었는데 무시당하고 있었습니다: 시드 입력은 바로 글자 폭을 돌려줄 수 있도록 <code>min-width: 0</code>과 함께 <code>flex: 1 1 20ch</code>인데, 한 단계 위의 일괄 <code>flex-shrink: 0</code> 때문에 한 번도 요청받지 못했습니다. 이제 시드는 <strong>10ch를 요청하고 늘어납니다</strong>. flexbox는 줄어들기 전에 기준 크기로 줄바꿈을 정하기 때문입니다. 행은 최후의 수단으로 줄바꿈하며, 예전에는 결코 그러지 않았습니다.","changelog.d69262d1a787":"변경 — 아티스트 창이 세 가지를 말합니다, 2026-08-30","changelog.843ac4d32d6d":"장르, 스케일, 템포 범위 — 그리고 첫 번째 스케일만 보여 주던 자리에 <strong>모든</strong> 스케일. 내추럴 마이너로만 쓰는 아티스트와 마이너, 도리안, 마이너 펜타토닉을 오가는 아티스트는 함께 작업하기에 다르며, 항목 하나로는 둘을 구분할 수 없습니다.","changelog.150a5f8a6f30":"⛔ 빠진 것들, 실수로 되살아나지 않도록 이름을 적어 둡니다: 시대, 첫 번째 키, 하프타임 표기, 무드, 그리고 작성하는 파트 / 작성하지 않는 파트. 이로써 이 창이 품고 있던 모순도 정리됩니다 — 808이 <em>곧</em> 베이스라인인 360개 모델에 대해 베이스를 내세웠지만, 베이스 탭은 그 모델들을 거부했습니다.","changelog.db7b20c296bf":"수정 — Drake가 73 BPM으로 생성되던 문제, 2026-08-30","changelog.e6fd0aee8b1e":"Drake는 130–150으로 씁니다. 템포 고정값은 설계상 아티스트를 바꿔도 살아남는데, Ableton의 20–999 범위로만 묶여 있었으므로, 다른 아티스트에서 넘어온 73은 73 그대로였습니다. 이제 그 한계는 당신이 보고 있는 컨트롤 안에 있고, 아티스트를 바꾸면 넘어온 고정값이 새 아티스트의 범위 안으로 당겨집니다 — 지워지지 않고 당겨집니다. 한 아티스트의 빠른 쪽 끝을 요청한 사람은 다음 아티스트의 빠른 쪽 끝을 원하기 때문입니다.","changelog.5d6b18a3616d":"⛔ 먼저 두 계층 더 깊은 곳에서 시도했고, 테스트가 둘 다 거부했습니다. 스토어 setter에서는: 템포 상자는 <em>키를 누를 때마다</em> 고정값을 설정하고 포커스를 잃을 때만 범위를 맞춥니다 — 그렇지 않으면 “50”으로 가는 길에 “5”를 입력하는 순간 커서 아래에서 고쳐질 것입니다. 엔진에서는: <code>reroll_section</code>이 <strong>기록의</strong> 템포를 같은 함수에 통과시키므로, 범위 맞추기가 155의 곡을 한 구간씩 145로 끌어내렸습니다.","changelog.7831fdaa78c2":"수정 — 몇몇이 아니라 모든 모델에 맞는 악기, 2026-08-30","changelog.6d061d82240b":"모델 2,224개 중 무엇인지 질문을 받은 것은 멜로디뿐이었습니다. 나머지 세 파트는 모델에 대해 아무것도 읽지 않은 장르별 후보 목록에서 나왔습니다. 이제 각 파트가 자신의 블록에서 답합니다:","changelog.32d6056dcb8e":"<strong>카운터멜로디.</strong> <code>styles</code>는 <strong>1,876</strong>개 모델에 작성되어 있었지만 오늘까지 소리에 대해 아무 말도 하지 않았습니다. ⛔ 옥타브 에코에는 멜로디 자신의 악기로 답합니다. 옥타브 에코란 <em>바로</em> 그것이기 때문입니다.","changelog.4d54431ef084":"<strong>코드.</strong> 696개 모델이 도미넌트 세븐스 중심인데, 이는 톱니파 패드가 아니라 건반입니다. <code>vamp</code>는 누군가 컴핑하는 것이므로 패드일 수 없습니다.","changelog.23468091c213":"<strong>베이스.</strong> ⛔ 808이 곧 베이스라인인 <strong>360</strong>개 모델에는 <strong>베이스 악기가 아예 없습니다</strong>. 엔진이 바로 그 모델들에 대해 그 파트를 거부하기 때문입니다. $uicideboy$에서 Pluck Bass로 발견되었습니다.","changelog.c1557e2ef5e3":"⚠ 카운터는 멜로디의 선반을 공유했기 때문에 자신만의 선반을 얻었습니다. 리드 목록 어디에도 패드, 현악 섹션, 합창이 하나도 없었으므로 — <em>“내 카운터는 지속음”</em>이라고 말하는 655개 모델이 Saw Lead로 답을 받았습니다.","changelog.3eb279716ce7":"수정 — 120 BPM과 73 BPM이 똑같이 들리던 문제, 2026-08-30","changelog.20ba9ed93269":"<code>Schedule::arm</code>은 테이크가 <strong>생성된</strong> 템포로 모든 노트를 배치하는데, 숫자가 바뀌어도 다시 준비하는 것이 없었습니다: 칩은 움직였고 다음 생성은 그것을 썼지만, 이미 로드된 것은 예전 템포로 계속 재생되었습니다.","changelog.be97e25d3228":"⛔ 템포는 생성 설정이 아니라 시계입니다. 노트는 움직이지 않고 시계가 움직입니다. DAW에서 템포를 끌 때 DAW가 하는 일이 바로 그것입니다. 같은 재준비가 반대 방향에도 답합니다 — 자동 동기화가 켜져 있을 때 프로젝트 템포를 끌면, 예전에는 플러그인이 만들어진 템포 그대로 계속 재생했습니다.","changelog.3b643d7c2f3d":"수정 — 표시 셋과 제목 표시줄 하나, 2026-08-30","changelog.97cc14c61e0e":"<strong>스타일 인스펙터는 스타일시트를 씌운 JSON 파일이었습니다.</strong> <code>$schema</code>를 빼고 나니 각각 <code>arrangement.</code>로 시작하는 행 서른 개가 남았고, 모든 경로의 쓸모 있는 절반은 끝에 있어 좁은 레일 밖으로 옆으로 스크롤되었습니다. 이제 블록은 제목이 되고 행은 단어로 읽힙니다 — <code>Section bars › Hook</code>. ⚠ <strong>값</strong>은 그대로입니다: <code>[4,8]</code>을 “4 또는 8”로 다듬으면 편집 가능한 필드가 자신이 받는 것에 대해 거짓말을 하게 됩니다.","changelog.0affc50612cd":"<strong>상태 줄이 그 소리가 누구의 것인지 말해 줍니다</strong> — <em>“기본 악기: Tambourine”</em>, <em>“내 원샷: 808long.wav”</em> — 무엇을 출시할 수 있는지 판단하는 사람에게 필요한 것입니다.","changelog.469d7247448c":"<strong>미리 듣기 플레이어</strong>가 탐색기 아래쪽에 고정됩니다: 레일이 스크롤되므로, 즐겨찾기가 있는 라이브러리는 트랜스포트를 화면 밖으로 밀어내, 플러그인이 계속 재생하는 동안 화면에 정지 버튼이 없었습니다.","changelog.83ea9df0754e":"<strong>제목 표시줄에 기본 Windows 아이콘이 있었습니다</strong>. 제목 표시줄은 창 클래스에서 아이콘을 가져오는데, <code>baseview</code>는 아이콘 없이 클래스를 등록하기 때문입니다. ⛔ 독립 실행 버전에만 해당합니다 — DAW에서는 그 창이 호스트의 것입니다.","changelog.8db43618eb5d":"수정 — 아티스트가 실제로 불러오는 악기, 2026-08-30","changelog.124d7acd17d3":"⛔⛔ <strong>Drake의 멜로디는 Hand Bell이었고 카운터멜로디는 Recorder였습니다.</strong> 결함 셋, 측정한 것:","changelog.d4d7ff8f906c":"<strong><code>melody.timbreHint</code>를 읽는 곳이 없었습니다.</strong> <strong>252가지 서로 다른 값으로 1,966번</strong> 작성되어 있는데 <code>grep</code>은 테스트에서만 그것을 찾았으므로, 모든 모델의 소리가 음높이 있는 파트를 맡는 악기 77개 전체에서 뽑혔습니다. 이제 읽힙니다: 명사는 악기가 되고 수식어는 음색이 됩니다.","changelog.cb4b176767c3":"<strong>대체 뽑기는 어떤 장르를 위한 것인지 전혀 몰랐습니다.</strong> ⚠ 첫 수정은 <em>계열</em>로 걸렀는데 여전히 틀렸습니다 — 건반 계열에 반도네온이 들어 있어서, Drake의 코드가 <strong>Bandoneon</strong>으로 나왔습니다.","changelog.9ec8b19d2a99":"<strong>변주는 0..23에서 뽑혔습니다</strong>. 코드는 줄곧 변주 0이 대표 프리셋이라고 말해 왔는데도 그랬으므로, 아티스트의 기본값이 받은 악기가 무엇이든 그 악기의 이상치였습니다.","changelog.83d8f379ed55":"▶ 수정 후 측정: Drake의 멜로디는 부드러운 Electric Piano, Future는 밝은 Bell, Adele은 따뜻한 Grand Piano. 엔진은 결코 문제가 아니었습니다 — 225개 악기 중 179개가 이미 물리 모델로 연결됩니다.","changelog.d24230b7e18c":"추가 — 그날 밤의 지시 사항, 2026-08-30","changelog.94468f71b792":"<strong>기본 악기를 위한 원샷 미리 듣기.</strong> 브라우저는 디스크의 모든 <code>.wav</code>를 미리 들을 수 있었지만 악기 225개 중 하나도 들을 수 없었습니다. ▶ 세 조각이 이미 트리에 있었는데 한 번도 이어진 적이 없었습니다.","changelog.d9630357c37d":"<strong>악기별 미리 듣기 음.</strong> 표는 베이스를 빼고 모든 것에 C4로 답했으므로, 튜바와 피콜로가 같은 음으로 미리 들렸습니다.","changelog.a0f4946b92e6":"<strong>푸터의 상태 표시줄.</strong> 그 구석의 <code>1.1.00</code>은 트랜스포트 위치였는데 버전 번호로 읽혔습니다. ▶ 표시줄을 채우는 라이브 영역은 이미 이 문장들을 쓰고 있었는데, 누구에게도 보여 준 적이 없었습니다.","changelog.24e91666084b":"<strong>이제 메트로놈이 박자 위에 떨어집니다</strong>: 클릭은 박자를 담은 블록의 시작에서 발동되었는데, 독립 실행 버전의 2048프레임 주기에서는 그 차이가 <strong>43 ms</strong>입니다.","changelog.40c605708dea":"<strong>킷 레인을 라우팅 대상으로 고를 수 있고</strong>, <code>Ctrl</code>+→가 선택한 악기를 그리로 보냅니다. 거꾸로 생성기에 들어가는 것은 없습니다.","changelog.8a97e46ad351":"수정 — 거짓말을 하던 표시 셋, 2026-08-30","changelog.13efc12c8cad":"<strong>스타일 인스펙터가 <code>$schema</code>와 연구 블록을 나열했습니다.</strong> 이제 파일의 관리용 항목과 연구 출처는 건너뜁니다. <code>era</code>와 <code>genres</code>는 남습니다. 악기 선택기가 그것을 읽기 때문입니다.","changelog.31e9eda443e8":"<strong>엔벨로프 편집기가 끝 핸들을 반만 그렸습니다.</strong> 핸들은 자신의 값 위치에 놓이므로, 0 dB의 서스테인은 위쪽 가장자리에, 최대의 릴리스는 오른쪽 가장자리에 있고, 원의 5단위가 viewBox 밖으로 나갔습니다. 이제 상자에 여백이 있습니다.","changelog.5ba045b1b88b":"<strong>킷 패널은 아티스트가 무엇을 불러왔든 “기본 제공”이라고 말했습니다</strong>. 프리셋 로더가 이미 답한 이름을 버린 것입니다.","changelog.3f52a91cd88b":"추가 — v1.0.0 필수 항목, 2026-08-29","changelog.fd9a52e845e2":"<strong>매개변수별 잠금.</strong> <em>리듬</em>을 잠그고 음높이를 다시 굴리거나, 그 반대로. ⛔ 입구마다가 아니라 <code>withLocks</code> 안에서 조합되므로, 생성과 전체 생성이 구조적으로 이를 얻습니다 — 한 입구에만 설치되고 다른 입구에는 없는 규칙은 이 저장소가 일곱 번이나 기록해 둔 실패입니다.","changelog.17455804e395":"<strong>내용 기반 원샷 역할.</strong> 파일 이름이 아무것도 말해 주지 않으면, 샘플을 읽을 수 있는 DSP 특징 여섯 개로 분류하고 창에 그 이유를 인쇄합니다: <em>“808 · 1.9 s · 62 Hz · 노이즈 4%”</em>. ⛔ 분류기가 아니라 임곗값이며, 이름이 언제나 이깁니다.","changelog.3ba97e819e31":"<strong>스타일 인스펙터</strong>, 모든 값에 그것을 제공한 모델이 표시됩니다. ⛔ 덮어쓰기는 모드 다음, 린트 전에 적용되므로, 모드가 방금 고정한 값을 조용히 앞지를 수 없습니다.","changelog.b3fc14e1aaf9":"<strong>출처 영수증.</strong> 기본값은 꺼짐이고, 로컬에 기록되며, 어디로도 보내지지 않습니다.","changelog.e9eeec6e1529":"<strong>누락 파일 진단.</strong> ⛔ 검증됨과 이름으로 일치함은 서로 다른 주장이며 다르게 그려집니다. 파일이 사라지기 <em>전에</em> 기록된 해시만이 후보를 증명할 수 있기 때문입니다.","changelog.4c2e5321dca4":"<strong>노트를 연주해 넣기.</strong> ⛔ 온셋은 스냅되고 길이는 스냅되지 않습니다 — 연주한 노트를 그리드에 맞춰 늘리는 것이야말로 퀀타이즈된 입력을 기계처럼 들리게 만드는 것입니다.","changelog.8c0513f107b0":"<strong>스타일 공동 작성.</strong> ⛔ 사본이 아니라 원래 모델에 대한 차이(diff)입니다: 사본은 오늘의 기본값을 얼려 넣고, 이후 부모의 모든 개선이 조용히 닿지 않게 됩니다.","changelog.beb404bfb850":"이미 만들어져 있음을 확인함","changelog.9c1a0003d15a":"FMM-S01(플러그인 내 샘플러), FMM-S02(MIDI 전용 바이패스, 그리고 MIDI는 계속 흐르는 상태의 레인별 오디오 음소거), FMM-S03(MIDI와 렌더링된 오디오의 네이티브 드래그아웃)은 모두 이전 작업 번호로 이미 출시되었습니다.","changelog.18fb79233d8e":"추가 — 녹음 버튼, 메트로놈, 그리고 건반 하나로 코드 연주, 2026-08-26","changelog.55c7530e6073":"<strong>연주한 것을 파트의 클립에 녹음합니다</strong>. 화면 건반, MIDI 건반, 또는 컴퓨터 키에서. ⛔ 루프를 넘어 붙잡은 노트는 마디선에서 잘리지 않은 하나의 노트이고, <strong>두 번째 패스는 오버더빙합니다</strong>. 둘 다 하나의 결정에서 나옵니다: 시간은 녹음이 시작된 순간부터 세고, 노트를 기록할 때에야 위치로 바뀝니다.","changelog.29e9a0b6f948":"⛔ <strong>테이크를 비우는 것은 버리기뿐입니다.</strong> 자신의 테이크를 먹어 치우는 한 패스 녹음기는 모든 프로듀서가 다른 도구에서 겪어 본 실패이고, 처음 30초 안에 시험해 볼 것입니다.","changelog.2339bbf1e7ae":"<strong>그 옆에 메트로놈.</strong> ⛔ 모니터링 보조이며, 렌더링된 믹스, 드래그아웃, 팩 내보내기에는 결코 들어갈 수 없습니다.","changelog.6136b9c1d42c":"<strong>건반 하나로 코드를 연주합니다.</strong> ⛔ 코드 빌더는 오디오 스레드에 하나뿐입니다. 페이지는 루트만 보내고 코드는 절대 보내지 않습니다. 스케일의 반음들을 TypeScript로 복사하면, 이 구조가 막으려고 존재하는 두 번째 빌더가 생기기 때문입니다.","changelog.fd3543d53681":"<strong>롤과 건반에 코드 레이블.</strong> ⛔ 키는 노트가 아니라 언제나 세션에서 옵니다: C–E♭–G는 C 마이너에서는 <code>i</code>이고 E♭ 메이저에서는 <code>vi</code>이며, 둘 사이에서 깜빡이는 레이블은 없느니만 못합니다.","changelog.0c3159dec9e4":"보안 — 존재하지 말았어야 할, 룸으로 들어가는 세 가지 길, 2026-08-27","changelog.f18e6a3e8b22":"⚠ 아직 출시된 빌드에서는 어느 것에도 닿을 수 없지만, 각각 다른 부분은 완성된 코드에 난 실제 구멍이었고, 각각 그것을 재현하는 테스트와 함께 고쳐졌습니다.","changelog.866ebdbc95a0":"⛔⛔ <strong>붙여 넣은 초대 응답이 방장의 신원을 주장할 수 있었습니다.</strong> 응답의 피어 id는 그것을 만든 사람이 쓰는데, 룸과 방장이 한 번의 시계 읽기로 만들어졌기 때문에 쉽게 추측할 수 있었습니다 — <code>room-&lt;t&gt;</code>가 <code>me-&lt;t&gt;</code>를 드러냈습니다.","changelog.839fdc680905":"⛔⛔ <strong>손님이 다른 구성원 대신 서명할 수 있었습니다.</strong> 시그널링 프레임은 자신이 다루는 피어의 이름을 적는데, 그 이름을 그대로 믿었으므로, 손님이 피해자의 연결 표에서 방장의 자리를 차지할 수 있었습니다. ⚠ 한 테스트는 예전 동작이 올바르다고 단언하고 있었습니다. 그 테스트가 구멍을 열린 채로 고정하고 있었던 것입니다.","changelog.21f5bf6627b0":"⛔⛔ <strong>늦게 들어온 참가자가 잘못된 후계자를 배울 수 있었습니다</strong>. 그가 받은 명단이 도착 순서가 아니라 자리 순서로 정렬되어 있었기 때문입니다.","changelog.2a4225044c45":"<strong>사이드카의 포트 파일은 Linux에서 <code>0600</code>입니다</strong>. 만든 뒤에 좁히는 것이 아니라 처음부터 그렇게 만들어집니다.","changelog.ae9b66d28161":"수정 — 다시 살펴본 녹음기, 2026-08-27","changelog.bf75d500547e":"모두 막 출시된 코드에 있었고, 모든 수정에는 예전 동작에서 실패하는 테스트가 있습니다.","changelog.06a1e90fa8d5":"⛔⛔ <strong>테이크가 연주한 곳이 아니라 녹음을 누른 곳에 떨어졌습니다.</strong> 시계가 트랜스포트가 아니라 버튼에서 시작했으므로, 3마디에서 녹음을 준비하고 4마디 다운비트에 연주한 코드가 클립의 한 마디 뒤에 도착했습니다.","changelog.df8e2475b858":"⛔ <strong>한 패스에서 1,024번째 노트 이후는 모두 버려졌습니다</strong>: 넘겨주기가 노트가 들어갔는지 확인하기 전에 커서를 전진시켰습니다.","changelog.a60f121ecd2e":"⛔ <strong>두 생성기에 걸쳐 연주한 테이크가 하나로 합쳐졌습니다</strong>. 각 노트를 울린 엔진이 버려지고, 그때 열려 있던 탭으로 대체되었습니다.","changelog.398bb76fb6e9":"⛔ <strong>패닉 버튼으로 끊긴 노트가 테이크 끝까지 이어졌습니다</strong>. 그래서 200 ms짜리 코드가 녹음 전체 길이의 노트로 기록되었습니다.","changelog.e8057c8ad5f1":"<strong><code>x/4</code>가 아닌 모든 박자에서 루프가 엉뚱한 지점에서 되감겼습니다.</strong>","changelog.225cbcabcd7f":"수정 — 브라우저 빌드, 그리고 거짓말을 한 픽스처, 2026-08-27","changelog.6cff7080b85d":"⛔⛔ <strong>브리지 명령 일곱 개에 픽스처가 없어서, 플러그인 밖에서는 녹음기와 코드 모드가 죽어 있었습니다</strong> — <code>vite dev</code>, 웹 빌드, 모든 엔드투엔드 실행에서 — 그런데 아무것도 빨갛게 되지 않았습니다. 호출 지점마다 오류를 삼켜 버리기 때문입니다. 롤은 자신의 그리기 안에서 코드 레이블을 요청하므로, 페이지가 살아 있는 동안 프레임마다 거부된 호출이 하나씩 생겼습니다.","changelog.dd41a2bcdfe7":"⛔ <strong>그다음에는 픽스처가 41개 스케일 중 35개를 거부했으므로</strong>, 도리안으로 고정한 사람에게는 코드 모드가 여전히 죽어 있었고, 엔진이 플랫으로 부르는 코드를 샵으로 불렀습니다. 실제와 다르게 답할 수 있는 픽스처야말로 픽스처가 절대 해서는 안 되는 단 한 가지입니다.","changelog.8dae7783d759":"<strong>파생된 랙의 패드 하나를 편집하면 나머지 일곱 개가 영구히 초기화되었습니다</strong>. 그 뒤로는 편집된 레이아웃이 영원히 이기기 때문입니다.","changelog.130d4f5e7331":"<strong>새 프로젝트는 모든 코드를 C로 표기했습니다</strong>. “키 설정 없음”이 “C 키”로 보내지고 있었기 때문입니다.","changelog.dbf257322b22":"변경 — 개인정보 페이지가 실제로 기기를 떠나는 것을 말합니다, 2026-08-27","changelog.a78636091f9d":"⛔⛔ <strong>페이지는 “STUN 서버가 구성되어 있지 않고 컴파일된 기본값도 없다”고 말했습니다. 사실이 아니었습니다.</strong> 빌드에는 두 개 — Cloudflare와 Google — 가 실려 있고, 룸을 열거나 들어갈 때 그중 하나에 연락하므로, 그 서버는 어떤 주소가 WebRTC 애플리케이션을 쓰고 있다는 것을 알 수 있습니다. 누구와 이야기하는지도, 무엇을 보내는지도 아닙니다. 이제 두 서버 모두 열여덟 개 언어 전부로 페이지에 이름이 적혀 있으며, 언제 연락하는지와 무엇을 알게 되는지도 함께 적혀 있습니다.","changelog.48cff82da9bd":"⚠ 한 테스트가 그 사실이 아닌 문장을 단언하고 있었고, 그래서 살아남았습니다. 아직 빚으로 남아 있고 이제 그렇다고 밝히는 것은, 이 서버들을 바꾸거나 끌 수 있는 설정입니다.","changelog.0b9b24ca1f7c":"추가 — 악기에 건반, 저장할 수 있는 라이브러리, 샘플 랙이 생겼습니다, 2026-08-23","changelog.bbd370386f96":"<strong>한 번에 악기 넷.</strong> 멜로디, 카운터, 베이스라인, 코드가 각각 <code>SynthEngine</code>을 가집니다. ⚠ 16보이스로 파트 넷일 때 <strong>128프레임 블록의 26%</strong>로 측정되었습니다.","changelog.8d4e8720aff1":"<strong>소리를 저장합니다</strong>. 고른 카테고리와 이름으로. ⛔ <em>사운드</em>는 악기이고, 오른쪽 레일의 <em>프리셋</em>은 저장된 세션입니다. 디렉터리가 다르며, 결코 한 목록이 아닙니다.","changelog.8945b84546af":"<strong>PACK — 25슬롯 샘플 랙</strong>. 에디터 스레드 밖에서 진행 표시와 취소 버튼과 함께 렌더링되며, 거의 무음인 렌더링은 랙에 닿기 전에 거부됩니다.","changelog.b0679c7fd0e5":"<strong>하드웨어로 연주해 넣기.</strong> ⛔ 양 끝을 넘어 조옮김된 노트는 되감기지 않고 버려집니다: 되감긴 노트는 틀린 노트이고, 화면의 어떤 것도 그렇다고 말해 주지 않을 것이기 때문입니다.","changelog.0a8a403c1283":"<strong>AIFF, 24비트, 32비트 float, 그리고 192 kHz까지의 레이트.</strong> ⛔ 끌어낸 루프는 여전히 언제나 16비트 WAV입니다. 자기 템포에 맞춰 떨어지게 하는 <code>acid</code> 청크를 담을 수 있는 것은 WAV뿐이기 때문입니다.","changelog.becd79896add":"수정 — 아무도 찾고 있지 않던 결함 넷, 2026-08-23","changelog.5aa574085b3e":"⛔⛔ <strong>다시 연 프로젝트가 재생하고 있지 않은 소리의 이름을 댔습니다.</strong> <code>part_sounds</code>는 세션과 함께 복원되므로 패널은 배정된 악기를 보여 주며 돌아왔지만 — 패치를 다시 보내는 것이 없어서, 모든 엔진이 여전히 초기 소리에 머물러 있었습니다. 팬도 오디오 스레드에 전혀 닿지 않았습니다.","changelog.e41b41f68e79":"⛔⛔ <strong>macOS에서 <code>Shift+ArrowUp</code>이 아무것도 하지 않던 것은 수정 키가 아니라 되읽기 경쟁 상태 때문이었습니다.</strong> 노브 커밋은 모두 왕복해서 값을 되읽는데, 한 커밋의 응답이 더 새로운 편집 뒤에 도착해 그것을 덮어쓸 수 있었습니다. 이제 확인은 응답이 도착할 때 이루어집니다. Shift는 그것을 눈에 띄게 했을 뿐입니다: 되돌려진 큰 단계는 분명히 틀린 곳에 떨어지고, 되돌려진 미세 단계는 허용 오차 안에 떨어집니다.","changelog.8da0d11157f2":"<strong>32비트 float WAV가 “압축됨”이라며 거부되었습니다</strong>. 사실이 아니며, 대부분의 DAW가 바운스하는 형식입니다.","changelog.eab27dba438d":"<strong>파트별 게인, 팬, 엔벨로프가 어떤 소리에도 닿지 않았습니다.</strong>","changelog.33498857d52b":"<strong><code>MAX_EXTRACT_SECONDS</code> 60 → 300</strong>. 어림짐작이 아니라 측정에 근거한 것입니다. 피크 분석 메모리는 “디코딩된 길이의 몇 배”라고 정당화되어 있었는데, 피크를 추적하는 할당기로 측정해 보니 <strong>1.2×로 일정</strong>했습니다 — 1분에 13.9 MB, 5분에 69.5 MB. ⛔ 여전히 잘라내지 않고 <strong>거부합니다</strong>: 7분짜리 파일의 처음 5분은 채보로 포장된 추측이 될 것입니다.","changelog.034ba0a65cf5":"<strong>리버브, 딜레이, 드라이브는 팩토리 악기 위에서만 그려집니다</strong>. 샘플러에는 이펙트 체인이 없어서, 당신의 샘플 위에서는 아무것도 바꾸지 않을 것이기 때문입니다.","changelog.975e6e71fd3a":"플러그인의 공유 라이브러리가 독립된 크레이트로 옮겨졌습니다. ⛔ <code>cargo test --workspace --release</code>는 몇 달 동안 링크할 수 없었습니다 — 해결되지 않은 외부 기호 413개 — <code>panic = &quot;abort&quot;</code>와 <code>[&quot;cdylib&quot;, &quot;lib&quot;]</code> 타깃 때문에 Cargo가 한 라이브러리를 두 번 빌드해 한 파일 이름에 넣었기 때문입니다.","changelog.2cecc0c1d888":"내려받는 zip에 <code>INSTALL.txt</code>가 들어 있습니다.","changelog.38fbbc3ec4b5":"수정 — 상속된 <code>secondaryAnchor</code>가 자식의 킥 예산 전체를 먹어 치우던 문제, 2026-08-22","changelog.37aab3338c62":"⛔⛔ <strong>출시된 모델 129개가 이제 다른 킥을 생성합니다.</strong> <code>drums.kick.anchors</code>는 배열이므로 자식이 직접 작성하면 부모의 것을 대체하지만 — <code>secondaryAnchor</code>는 그 옆의 별도 스칼라여서, 그 대체에서 살아남아 다시 합쳐졌습니다. <em>“내 앵커는 1과 3”</em>이라고 말하는 모델이 1, 2&amp;, 3을 받았고, 그것이 밀도 예산을 채운 곳에서는 모든 킥 타격이 보장되어 레인이 더는 변하지 않았습니다. <code>darius-rucker</code>로 측정: 자신의 베이스 모델 위에서는 <strong>시드 200개에 서로 다른 킥 모양 92개</strong>, 세컨더리가 <code>&quot;2&amp;&quot;</code>인 베이스 모델 위에서는 <strong>4</strong>개.","changelog.7b1e2aadc5b3":"<code>anchors</code>를 작성하고 <code>secondaryAnchor</code>는 작성하지 않은 자식은 더는 그것을 상속받지 않습니다. 34개 장르가 이 필드를 작성하고, 282개 모델이 세컨더리 하나가 추가되면 채워질 예산으로 자신의 앵커를 작성하므로, 이것은 결코 한 모델만의 문제가 아니었습니다.","changelog.42019e6efdae":"수정 — 정보 화면이 제품이 쓰지 않는 데이터셋을 출처로 밝히던 문제, 2026-08-22","changelog.e38cc70c3c1f":"열여덟 개 언어 모두에서 <em>“Magenta Groove MIDI Dataset에서 도출한 타이밍 및 벨로시티 통계”</em>라고 말했습니다. <strong>사실이 아닙니다</strong>: 휴머나이저는 공개된 기법 연구에서 손으로 작성한 것이고, GMD를 읽었을 도구는 한 번도 만들어진 적이 없습니다. 정보 창과 <code>docs/credits.md</code>에서 제거했습니다. 저작물을 <em>사용할</em> 때 출처 표기가 필요합니다. 쓰지 않는 저작물을 출처로 밝히는 것은 제품의 숫자가 어디서 왔는지에 대한 거짓 진술입니다.","changelog.36015e08f729":"추가 — 파일 탐색기의 태그, 그리고 마침내 제공되는 충돌 폴더","changelog.1e983e7b7fd6":"<strong>태그.</strong> 선택한 파일에 자동 완성으로 태그를 추가하고 제거하며, 태그나 별표로 트리를 거릅니다. ⛔ 폴더는 자기 이름만으로 태그 필터를 만족하지 않습니다: 태그 필터는 <em>파일</em>에 대한 진술이므로, <code>808s</code>라는 폴더가 그 안의 태그 없는 파일들을 다시 들여보내서는 안 됩니다.","changelog.3ef25c4b3313":"<strong>충돌 폴더가 숨겨지지 않고 제공됩니다.</strong> 패닉 훅과 오류 경계가 둘 다 아무도 읽지 않는 보고서를 쓰고 있었습니다.","changelog.8d8b9b03bc3f":"<strong>생성이 화면 낭독기에 알려집니다</strong>. 예전에는 인지할 수 있는 것이 아무것도 나오지 않았습니다 — 그리드는 캔버스이고 나머지는 모두 시각적이었습니다.","changelog.20ad24384bcf":"<strong>새 클립이 당신이 정한 길이로 열립니다.</strong>","changelog.6e286b860c79":"<strong>무드는 학습 뒤에 추론되지 않고 학습 전에 선언됩니다.</strong> 남겨 둔 테이크에서 무드를 되읽으면 <em>“이 작업 방식은 무엇인가”</em>가 아니라 <em>“무엇을 생성했는가”</em>에 답하게 되므로, 어두운 테이크 스무 개와 바운스 하나로 학습한 스타일이 자신을 둘 다로 기록했습니다.","changelog.273946b10440":"<strong>언더그라운드 아티스트 14명 추가</strong> — rage, opium, jerk — 로스터가 <strong>1,317개 모델</strong>이 됩니다.","changelog.50f34d3336e8":"추가 — 아무도 지켜보지 않던 구멍을 막는 관문 셋","changelog.12458ceaee7b":"<strong>어떤 별칭도 다른 모델의 고유 이름일 수 없습니다.</strong> 모델이 1,317개가 되자 주의만이 아닌 다른 무언가로 강제해야 했습니다. ⚠ 한 종류의 충돌에서만 실패합니다: 여러 모델을 가리키는 크루 태그는 한 무리의 사람들에게 닿는 정당한 방법입니다.","changelog.5b575339b3de":"<strong>우리 Rust 코드에 <code>std::net</code> 금지</strong>, <code>clippy.toml</code>로. 모든 의존성 검사는 <code>std</code>를 통해 열린 소켓을 보지 못합니다. 아무것도 링크하지 않고 <code>Cargo.lock</code>에 새로 해석되는 것도 없기 때문입니다. ⚠ 소스 텍스트 스캔을 먼저 작성했다가 버렸습니다: 아무것도 해석하지 않았으므로 <code>use std::net as n</code>이 깨끗하게 통과했습니다.","changelog.8ba8228a27d5":"<strong>보이스 가이드가 금지하는 다섯 단어.</strong> ⛔ 첫 실행에서 <em>올바른</em> 문구 — “Re-roll every unlocked pad” — 가 걸렸으므로, 규칙은 스타트업식 동사와 그 동명사이고 과거분사는 결코 아닙니다: 이 제품에는 잠금이 있습니다.","changelog.6951117e4210":"추가 — 데이터셋에 작성되어 있었지만 어떤 코드도 읽지 않던 매개변수 13개 추가, 2026-08-18","changelog.02b8b216112f":"부채 목록에서 키 열세 개가 지워졌습니다. 아무 일도 하지 않던 약 <strong>1,600개의 작성된 설정</strong>에 걸친 것입니다.","changelog.22595cc7e4a2":"<strong>스네어 아래의 림샷</strong>(231개 모델). 백비트를 옆이 아니라 박자 위에서 겹칩니다 — 스네어 아래의 림샷은 한 드럼을 두 가지 방식으로 치는 것입니다.","changelog.759a885d7eed":"<strong>808의 글라이드 시간</strong>(105개 모델). 드릴은 20–35 ms에 탁 붙고 afroswing은 130–220에 걸쳐 휘어 들어가는데, 이동이 세 곳에 하드코딩되어 있어서 그 모두가 스피커에서 “노트의 나머지”로 나왔습니다. ⚠ 노트마다가 아니라 테이크마다 한 번 뽑습니다: 노트마다 뽑으면 슬라이드마다 105개 모델의 rng 위치가 움직였을 것입니다 — <em>음색</em>에 관한 키가 그들의 <em>음높이</em>를 다시 쓰는 셈입니다.","changelog.46c9a98765f4":"<strong>고정된 백비트</strong>(5개 모델). 그래서 2와 4는 제자리에 있고 그 주위의 고스트가 숨을 쉽니다.","changelog.712e506631ab":"<strong>훅의 four-on-the-floor</strong>(29)와 <strong>크로스스틱 벌스</strong>(74). 둘 다 드럼이 한 번도 본 적 없는 구간을 지목합니다. ⛔ 크로스스틱은 백비트를 겹치는 것이 아니라 림으로 <em>옮깁니다</em>. 그것이 벌스를 코러스보다 조용하게 만드는 것입니다.","changelog.d833b34971a3":"<strong>스네어의 튜닝</strong>(7개 모델). ⛔ 목록은 이것을 808 아래에 분류했는데, 거기에 썼다면 <em>베이스라인</em>을 디튠했을 것입니다 — 음색이 아니라 틀린 음.","changelog.86a977b8200a":"수정 — 리뷰 패스가 찾아낸 것, 2026-08-18","changelog.b6906fa13a4e":"⛔⛔ <strong>플러그인에서는 음높이 변화 없이 연주되던 드럼이 내보낸 스템에서는 음높이가 움직였습니다.</strong> 노트 번호 하나가 두 독자를 상대했습니다: 호스트는 드럼의 <strong>GM 보이스</strong>가 필요하고 — 그렇지 않으면 걸어가는 킥이 랙의 서로 다른 드럼 네 개를 울립니다 — 미리 듣기 샘플러는 같은 번호를 읽어 패드를 얼마나 다시 조율할지 정합니다. GM에 고정하자, 모든 드럼이 <em>실시간 미리 듣기에서만</em> 음높이 변화 없이 연주되었고 렌더링은 올바르게 다시 조율했습니다.","changelog.f91f216318eb":"⛔⛔ <strong>크로스스틱 벌스가 808 자신의 멈춤 규칙을 침묵시켰습니다.</strong> 백비트가 림 레인에 곧바로 쓰였는데, 808은 자신이 울리며 지나가서는 안 되는 스네어 타격을 읽습니다 — 그래서 벌스에서는 그 목록이 비어 돌아왔고, 808은 드릴이 바로 그 앞에서 멈추는 것으로 정의되는 타격을 가로질러 지속되었습니다.","changelog.df60688769f5":"⛔ <strong>훅의 four-on-the-floor가 2마디부터 킥 자신의 문법을 다시 썼습니다</strong>. 추가된 펄스들이 이후 모든 마디가 읽는 같은 스트림에서 벨로시티를 뽑았기 때문입니다.","changelog.c566b1219e10":"⛔ <strong>다시 굴리기가 기록의 루프 길이를 다시 뽑았으므로</strong>, 다시 굴린 구간이 다른 클립 길이로 돌아와 모든 반복의 끝부분이 무음이 되었습니다.","changelog.6bafa094d3d1":"변경 — 부채 목록이 실제로 갚아야 할 것을 말합니다, 2026-08-18","changelog.9c4c6538b967":"항목 넷이 낡았거나 틀렸습니다: <code>timbreHint</code>는 21개 모델이라고 주장했지만 실제로는 <strong>1,234번 작성</strong>되어, 데이터셋에서 작성되었지만 읽히지 않는 가장 큰 키였습니다. <code>monoCutSelf</code>의 <code>true</code> 쪽 절반은 이미 동작하며, 읽히지 않는 것은 <code>false</code>를 작성한 네 모델입니다. <code>minimalism</code>과 <code>chordFrequency</code>는 잘못된 수준에 분류되어 있었고, 후자는 590개 전부가 상속합니다. 셋은 이제 할 일이 아니라 <strong>Mike에게 묻는 질문</strong>으로 표시됩니다. 각각 같은 모델이 작성한 키를 뒤집거나 아무 효과가 없기 때문입니다.","changelog.148f80ce9161":"추가 — 데이터셋에 작성되어 있었지만 어떤 코드도 읽지 않던 매개변수 16개, 2026-08-18","changelog.5a6d1f5a2389":"<strong>클러스터 노트가 이제 자신만의 아티큘레이션입니다.</strong> 관문 셋이 장식음을 그것이 둘러싼 박자와 구별해야 했는데 어느 것도 그러지 못했습니다: 롤로 표시하면 <em>필</em>로 셌고, 고스트로 표시하면 백비트에 <em>응답하는</em> 스네어로 셌고, 표시하지 않으면 백비트였습니다 — 그래서 한 테스트는 32분음표 폭의 장식음을 조용히 미세 이동으로 측정하기 시작했고, 엉뚱한 이유로 계속 통과했을 것입니다.","changelog.da3d109cb5d7":"<strong>스네어 클러스터</strong>(19개 모델), jerk의 대표 표지. ⛔ 박자에서 시작하는 것이 아니라 박자를 중심에 두므로, 백비트가 늦게 끌려가지 않고 둘러싸입니다.","changelog.3af1edb2e147":"<strong>레인 자신의 벨로시티 대역</strong>, <strong>킥의 서브 레이어</strong>, <strong>건너뛴 박</strong>(43개 모델), 그리고 <strong>킥을 무시하는 808</strong>(15). ⛔ 808은 킥 자신의 온셋을 거르므로, 잠금은 서브를 <em>더 성기게</em> 만들 수만 있을 뿐 결코 옮길 수 없었습니다.","changelog.ce23805b3729":"⛔ <strong>하나하나가 시드가 있는 자신만의 스트림에서 뽑습니다.</strong> 그 규칙을 어긴 것이 두 레인 떨어진 곳에서 잡혔습니다: 서브 레이어의 벨로시티가 킥의 스트림을 전진시켰고, 킥이 움직였고, 베이스라인은 킥을 따르므로, 한 모델이 하한 950에 대해 서로 다른 베이스라인 946/1000으로 떨어졌습니다 — 드럼 벨로시티 때문에 실패하는 베이스라인 관문.","changelog.3838ea6a725f":"수정 — 손으로 편집한 모델에서 닿을 수 있던 패닉 두 개, 2026-08-18","changelog.5d8e80129d6f":"<strong>사용자 모델의 비ASCII 키가 호스트 DAW를 중단시켰습니다.</strong> 린트는 가져오거나 손으로 편집한 것을 포함해 모든 모델의 모든 키를 훑으며 마지막 3바이트를 잘라 냈는데 — 그 인덱스가 멀티바이트 문자 안에 떨어지면 패닉합니다. 릴리스는 <code>panic = &quot;abort&quot;</code>로 빌드되므로, 그것은 DAW가 종료된다는 뜻이고, 파일을 찾아 지울 때까지 <strong>실행할 때마다</strong> 그렇습니다. 이제 바이트로 비교합니다. ⚠ 출시된 모델 중 비ASCII 키를 가진 것은 없으므로, CI는 결코 이를 보지 못했을 것입니다.","changelog.9ca14e5ed251":"<strong><code>f64</code>가 뺄 수 있는 것보다 넓은 변위가 <code>rand</code> 안에서 패닉했습니다.</strong> <code>[-1e308, 1e308]</code> 범위가 샘플러에 닿으면, 샘플러는 <code>high - low</code>를 계산해 <code>inf</code>를 얻고 오류를 unwrap합니다. 이제 한 한계가 오프셋 키 셋을 모두 덮습니다.","changelog.df3a55b59625":"수정 — 아무것도 담기지 않은 스타일은 더는 저장되지 않습니다, 2026-08-18","changelog.58a45134d22e":"베이스가 이미 말하지 않는 것을 하나도 말하지 않는 초안을 화면에 비트가 없는 상태로 열었다면, 기록되지 않고 이유와 함께 거부됩니다. ⛔ 스케일을 체크하는 것은 의도적으로 내용으로 치지 않습니다: 편집기가 제공하는 스케일 목록은 베이스 자신의 것으로 좁혀져 있으므로, 체크할 수 있는 모든 스케일은 베이스가 이미 쓰는 것입니다.","changelog.4dd7f6210e64":"⛔ 빈 양식이 아니라 대화상자가 열릴 때의 초안과 비교해 측정합니다 — 첫 수정은 이를 틀려서 규칙이 거의 발동하지 않았습니다. 초안은 선택한 모델의 기본값에서 스윙을 가져오는데, 1,303개 중 여섯 모델이 우연히 일치했기 때문입니다.","changelog.7da6467e020c":"변경 — 데이터셋 로드 비용 두 가지를 측정해 제거했습니다, 2026-08-18","changelog.7355c12f6bd4":"린트는 더는 모델마다 키마다 JSON 포인터를 할당하지 않습니다 — 발견이 있든 없든 전체 포인터를 만들었고, 모든 키의 소문자 사본도 만들었습니다. 그리고 <code>resolve_all</code>은 각 조상 사슬을 한 번만 병합합니다: 590개 모델 중 534개가 수십 개 장르 원형 위의 아티스트이고, 하나하나가 같은 병합을 다시 했습니다.","changelog.715106ffd3f6":"수정 — 지속되는 카운터멜로디가 더는 매번 같은 자리에서 들어오지 않습니다, 2026-08-17","changelog.7ad05d0e7f17":"<code>sustain_pad</code> 카운터멜로디는 이제 프레이즈의 어디에서 들어올지 고릅니다. 진입 지점은 리드가 비워 둔 첫 틱이었습니다 — 같은 프레이즈 길이를 뽑은 모든 시드에 같은 답 — 그래서 네 마디가 모두 한 코드인 뱀프 위에서는 시드 세 개 중 하나가 한 자리에 붙잡은 노트 하나를 받았습니다. 스물일곱 모델이 그것만으로 카운터 다양성 하한 바로 아래에 있었고, 이제 스물셋이 데이터를 바꾸지 않고 하한을 넘습니다.","changelog.c4353fab112d":"⚠ 진입 지점은 프레이즈의 <em>앞쪽 절반</em>에서 고릅니다: 프레이즈의 마지막 마디에 들어오는 패드는 패드가 아니며, 길이가 <code>sustain_pad</code>가 주장하는 전부입니다. 앞쪽 절반이 아무것도 내주지 않을 만큼 레가토인 리드를 위해 예전 답을 대체 수단으로 남겨 두므로, 어떤 모델의 패드도 침묵하지 않습니다.","changelog.be20007c0663":"추가 — 생성기가 응답하는 파트들, 그리고 연구에 빚진 원형 넷, 2026-08-15","changelog.a6502afe501a":"<strong>카운터멜로디를 생성하면 그것이 응답하는 멜로디와, 둘 다 그 위에 쓰인 화성이 채워집니다.</strong> 엔진은 생성을 눌렀든 안 눌렀든 늘 그 파트들을 렌더링해 왔으므로, 새 세션의 카운터는 아무도 들을 수 없는 무언가에 응답했습니다. ⛔ 채움은 새 테이크가 아니라 기록에서 옵니다. 그렇지 않으면 탭이 그것이 응답하는 멜로디와 다른 멜로디를 보여 줄 것입니다.","changelog.a5ea6391fc17":"<strong>연구가 우회해야 했던 장르 원형 열한 개</strong>로, 데이터셋이 <strong>장르 61개와 모델 602개</strong>가 됩니다. 가장 중대한 누락은 <strong>Techno</strong>였습니다: Jeff Mills, Robert Hood, Underground Resistance, Carl Craig, Derrick May, Juan Atkins, Kevin Saunderson이 정당하게 둘 곳이 없어서 빠져 있었습니다. ⛔ 엔진은 Lowend도 표현할 수 없었습니다 — 1과 3의 스네어는 엔진이 아는 어느 배치와도 맞지 않았습니다. ⚠ Techno와 Dominican Dembow는 <code>confidence: low</code>로 출시되며 그 이유를 밝힙니다.","changelog.d0cb1f806314":"<strong>네 멜로딕 생성기 전체에 걸친 단순하게 / 빽빽하게 스위치.</strong> ⛔ 각 모델이 작성한 범위 안에서 조정할 뿐 결코 그것을 덮어쓰지 않습니다 — <em>“빽빽하게 만든 rage 뱀프는 더는 rage가 아니다”</em> — 그리고 세 상태 중 가운데는 작성된 그대로의 모델이므로, 저장된 모든 시드는 여전히 자신의 비트를 다시 만듭니다.","changelog.97da7ec59349":"<strong>스타일 편집기가 롤 어휘, 스네어 배치, 808 동작, 진행 계열에 닿습니다.</strong> ⚠ 모든 그룹은 “기반에서”로 시작합니다: 작성된 값은 부모의 것을 <em>대체</em>하므로, 설정 안 함 상태가 없는 컨트롤이라면 대화상자를 여는 것만으로 스타일의 바탕을 덮어쓰게 됩니다.","changelog.0c5372d37a10":"변경 — 로스터가 다시 자신의 연구처럼 들립니다, 2026-08-15","changelog.58f17233fd10":"<strong>아티스트·프로듀서 모델 396개를 연구 항목에 적힌 값으로 복원했습니다</strong>. 소유자의 지시에 따른 것입니다: <em>“겹치는 건 상관없어요, 저작권 있는 자료를 쓰지 않게만 해 주세요.”</em> 두 차례의 일괄 패스가 그 값들을 옮겨 놓았는데, 둘 다 쌍별 구별성 관문을 통과하기 위해서였습니다. ⚠ 여섯은 이후 상태를 유지합니다. 그 변경은 음악적인 무언가를 고쳤고 무엇을 고쳤는지 밝혔기 때문입니다.","changelog.0540e2c3eea0":"<strong>두 쌍별 관문은 더는 겹침으로 실패하지 않습니다.</strong> 한 계열의, 한 킷 위의, 한 템포의 두 아티스트는 가끔 같은 마디에 떨어지는 것이 <em>당연합니다</em> — 그래야 각자가 일부러 음을 어긋나게 한 이웃이 아니라 자기 자신처럼 들립니다. 둘 다 여전히 상한을 출력하며, <strong>모든</strong> 시드에서 똑같은 쌍에 대해서는 여전히 실패합니다.","changelog.f4e63eedd08b":"<strong>새로움 가드가 이제 베이스라인도 검사합니다</strong>. 그것이 위의 변경을 안전하게 만듭니다. ⛔ 가드는 다섯 리듬 중 하나에만 참인 논리 — <em>“베이스라인은 킥에 묶여 있다”</em> — 로 모든 베이스라인을 제외해 왔는데, <strong>출시된 모델 194개가 <code>independent_riff</code>를 작성합니다</strong>. ⚠ 표는 여전히 해시만 싣습니다: 지문은 윤곽이고, 윤곽에서 노트로 돌아갈 길은 없습니다.","changelog.415ba45149dd":"수정 — 위 나흘 동안의 작업에서 리뷰 패스가 찾아낸 것, 2026-08-16","changelog.9254a5cab370":"한 브랜치에 리뷰어 여섯. 그중 셋이 같은 결함을 독립적으로 찾았습니다.","changelog.2f8b7a34fe32":"<strong>단순하게 / 빽빽하게 스위치는 그것을 읽는 네 입구 중 정확히 하나로만 전달되었습니다.</strong> 엔진의 읽기 셋은 모두 올바랐는데, 페이지가 하나에만 보냈습니다. ⛔ 송 모드는 모델의 작성된 해석으로 편곡하는 동안 그 옆의 모든 루프는 빽빽하게로 답했고, 한 구간을 다시 굴리면 이웃보다 밋밋하게 돌아왔습니다 — 재현 가능하게, 그래서 의도된 것처럼 읽힙니다.","changelog.3447f687fc83":"<strong>스타일 편집기에서 스케일을 체크하면 스타일을 저장할 수 없게 되었고, 이 컨트롤이 출시된 이래 줄곧 그랬습니다.</strong> <code>session.scales</code>가 <code>weights</code> 없이 쓰였는데, <strong>620개 모델 파일 중 599개가 그 쌍을 작성합니다</strong>. 리뷰어 여섯 중 아무도 찾지 못했고 — 롤 결함을 위해 작성한 테스트가 첫 실행에서 잡아냈습니다.","changelog.343ec0c7ac53":"<strong>롤 세분을 하나라도 체크하면 스타일을 저장할 수 없게 되었습니다</strong>. 같은 이유로, 한 블록 옆에서. 린트를 통과했다면 그 스타일은 <strong>햇 롤을 하나도</strong> 쓰지 않았을 것입니다. ⚠ e2e는 내내 통과했고 지금도 통과할 것입니다. 목에는 린터가 없기 때문입니다.","changelog.be4f92504204":"<strong>가져온 스타일이 DAW를 멈추게 할 수 있었습니다</strong>: 루프를 구동하는 키 두 개가 범위 제한 없이 읽혔고, 생성은 호스트가 창을 그리는 스레드에서 동기적으로 일어납니다.","changelog.e73c794fa7f5":"수정 — 2026-08-15","changelog.a20c61b94daf":"<strong>“전체 생성”이 생성 옆에 두 번째 최대 무게의 주 버튼으로 그려졌습니다.</strong> 그 클래스는 8월부터 적용되어 있었는데 <strong><code>src/</code> 어디에도 정의되어 있지 않았습니다</strong>. 이제 색과 안쪽 윤곽선만으로 스타일을 줍니다: 그 행은 편집기 아래에 있으므로, 더 높은 것은 무엇이든 벨로시티 레인의 높이를 빼앗습니다.","changelog.c1d850ee5c0a":"<strong>상류 채움이 실패하면 성공한 생성까지 버렸습니다</strong>. 그래서 거부 하나가 이미 올바르게 돌아온 카운터멜로디를 버렸습니다.","changelog.89075c088097":"<strong>Salaam Remi의 <code>live band</code>와 <code>one drop</code> 무드가 모든 시드에서 같은 멜로디를 생성했으므로</strong>, 그 쌍은 장식에 불과했습니다. 작성된 차이는 원 드롭이 실제로 만드는 차이입니다: 무게가 3박으로 옮겨 가고 라인이 뒤로 물러앉습니다.","changelog.b89dcb6ed30c":"<strong>“uk”를 입력하면 UK Drill 대신 Bassline이 나왔습니다.</strong> 두 글자짜리 맨 태그는 <em>정확</em> 일치로 점수가 매겨져 UK Drill 이름의 <em>접두어</em> 일치를 이깁니다. 같은 일을 하기 전에 셋을 더 제거했습니다.","changelog.e34b5632786a":"추가 — 시대별로 둘러보기, 그리고 프로젝트를 넘어 유지되는 끄기 설정, 2026-08-15","changelog.ee5867f7128b":"<strong>로스터 위의 시대 알약 넷: 90s · 2000s · 2010s · 2020s.</strong> 입력은 이미 그 이름을 댈 수 있을 때 통하고, 둘러보기는 그럴 수 없을 때 하는 것입니다. ⛔ <strong>정렬이 아니라 필터</strong>: <code>boom-bap</code>은 <em>1990년대–현재</em>이므로 네 시대 모두에 동시에 속하며, 정렬은 그것을 하나에 밀어 넣고 나머지 셋에 대해 거짓말을 할 것입니다. 알약은 둘러보는 것을 좁힐 뿐, 찾을 수 있는 것은 결코 좁히지 않습니다.","changelog.20cce385b4bc":"<strong>꺼 둔 생성기는 프로젝트를 다시 열어도 꺼진 채입니다.</strong> 그 상태는 UI 상태에 있었으므로, 다시 열면 베이스라인 스위치가 켜진 채로 돌아오고 그 옆에 클립이 여전히 저장되어 있었습니다 — 그래서 세션이 가져온 기록에는 없는 베이스를 연주했습니다.","changelog.b9dd2c70835c":"<strong>생성기에 놓은 <code>.mid</code>는 그 보이스들이 속한 생성기들로 나뉩니다</strong>. 예전에는 놓기 동작이 파일 전체를 겨냥한 탭 하나로 읽어 들였습니다.","changelog.93349a364b1f":"<strong>원샷 대화상자와 킷 주사위가 하나의 답을 두고 경쟁했습니다.</strong> 둘 다 읽으면 비워지는 우편함을 폴링하므로, 먼저 폴링한 루프가 결과를 가져가고 다른 쪽은 보지 못한 실패 위에서 성공을 보고했습니다.","changelog.aca47e54cbfd":"<strong>곡 탭에서 생성기를 비우면 편곡 전체가 무음이 되었습니다</strong>. 타임라인은 화면에 그대로 있고 재생도 여전히 켜져 있는데도.","changelog.2d60765bc992":"<strong><code>chroma</code>가 읽을 때마다 11.5 MB를 할당했다가 버렸습니다</strong> — 누군가의 DAW의 에디터 스레드에서. 답은 비트 단위까지 그대로입니다.","changelog.0eb460ecdc4a":"<strong><code>explorer_midi</code>는 아무것도 호출하지 않는 브리지 명령이었고</strong>, 이 프로젝트는 그것을 결함으로 분류합니다. 그것이 섬기던 한 파트 읽기와 함께 제거했습니다.","changelog.e21415352325":"추가 — 샘플이 노트가 됩니다, 2026-08-14","changelog.1cb3d917d3aa":"<strong>오디오 파일을 생성기에 끌어다 놓으면 그 파트들이 속한 생성기들로 나뉩니다.</strong>","changelog.286f68904eb7":"<strong>드럼은 두 패스로 분류됩니다.</strong> 스펙트럼이 제안하고 — 150 Hz 아래는 킥, 광대역은 스네어, 위쪽은 햇 — 스펙트럼이 할 수 없는 구분은 <em>마디</em>가 합니다: 2와 4에 있는 것은 어떤 소리였든 백비트이고, 셋잇단 간격의 고역 타격은 하나의 롤입니다. ⛔ 두 번째 패스는 첫 번째 패스가 검출한 것의 역할만 다시 배정할 수 있습니다. 그것이 검출기와 생성기를 가르는 선입니다.","changelog.fd25cb74ee0a":"<strong>베이스는 채보가 필요 없습니다.</strong> 250 Hz로 로우패스하면 살아남는 것이 <em>곧</em> 베이스라인입니다. 킥은 안정된 주기가 없으므로 스스로 빠집니다.","changelog.b79f5af7a4a1":"<strong>코드는 보이싱이 아니라 진행으로 돌아오며</strong>, 패널이 그렇다고 말합니다. ⛔ 전체 믹스의 폴리포닉 채보는 ML 문제이고, 여기서 ML은 금지되어 있으며, 완벽한 추출을 주장하고 근사한 노트를 내놓는 기능은 자신이 하는 일을 말하는 기능보다 나쁩니다.","changelog.fe6b6349383f":"<strong>노래한 라인은 그대로 둡니다.</strong> 보컬 <em>오디오</em>를 분리하려면 ML이 필요하지만, 추출한 <em>노트 라인</em>이 노래였는지 판단하는 것은 산수입니다. ⚠ 강한 Auto-Tune은 네 측정 중 셋을 한꺼번에 무력화합니다. 비브라토는 살아남습니다.","changelog.bf43f015b953":"수정 — 프로젝트 파일이 DAW를 함께 무너뜨릴 수 있던 문제, 2026-08-14","changelog.d7f36c2594cb":"⛔ <strong>공유된 프로젝트에 담긴 박자표가 호스트를 중단시킬 수 있었습니다.</strong> 박자는 페이지와 저장된 고정값에서 들어오는데 어느 쪽도 범위를 검사하지 않았습니다: 25/1은 한 마디의 96분의 1을 4분음표보다 길게 만들었고, 드럼 노트 길이를 제한하는 clamp는 하한이 상한을 넘으면 <strong>패닉합니다</strong>. <code>panic = &quot;abort&quot;</code>는 릴리스에만 적용되므로, 출시된 빌드에서는 그것이 DAW 전체와 그 안의 저장되지 않은 모든 프로젝트입니다. 박자는 들어오는 곳에서 좁혀지고 <em>또한</em> 쓰이는 곳에서 제한됩니다. 어느 한쪽만으로는 다른 입구가 열려 있기 때문입니다. ⚠ 실패하는 테스트가 아니라 코드를 읽다가 찾았습니다 — 스위트는 초록이었습니다.","changelog.b0f4be8222cd":"<strong>브라우저 미리 듣기가 오디오가 아닌 파일을 디코딩하려 했습니다</strong>: 경로가 로컬이고, 라이브러리 안에 있고, 파일인지는 확인했지만 확장자는 한 번도 확인하지 않았습니다.","changelog.505a5ca6f9a1":"수정 — 템포 칩이 무드를 따라잡습니다, 2026-08-14","changelog.cf21ff1cb729":"무드를 고정하면 다음 아티스트 변경 때가 아니라 즉시 칩이 갱신됩니다 — 트랩은 140이고 그 <code>dark</code> 모드는 136이어서, 표시가 엔진이 결코 쓰지 않을 템포를 말하고 있었습니다. ⛔ 베이스 고정에도 같은 빈틈이 있었는데 고쳐진 것처럼 보였습니다: 칩을 다시 읽긴 했지만, 고정값이 플러그인에 닿기 <em>전에</em> 읽었으므로 방금 벗어난 값으로 칩을 채웠습니다.","changelog.d9b7864d6aea":"추가 — 아티스트가 자신이 활동하는 모든 장르에서 생성합니다, 2026-08-14","changelog.a3d424256825":"<strong>“Drake, 하지만 R&amp;B로”.</strong> 로스터는 늘 아티스트를 그가 활동하는 모든 장르 아래에 나열해 왔고 — 아티스트·프로듀서 모델 <strong>534개 중 529개</strong>가 상속받지 않는 장르의 이름을 댑니다 — 생성은 늘 상속받는 장르로만 답해 왔습니다. <strong>생성할 장르</strong> 칩이 어느 쪽인지 고릅니다: 다른 장르의 토대 위에 아티스트 자신의 블록. 그래서 boom-bap 아래의 2Pac은 둘 중 하나가 아니라 <em>boom-bap 위의 2Pac</em>입니다.","changelog.0a39f9a2654c":"⚠ 무드처럼 프로젝트와 함께 저장됩니다 — 아티스트 자신의 장르로 다시 열면 같은 시드에서 조용히 다른 음반이 나올 것입니다. ⛔ 두 장르의 혼합이 아닙니다: 두 베이스를 병합하면 두 모드가 아니라 진흙이 됩니다.","changelog.5484dab868bd":"추가 — 소리에 자신만의 편집기가 생겼습니다, 2026-08-14","changelog.94523aee9a25":"<strong>이제 노트만이 아니라 모든 패드에 편집기가 있습니다.</strong> <strong>노트</strong>에는 편집기가 있었고 <strong>소리</strong>에는 없었습니다. 이제 패드에는 그래픽 <strong>ADSR</strong>(서스테인은 dB로, 참조에서 읽은 대로), <strong>볼륨</strong>, <strong>팬</strong>, <strong>조옮김</strong>, <strong>미세 조율</strong>, <strong>노멀라이즈</strong> 토글, 파형 위의 <strong>시작/끝 트림</strong>, <strong>페이드 인/아웃</strong>이 있습니다 — 모두 패드별로, 저장되며, 돌리는 대로 다시 미리 들려줍니다. ⛔ 교체한 샘플뿐 아니라 기본 탑재된 보이스에도 닿습니다. ⚠ 아무도 편집하지 않은 패드는 비트 단위로 예전 그대로입니다: 항등 엔벨로프는 아예 저장되지 않으므로, 오디오 스레드는 그 계산을 건너뜁니다.","changelog.cce1ec869482":"<strong>참조가 보여 주는 컨트롤 중 둘은 의도적으로 빠졌고</strong>, 패널은 동작할 수 없는 것을 그리는 대신 아무 말도 하지 않습니다.","changelog.4b17bad89480":"<strong>브라우저가 파일을 자체 레벨로, 또는 정확히 있는 그대로 재생할 수 있습니다.</strong> 미리 듣기는 풀 스케일보다 낮게 설정되어 있어 돌아가는 패턴 위의 원샷이 클리핑되지 않습니다 — 합리적이지만, 지금 하는 일이 샘플이 얼마나 큰지 판단하는 것이라면 그 순간 거짓말이 됩니다.","changelog.398db3f04b48":"<strong>패드에 샘플을 올리면 그 패드의 편집기가 열립니다</strong>. 세 경로 모두에서.","changelog.6765e374d806":"<strong>프로젝트에서 가장 오래 걸리던 테스트 바이너리가 1,300.91초 대신 1.70초에 돕니다.</strong> 일곱 테스트에 걸쳐 생성마다 한 번씩, <strong>호출할 때마다</strong> JSON 파일 609개를 다시 읽고 모델 590개 전부를 다시 해석했습니다. 같은 헬퍼가 엔진 바이너리 열다섯 개에 있었습니다.","changelog.79803c0d1988":"<strong>패드 편집 하나로 더는 프로젝트 전체를 잃지 않습니다.</strong> 새 패드별 필드 중 다섯 개가 하한 0은 있고 상한은 없었으므로, 유한하지 않은 값이 저장된 세션에 닿았습니다 — 거기서 <code>null</code>로 쓰여 깨끗하게 저장되었다가 불러오기에 실패해, 시드, 편집한 클립, 편곡, 샘플 폴더, 원샷을 모두 기본값으로 되돌렸습니다.","changelog.82d7ba79435d":"<strong>다시 연 프로젝트가 이제 화면에 보이는 패드 편집을 그대로 연주합니다.</strong> <em>기본 탑재</em> 보이스를 다듬은 것은 노브를 올바르게 복원했지만 오디오 엔진에는 한 번도 알리지 않았으므로, 내보낸 스템에는 엔벨로프가 있고 미리 듣기에는 없었습니다.","changelog.1a72d30e7569":"<strong>장르를 고정하고 생성한 곡이 이제 그 장르를 씁니다</strong>: 고정값이 다시 굴린 구간에는 닿았지만 곡 자체에는 닿지 않았습니다.","changelog.3b327e41cadd":"<strong>샘플을 트림해도 더는 딸깍 소리가 나지 않으며</strong>, 이제 릴리스가 드럼 레인에서 아무것도 하지 않는 대신 꼬리를 다듬습니다.","changelog.79fab545a936":"<strong>부분적인 엔벨로프 때문에 더는 블록 전체를 잃지 않습니다</strong>. 예전에는 이전 빌드가 쓴 프로젝트를 <code>missing field attackMs</code>로 거부했습니다.","changelog.308a6a7f8aa6":"추가 — 라이브러리 규모의 브라우저, 그리고 세션보다 오래 사는 기록, 2026-08-13","changelog.99f4a587028c":"<strong>샘플 트리는 폴더 전체가 아니라 창 하나만큼 그립니다.</strong> 폴더마다 2,000행, 여러 개가 동시에 열리고, 행마다 요소 여섯 개, 컴포넌트가 자기 자신을 호출해 만든 중첩 목록 안에서. 이제 하나의 평평한 순서이고 화면에 보이는 행만 존재합니다 — 파일 2,000개짜리 폴더가 300 ms 안에 열립니다.","changelog.118279c360c1":"<strong>입력해서 트리를 거릅니다.</strong> ⚠ 무엇을 검색했는지 말해 줍니다: 플러그인은 호출마다 폴더 하나를 읽으므로, 필터는 당신이 연 폴더까지만 닿고 그 너머로는 가지 않습니다.","changelog.c74f7d9b9f46":"<strong>존재하지 않는 라이브러리 폴더는 그렇다고 말합니다</strong>. 예전에는 연결이 끊긴 드라이브의 루트가 열리지 않는 평범한 폴더로 그려졌습니다.","changelog.62d394953cc6":"<strong>지금까지 만든 모든 생성을 둘러볼 수 있고, 저장됩니다.</strong> ◀/▶는 “하나 뒤로”에는 답하지만 “여든 개 중 그것 찾기”에는 쓸모가 없습니다. 상한은 <strong>스타일마다</strong>입니다. 전체 상한이라면 한 아티스트로 보낸 저녁이 다시 찾으러 온 테이크를 밀어낼 것이기 때문입니다.","changelog.d004a114800f":"<strong>브라우저에서 <code>.mid</code>를 들어 봅니다</strong>. <strong>중립적인</strong> 악기로 재생하므로 어떤 아티스트를 선택했든 같은 소리입니다.","changelog.be3f0d023b9a":"<strong>로스터 검색 비용이 절반 아래로 줄었습니다.</strong> 검색 상자는 키를 누를 때마다 항목 590개에 점수를 매기는데, 항목마다 쿼리를 다시 정규화하고, 검색 가능한 필드 아홉 개를 모두 다시 정규화하고, 각각을 두 번씩 단어로 쪼갰습니다. 키 입력당 5.5 ms에서 2.9 ms로, 순위는 그대로입니다.","changelog.547ba1349053":"<strong>독립 실행 버전이 릴리스에서 로그를 파일에 씁니다.</strong> 충돌 보고기는 <em>하드웨어 오류</em>는 잡았지만, <strong>패닉</strong>은 <code>windows_subsystem = &quot;windows&quot;</code> 빌드에는 없는 stderr로 갔습니다 — 그래서 재현되지 않은 채 열려 있는 충돌의 원인일 가능성이 가장 큰 실패가 아무 증거도 남기지 않고 있었습니다.","changelog.1dfc33ad2e89":"<strong><code>.mid</code>를 열면 브라우저 기록에 남습니다.</strong> 샘플 미리 듣기와 파트로의 <em>놓기</em>에서는 기록되었지만 그것을 여는 클릭에서는 기록되지 않았습니다 — 그래서 루프 스무 개를 클릭하고 하나를 가져온 사람은 그 하나만 있는 기록을 보았습니다.","changelog.b2294b88f311":"<strong>IPC 목은 고정되지 않은 생성마다 새 시드를 뽑습니다</strong>. 엔진이 그렇듯이. 목은 매번 리터럴 <code>424242</code>로 답했는데, <code>(part, seed)</code>를 키로 하는 기록이 세 번 누른 것을 테이크 하나로 만들 때까지 어떤 테스트도 알아채지 못했습니다.","changelog.931244f782e4":"추가 — 모든 드럼 레인이 피치 레인으로 펼쳐집니다, 2026-08-13","changelog.07f98c226e98":"<strong>어떤 레인이든 피치 행으로 열 수 있습니다</strong> — 레인의 루트, 반음 셋 위, 셋 아래 — 그래서 타격의 음높이가 그리드가 버린 값이 아니라 보고 끌 수 있는 것이 됩니다. 808이 이를 요청했고, 메커니즘은 33개 모두에 같으므로 예외는 없습니다.","changelog.04591dfc7ca3":"<strong>행 높이는 일곱 칸 그대로인데 이동 범위는 무제한입니다.</strong> 맨 위를 넘어 끌면 멈추는 대신 그 레인의 창이 이동하며, 레인마다 자신의 오프셋을 유지합니다.","changelog.ab9329495924":"<strong><code>sub</code>와 <code>subLow</code>는 행을 음이름으로, 다른 모든 레인은 반음으로 표시합니다</strong>. 거기서는 오프셋이 샘플 조옮김이어서, 셰이커를 “D#2”라고 부르면 거짓말하는 표시가 될 것이기 때문입니다.","changelog.a600b5a40e8c":"<strong>창 밖의 타격은 숨겨지지 않고 표시됩니다</strong>. 그래서 미끄러지는 808이 들리는데 보이지 않는 일은 결코 없습니다.","changelog.7a1adb84f977":"<strong>피치 드래그는 실행 취소 한 단계입니다</strong>: 창은 손가락을 따라가지만 노트는 놓을 때 떨어집니다. 그렇지 않으면 드래그 한 번이 반음마다 Ctrl+Z 한 번씩을 요구했을 것입니다.","changelog.768b595223be":"<strong>미리 듣기 파형을 끌어 스크럽합니다</strong>. 스무 번 클릭하지 않고 트랜지언트를 찾는 방법입니다.","changelog.055c12f8042f":"<strong>붙잡은 파트가 더는 뱀프 위에서 무너지지 않습니다.</strong> 두 지속 스타일 모두 코드마다 노트 하나를 썼으므로, 화성이 한 코드에 머무는 모델은 클립 전체에 노트 하나를 받았습니다 — 두 모델이 하한 0.98에 대해 1,000개당 서로 다른 카운터 959개와 963개에 그쳤고, <code>mobb-deep</code>는 <strong>시드 1,000개에 서로 다른 베이스라인 8개</strong>로 측정되었습니다. 이제 두 마디보다 긴 붙잡은 구간은 구간마다 뽑은 프레이즈로 다시 아티큘레이션합니다.","changelog.fc0cebf8ea13":"<strong>KRS-One의 베이스라인이 다시 자기 것이 되었습니다.</strong> 그와 Wu-Tang Clan은 같은 리듬으로 옮겨져 시드 200개 중 42개에서 같은 베이스라인을 쓰고 있었습니다: <code>mirror_kick</code>은 킥에서 온셋을 가져오고 boom-bap 모델 62개가 그것을 공유하므로, 자기 의견이 없는 모델은 킥을 공유하는 이웃이 누구든 그 베이스라인을 씁니다. 이제 KRS-One의 것은 연구가 늘 말해 온 것을 말합니다 — 레게: 더브 슬라이드, 플랫 7, 그리고 원(1박)보다 먼저 연주하는 베이스.","changelog.5ce722b37761":"<strong><code>country-train</code>이 시드 200개에 걸쳐 서로 다른 비트 73개를 씁니다. 24개에서 늘었습니다</strong>. 그리고 <code>rapsody</code>는 136에서 199로.","changelog.b395a0b52253":"추가 — 드럼 그리드가 편집기가 됩니다, 2026-08-11","changelog.f102e9a48f1f":"<strong>상자를 끌어 선택합니다.</strong> Shift를 누른 채 끌면 포인터가 지나간 셀만이 아니라 사각형 안의 모든 셀이 선택됩니다.","changelog.73e932010c9a":"<strong>선택 영역을 복사, 붙여넣기, 복제, 삭제합니다.</strong> 복사한 셋잇단은 셋잇단으로 붙여 넣어집니다: 클립보드는 그리드에 맞추지 않고 실제 노트 타이밍을 유지합니다.","changelog.91eb18c0cd6e":"<strong>오른쪽 클릭한 채 끌어 지웁니다</strong>. <code>Ctrl+Z</code> 한 번으로 되돌립니다. 움직이지 않은 오른쪽 클릭은 여전히 롤 팔레트를 엽니다.","changelog.879ec004b17a":"<strong>레인 이름을 다시 읽을 수 있습니다</strong> — 글자 하나로만 그려지고 있었습니다. 잠긴 자물쇠는 포인터가 무엇을 하든 계속 보입니다. 보이지 않는 잠금은 걸어 둔 것을 잊게 되는 잠금이기 때문입니다.","changelog.f9921d6b3fab":"추가 — 키보드 단축키 패널, 2026-08-11","changelog.d9b9605194c9":"<strong>이제 버튼이 있습니다</strong>. 설정과 정보 옆에. 예전에는 <code>?</code>나 <code>F1</code>을 눌러야만 닿을 수 있었습니다 — 키가 무엇을 하는지 알려 주는 것이 임무의 전부인 패널을, 이미 키를 알아야만 찾을 수 있었던 것입니다. 이제 한 화면에 들어가며, 드럼 그리드 자체의 동작이 처음으로 열여덟 개 언어 전부로 문서화되었습니다.","changelog.62dcea291c83":"수정 — 2026-08-11","changelog.ec59fc38e138":"<strong>클립을 생성하면 모든 노트가 가로로뿐 아니라 세로로도 보입니다.</strong> 이제 롤은 클립을 맨 위에 붙이고 남은 공간을 아래에 두는 대신, 행 크기를 클립 자신의 음역에 맞추고 가운데에 놓습니다.","changelog.1cb0980e60e7":"<strong>루프 범위를 가장자리로 크기 조절할 수 있습니다.</strong> 손잡이는 가장 가까운 핸들이 아니라 범위 안의 <em>첫</em> 핸들을 잡았으므로, 짧은 루프의 오른쪽 가장자리는 아예 잡을 수 없었습니다 — 그리고 눈금자 전체가 크기 조절 커서를 보여 주어, 실제로 크기를 조절하는 한 띠가 보이지 않았습니다.","changelog.78dcc84c55af":"<strong>마지막 남은 네이티브 드롭다운 열 개가 사라졌습니다</strong>. 필드가 아니라 창을 기준으로 OS가 그리던 것들입니다.","changelog.3aae90a5883e":"<strong>위 작업을 리뷰해 찾은 결함 열 개</strong>, 각각 먼저 실패하는 것을 지켜본 테스트와 함께 고쳤습니다. 넷은 그리드의 붙여넣기에 있었는데, 모두 그리드는 열 단위로 생각하는데 틱 단위로 측정한 데서 왔습니다: 휴머나이즈로 일찍 당겨진 타격은 첫 셀에 붙여 넣으면 사라졌고, 밀도가 높은 영역 위에 붙여 넣은 성긴 형태는 밀도 높은 쪽의 여분 타격을 남겼으며, 붙여넣기가 다른 곳으로 재배정한 레인을 되살릴 수 있었습니다.","changelog.ba30e336f27a":"추가 — 새 장르 32개, 2026-08-10","changelog.eee977220c4e":"<strong>장르 목록이 20개에서 52개로 늘어납니다</strong> — dark plugg, Detroit bounce, Jersey club, ATL swag rap, UK underground, EDM rage, digicore, jump-up DnB, neurofunk, jungle, pop DnB, UK garage, house, dance pop, pop 2020s, country pop, country shuffle, neo-soul, funk, future bass, afrobeats, amapiano, dancehall, reggaeton, baile funk, afroswing, Memphis rap, G-funk, lo-fi hip hop, sexy drill, hyphy, crunk.","changelog.42f059fbabae":"각 장르는 자신만의 드럼, 코드, 멜로디, 카운터멜로디, 베이스라인을 씁니다 — 파트를 통째로 상속하는 것은 없습니다 — 그리고 각각 무드 셋과 함께 도착하므로, 장르 하나를 고르면 음반 하나가 아니라 서로 다른 음반 셋이 나옵니다. 하나하나가 로스터의 나머지와 견주어 측정됩니다.","changelog.10d9e1d4972b":"수정 — 노트가 패턴 끝을 넘어 지속될 수 있던 문제, 2026-08-10","changelog.bbb3fb833dc4":"늦게 밀린 고스트 스네어나 마지막 세분 위의 탬버린이 길이를 패턴 너머로 끌고 갈 수 있었습니다 — 그래서 끌어낸 클립에 마디에 자리가 없는 노트가 들어 있었습니다. 다른 생성기 넷은 늘 잘라 왔지만, 킷은 한 번도 그러지 않았습니다.","changelog.e9fa1c28ce6f":"수정 — 베이스라인이 조를 벗어날 수 있던 문제, 2026-08-10","changelog.37090d443d59":"<strong>반음계적 베이스 노트가 이제 어딘가에 도착합니다.</strong> 경과음은 <em>코드</em>에서의 음정으로 쓰이는데, 평범한 코드 위에서는 그 음정이 조를 벗어날 수 있습니다 — 그래서 베이스는 어디서 오지도 어디로 가지도 않는 노트를 연주했습니다. 이제 베이스 연주자가 코드 변화로 걸어 들어가듯, 다음 노트로 다가갑니다. 걸어가는 플랫 7과 블루 노트는 유지됩니다: 그것은 버그가 아니라 어법입니다.","changelog.2d6b36e508b4":"<strong>베이스가 더는 자신이 받치는 코드보다 높게 연주하지 않으며</strong>, 베이스가 자신의 808을 노트 하나하나 똑같이 겹치던 네 모델은 이제 진짜 두 번째 파트를 연주합니다.","changelog.d0b5a7643bda":"수정 — 플러그인이 낡은 장르 목록을 실어 보낼 수 있던 문제, 2026-08-10","changelog.9411b413d18e":"데이터셋은 바이너리 안에 컴파일되는데 빌드 시스템에 그것을 지켜보라고 알려 주는 것이 없었으므로, 모델이 바뀐 뒤에 빌드한 플러그인이 컴파일 당시의 로스터를 계속 내놓을 수 있었고, 어디에도 그렇다고 말하는 것이 없었습니다.","changelog.77caf45cd87d":"수정 — 파일 탐색기가 하위 폴더를 열 수 없었고, 그 때문에 다른 네 가지도 깨지던 문제, 2026-08-10","changelog.b5ed0979ba9d":"<strong>다시 어떤 깊이의 하위 폴더로든 들어갈 수 있습니다.</strong> 라이브러리 폴더를 여는 것은 동작했지만, 그 <em>안의</em> 무엇을 여는 것은 거부되었습니다. Windows의 <code>canonicalize</code>는 <code>\\\\?\\</code>로 시작하는 경로를 돌려주는데, 네트워크 경로를 거부하는 검사가 그 앞의 <code>\\\\</code>를 네트워크 경로로 취급했기 때문입니다. <strong>같은 거부가 미리 듣기 플레이어, 파형, <code>.mid</code> 읽기, 드럼 패드에 샘플 놓기를 조용히 깨뜨리고 있었습니다</strong> — 모두 같은 가드를 거칩니다. 진짜 UNC 경로는 여전히 거부됩니다.","changelog.ade18cd195aa":"<strong>브라우저가 레일 전체를 쓸 수 있습니다</strong>. 예전에는 폴더가 아무리 깊어도 높이의 약 절반으로 제한되었습니다.","changelog.1b52bf9f1edf":"보안 — 페이지가 넘겨준 경로로 플러그인이 낯선 상대에게 인증할 수 있던 문제, 2026-08-10","changelog.b99ed6cfdb4b":"**파일에 별표를 달면 네트워크 경로인지 확인하기 <em>전에</em> 라이브러리를 확인했고**, 디스크에 닿는 것은 바로 그 라이브러리 확인입니다. Windows에서 그것은 읽기가 아닙니다 — Windows 자격 증명을 넘겨주는, 바깥으로 나가는 SMB 세션입니다. 플러그인 자신의 웹뷰에서 온 메시지 하나면 충분했습니다. 이제 가드는 포함 검사 자체 안에 있으므로, 앞으로 어떤 명령도 이를 다시 들여올 수 없습니다.","changelog.c11b4781c6b1":"<strong>공유된 프로젝트 파일이 샘플 라이브러리를 드라이브 전체로 지정할 수 있었습니다.</strong> 라이브러리 폴더는 프로젝트 파일 안에 담겨 이동하는데 <em>네트워크</em> 경로만 거부되었으므로, 프로젝트가 <code>C:\\Users</code>를 담아 라이브러리 안의 파일을 읽는 모든 것에 조용히 전부를 허락할 수 있었습니다.","changelog.436b592f6cec":"<strong>형식이 잘못된 MIDI 파일이 DAW를 죽일 수 있었습니다.</strong> 박당 1틱으로 극단적인 박자표를 선언한 파일이 편곡 리더를 자신의 틱 공간 끝 너머로 밀어냈습니다. 릴리스 빌드에서는 그것이 저장하지 않은 세션과 함께 호스트를 무너뜨립니다.","changelog.4c1f2cf3c0a6":"수정 — 작업이 사라질 수 있던 세 가지 경로, 2026-08-10","changelog.4c212624c7d8":"<strong>샘플 폴더가 여덟 개를 넘는 프로젝트는 넘친 폴더를 잃었습니다.</strong> <em>추가</em>할 수 있는 수의 상한이 <em>불러올</em> 때도 적용되었고, 잘린 목록이 그대로 프로젝트에 다시 쓰였습니다. 추가할 수 있는 것의 한계가 이미 가진 것을 지울 자격은 아닙니다.","changelog.880491ce97f6":"<strong>가져온 곡이 저장되지 않았습니다.</strong> MIDI 파일을 곡 탭에 끌어다 놓으면 타임라인은 채워졌지만, 프로젝트에 그것을 저장하라고 요청하는 것이 없었습니다.","changelog.8e4f72c4b2d3":"<strong>실행 취소가 가져온 곡을 지웠습니다.</strong> 가져온 것은 어떤 아티스트에도 속하지 않는데, 한 아티스트의 편곡이 다른 아티스트에게 새어 들어가는 것을 막는 가드가 그것을 불일치로 읽었습니다: 가져온 뒤 키 한 번, Ctrl+Z가 그것을 지웠고 Ctrl+Y로도 되돌릴 수 없었습니다.","changelog.cdb3914ece4a":"추가 — 제대로 된 파일 트리, 폴더 탭, 별표 즐겨찾기, 그리고 자신이 무엇인지 아는 MIDI, 2026-08-10","changelog.8f46d9bab3fb":"<strong>브라우저가 제대로 된 트리가 됩니다</strong>. 폴더 사이를 오갈 때 열어 둔 것을 기억하며, 라이브러리 폴더를 최대 여덟 개까지 탭으로 둡니다.","changelog.d384c27e9841":"<strong>앱을 닫아도 라이브러리가 남습니다.</strong> 예전에는 <em>프로젝트</em> 안에만 저장되었으므로, <code>.als</code>와 함께는 돌아왔지만 독립 실행 버전에서는 결코 돌아오지 않았습니다.","changelog.0985960cb1d0":"<strong>별표 즐겨찾기.</strong> 하나를 클릭하면 트리가 루트에서 그 파일까지의 모든 폴더를 엽니다 — 또는 그 폴더가 더는 여덟 탭 중 하나가 아니라면, 대신 탐색기나 Finder에서 파일 위치를 엽니다.","changelog.6fdc895ea960":"<strong>키보드로 트리를 걷습니다.</strong> <code>↑</code>/<code>↓</code>는 행 사이를 움직이고, <code>→</code>는 폴더를 열고 <code>←</code>는 닫습니다 — 그리고 <em>파일</em> 위에서는 같은 키가 파일을 정방향과 역방향으로 재생합니다. 폴더에는 미리 들을 것이 없고 샘플에는 펼칠 것이 없으므로, 무엇을 뜻했는지 결코 모호하지 않습니다.","changelog.60837102da5c":"<strong><code>.mid</code> 파일이 표시되고</strong>, 오디오와는 정직하게 구분됩니다: 패드는 나중에 오류를 내는 대신 손을 놓기 전에 그것을 거부합니다.","changelog.b1043457ecb3":"추가 — MIDI 파일을 놓으면 그 안에 무엇이 있는지 알아냅니다, 2026-08-10","changelog.fd88ab1f798a":"<code>.mid</code>를 생성기에 끌어다 놓으면 노트가 거기 떨어지고, 곡 탭에 놓으면 원하는 파트를 고를 수 있습니다 — 파일 전체가 편곡으로 도착하며, 당신이 고르기 전에는 아무것도 지금 가진 것을 덮어쓰지 않습니다. 여러 겹으로 된 파일은 베이스, 멜로디, 카운터, 코드, 드럼으로 나뉘고, <strong>모든 파트가 왜 그곳으로 보내졌는지 말해 주므로</strong> — “GM 드럼 채널에 있음”, “가장 낮은 보이스”, “파일 이름에서” — 잘못된 추측은 클릭 한 번으로 바로잡을 수 있습니다.","changelog.e560b4cd27a4":"<strong>가정이 아니라 실제 파일로 가르쳤습니다.</strong> 샘플 팩 내보내기 네 개가 첫 버전을 세 번 중 세 번 깨뜨렸습니다: 팩은 드럼을 GM 드럼 채널이 아니라 <strong>채널 0</strong>에 두므로, 드럼은 모양으로 인식됩니다 — 몇 안 되는 음높이를 여러 번, 짧게 치는 것. 붙잡은 멜로딕 노트는 끊임없이 겹치므로, 코드는 그저 겹치는 노트가 아니라 <em>함께</em> 친 노트입니다. 그리고 <strong>808의 MIDI 노트는 그것이 얼마나 낮게 들리는지가 아니라 어떤 키가 샘플을 울리는지를 말하므로</strong>, 베이스라인이 흔히 멜로디 음역에 있습니다 — 그래서 어떤 측정보다도 파일 자신의 이름을 믿습니다.","changelog.08e81ba37df8":"추가 — 무대 위의 드럼 패드, 어떤 아티스트든 찾는 상자 하나, 그리고 마침내 제대로 동작하는 창, 2026-08-09","changelog.5a8e71fc3e5d":"<strong>무대 위쪽에 드럼 패드 여덟 개</strong>. 각 패드는 모든 것을 앞면에 담고 있습니다: 레인 이름, 올라가 있는 것, 들리는지를 나타내는 초록이나 빨간 점, 단독으로 미리 듣는 재생, 다시 굴리는 셔플, 그리고 내장 소리로 되돌리는 ✕. 두 패드가 한 레인을 공유할 수 있어 스네어를 겹칠 수 있으며, 배치는 <strong>아티스트마다</strong> 기억됩니다.","changelog.7a967cc608c0":"<strong>검색 상자, 칩 줄, 500행짜리 목록 대신 콤보박스 하나.</strong> 입력하면 아티스트, 장르, 별칭, 오타까지 걸러집니다. 중간에 멈추고 다른 곳을 클릭하면 가장 잘 맞는 것을 고르므로, 아무것도 선택되지 않은 상태로 끝날 수 없습니다. “Original Workflow”는 무엇이 선택되어 있든 맨 위에 고정됩니다.","changelog.cca505068909":"<strong>생성기 음소거 스위치가 탭 위로 옮겨졌습니다</strong>. 같은 여섯 단어를 담은 두 번째 줄이었기 때문입니다 — 그래서 어느 것이 드럼을 무음으로 했는지 알아내려면 “드럼”을 두 번 읽어야 했습니다.","changelog.635de9290198":"<strong>생성하면 클립 전체가 보입니다</strong>. 길이가 얼마든.","changelog.34647eb32c75":"수정 — 2026-08-09","changelog.cb746382c26e":"⛔ <strong>플러그인은 DPI를 인식하지 않은 채 돌았고 WebView2는 그렇지 않았습니다.</strong> 150% 디스플레이에서 Windows는 창을 절반만큼 더 늘렸고 페이지는 실제 픽셀로 렌더링되었으므로, UI가 창의 3분의 2만 덮었고 창을 끌어도 내용이 따라오지 않았습니다. 불일치 하나, 증상 둘.","changelog.1c0e1181baae":"<strong>창을 끌고, 크기를 조절하고, 최대화할 수 있으며</strong>, 앱이 설계된 크기보다 작아지지 않습니다.","changelog.395cd7a6da0c":"<strong>스타일의 복사된 샘플이 다시 불러와집니다.</strong> 동의 관문과 복사는 둘 다 동작했는데, 그것을 읽는 것이 하나도 없었으므로 빌드가 그 체크박스를 싣고 있는 동안 체크박스의 약속은 거짓이었습니다.","changelog.cab98edaf117":"<strong>“단타”가 더는 자신이 가리키는 노트를 지우지 않습니다</strong> — 롤을 다시 단타로 접습니다.","changelog.535170bf7968":"<strong>독립 실행 버전을 더블클릭하면 실행됩니다.</strong> 명령줄 플래그에 의존하지 않고 자체 오디오 주기 크기를 제공합니다.","changelog.06c7109c2a8c":"추가 — 모든 아티스트에 무드가 생기고, 나만의 스타일을 만들어 학습시킬 수 있으며, 묻지 않고 샘플을 복사하는 일은 없습니다, 2026-08-09","changelog.a4377a96815d":"<strong>이제 모든 아티스트와 장르에 무드가 있습니다.</strong> 무드가 없던 열두 장르가 이제 각각 셋을 제공합니다 — boom bap의 <em>dusty / jazzy / hard</em>, country의 <em>shuffle / ballad / barnburner</em>. 생성을 누르면 시드만 다른 한 가지 소리를 돌려주는 대신 아티스트의 폭을 돕니다: <strong>(아티스트, 무드) 쌍 96개</strong>, 33개에서 늘었습니다.","changelog.89a78f654f4d":"<strong>Original Workflow — 나만의 스타일 만들기.</strong> 이름을 붙이고, 어떤 아티스트나 장르를 바탕으로 삼고, 템포 범위, 스윙, 밀도, 스케일을 정하고 저장하세요. 함께 실린 스타일과 정확히 같은 방식으로 생성하고, 잠그고, 다시 굴리고, 내보냅니다. 같은 종류의 것<em>이기</em> 때문입니다 — 바꾸지 않은 모든 것을 상속하며, 바탕이 나중에 얻는 개선까지 이어받습니다.","changelog.ce63a23ea1c7":"<strong>남겨 둔 테이크로 워크플로를 학습시킵니다.</strong> 서른 개가 되면 학습이 남겨 둔 것에 맞춰 스타일을 맞추며, 스스로를 반복하는 스타일은 저장하지 않습니다. <strong>여기에는 머신 러닝이 없습니다</strong>: 테이크를 측정해 숫자를 되써 넣을 뿐이고, 앱은 완전히 오프라인으로 남습니다.","changelog.5f1d99513891":"<strong>장르 칩이 클릭할 수 없다고 말했습니다.</strong> 장르 줄은 완벽하게 동작하는 컨트롤 위에 “금지” 커서를 보여 주었고, 레이아웃이 처음 그려진 이래 줄곧 그랬습니다.","changelog.f5f2401fda2d":"<strong>학습이 DAW를 멈추게 할 수 있었습니다.</strong> 학습된 스타일이 스스로를 반복하지 않는지 확인하는 검사가, 호스트가 창을 그리는 스레드에서 수천 번의 생성을 돌렸습니다.","changelog.7de627bf6f0a":"추가 — 멜로디가 남을 인용하지 않고, 모든 장르가 자신의 목소리를 얻고, 햇이 말을 합니다, 2026-08-08","changelog.c0ae9370557e":"<strong>⛔ 새로움 가드</strong>. 생성된 멜로디가 이미 누군가 소유한 훅이 되지 않도록. 모든 멜로디와 카운터멜로디는 당신이 듣기 전에 잘 알려진 윤곽들의 내장 표와 대조됩니다. <strong>표 안의 어떤 것도 멜로디가 아닙니다</strong>: <em>윤곽</em>의 일방향 지문을 담고 있으며, 지문에서 노트로 돌아갈 길은 없습니다. 훅을 조옮김해도 숨길 수 없습니다.","changelog.30b1c2284c32":"<strong>이제 모든 장르에 자신만의 멜로디, 카운터멜로디, 코드가 있습니다</strong>. 다섯 장르가 공유 기본값으로 되돌아가던 대신. 808이 없는 여섯 장르는 진짜 베이스라인을 얻었습니다.","changelog.030f3251348a":"<strong>⛔ 하이햇 필.</strong> 햇은 trap, drill, plugg가 말을 하는 곳입니다: 흐름을 끊는 프레이즈 끝의 형태 — 롤, 스터터, 셋잇단 버스트, 램프, 또는 햇이 뚝 멈추는 <strong>공백</strong>.","changelog.d453628fda56":"<strong>⛔ 드럼을 잠가 다시 굴리기가 건드리지 못하게 하고</strong>, <strong>모든 드럼 레인에 솔로</strong>. 음소거한 레인은 솔로 중에도 음소거된 채입니다.","changelog.28b35f4817da":"<strong>⛔ 프로젝트보다 오래 사는 패턴 라이브러리</strong> — 킷 없이 노트로 저장됩니다. 하나하나가 별도 파일이므로, 저장이 잘못되어도 선반 전체가 아니라 루프 하나만 잃습니다.","changelog.f3ac9ded3a5f":"<strong>⛔ 이번 세션에서 만든 모든 테이크</strong>. 아티스트, 무드, 시드, 마디, 고정값까지 설정 전체를 되돌립니다.","changelog.1e86a4e5892e":"골든 스냅샷 넷이 움직였고, 다시 생성하기 전에 차이를 하나하나 읽었습니다: trap과 UK drill은 이제 하이햇 필을 작성합니다. <code>ny-drill</code>, <code>liquid-dnb</code>, <code>country-train</code>, <code>boom-bap</code>은 베이스라인을 상속하는 대신 자신의 베이스라인을 연주합니다. 그리고 오픈 햇 위에 겹쳐 있던 클로즈드 햇 하나가 사라졌는데, <code>humanize</code>가 레인을 노트 순서로 걷기 때문에 이후 모든 햇의 벨로시티가 바뀝니다.","changelog.bff5ca6b89e9":"수정 — 리뷰가 찾아낸 것, 2026-08-09","changelog.5267b9a16e83":"독립적인 검증을 통과한 발견 열다섯 개. 가장 나쁜 것부터:","changelog.0c5c4cec0863":"<strong>⛔⛔ 패턴 라이브러리를 열면 DAW 전체가 무너질 수 있었습니다</strong>. 저장된 파일 자체의 숫자로 계산한 클립 길이로 나누는데 — 운 나쁜 한 쌍이면 0으로 나누고, 플러그인은 되감지 않고 중단합니다.","changelog.4c20acd804e4":"<strong>⛔⛔ 패턴을 저장하면 다른 패턴이 조용히 지워질 수 있었습니다</strong>: “Take 1”과 “Take-1”이 같은 파일 이름이 되었습니다.","changelog.89c7905e0b4b":"<strong>⛔⛔ 잠긴 레인이 저장된 프로젝트에서 사라질 수 있었습니다</strong>. 다시 열 때 클립이 시드로부터 다시 만들어졌기 때문입니다 — 그리고 더 짧은 클립의 끝을 넘어 노트를 지닐 수 있었으므로, 그리드는 깨끗한 네 마디를 그리는데 내보낸 것은 5~8마디에 타격을 연주했습니다.","changelog.96f10a153c71":"<strong>⛔ 송 모드는 한 번도 새로움 가드를 돌리지 않았습니다</strong>. 가드는 멜로디 탭이 쓰는 경로에 설치되었는데 송 모드는 생성기를 직접 호출하기 때문입니다. 테스트는 출력이 아니라 연결을 단언합니다. 출시된 로스터로는 검사한 출력과 검사하지 않은 출력이 똑같아서, 뻔한 테스트로는 실패할 수가 없었기 때문입니다.","changelog.f4b2d931a43d":"<strong>⛔ 손으로 추가한 하이햇 필이 40틱 일찍 떨어졌습니다</strong>. 그리드가 <em>휴머나이즈된</em> 노트가 어느 셀에 속하는지 정할 때 쓰는 창을 가져다 썼기 때문입니다 — 읽기에는 맞고 쓰기에는 틀립니다.","changelog.0830687ca248":"⚠ 관문 둘이 주장하는 것보다 적은 것에 대해 성공을 보고하고 있었습니다: 레인 목록은 엔진의 37개 중 21개로 어긋나 있었고, 솔로 테스트는 멜로딕 파트가 무음이 되도록 <em>요구했습니다</em> — 그 동작이 리뷰를 통과해 살아남은 이유입니다.","changelog.4e59efdbda65":"추가 — 실제로 쓸 수 있는 샘플 브라우저, 그리고 클립처럼 보이는 클립, 2026-08-07","changelog.3ac5714f8a97":"<strong>⛔ 샘플 브라우저가 화면에 있습니다.</strong> 폴더를 한 번 추가하면 프로젝트와 함께 돌아오고, 샘플을 클릭하면 파형이 보이며 <strong>드럼 레인에 바로 끌어다 놓을 수 있습니다</strong>. 이 모든 것을 뒷받침하는 기능은 지난 세션에 출시되었지만 닿을 방법이 없었습니다.","changelog.e158007006c0":"<strong>브라우저 아래의 미리 듣기 플레이어</strong> — 파형의 어디든 클릭하면 그 지점부터 재생합니다.","changelog.2c629c57d407":"<strong>⛔ 편곡의 클립이 클립처럼 보입니다</strong>. 음영 상자 위의 이름 대신 자신의 노트를 그리므로, 같은 파트의 두 클립이 더는 똑같아 보이지 않으며, 각각을 따로 DAW로 끌어 넣을 수 있습니다.","changelog.ef9a103aedc5":"<strong>⛔ 클립 크기를 조절합니다</strong>: 오른쪽 가장자리를 끌면 그 행이 구간 안에서 더 적은 마디로 반복되며, 구간이나 다른 파트는 움직이지 않습니다.","changelog.84e02b004ba3":"<strong>⛔ 편곡 보기가 DAW처럼 배치됩니다.</strong> 예전에는 트랙 이름이 클립 위에 떠 있어서, 1마디에서 “DRUMS”라는 단어가 모든 행의 첫 클립 위에 놓여 있었습니다.","changelog.0b3d5bf7e564":"수정 — 세 리뷰가 찾아낸 것, 2026-08-07","changelog.b35639f57cb2":"<strong>⛔ 크기를 조절한 클립의 긴 노트가 자신의 다음 반복까지 울렸으므로</strong>, DAW는 이미 다시 친 노트에 맞서 그 노트를 뚝 잘랐습니다.","changelog.0c66c5b6f618":"<strong>⛔ 4/4가 아닌 박자에서 하이햇이 고스트 노트를 모두 잃었습니다</strong> — 6/8, 12/8, 그리고 모든 x/16 박자에서 흐름 전체가 하나의 평평한 벨로시티로 나왔습니다.","changelog.6af16dde009c":"<strong>⛔ “offbeat”로 설정한 퍼커션이 완전히 무음이 되었습니다</strong>. x/16과 x/32 박자에서.","changelog.e476442a0ddc":"<strong>크기를 조절한 클립이 연주하지 않는 노트를 그렸습니다</strong>. 반복마다 패턴 전체를 욱여넣은 모습으로.","changelog.4f5db5bbdf0a":"<strong>구간을 다시 굴리거나, 클립을 복사·붙여넣기·끌기 하면 그 클립에 설정해 둔 루프 길이가 버려졌습니다.</strong>","changelog.5878d98d269b":"드럼과 베이스를 생성하는 사이에 마디를 바꾸거나, 템포를 고정하거나, 무드를 바꾸면 <strong>베이스라인이 여전히 엉뚱한 킥을 따라 할 수 있었습니다</strong>.","changelog.6e929e8afe20":"수정 — 미리 듣기 플레이어, 2026-08-07","changelog.b2864d845e0f":"<strong>⛔ 오디오 스위치가 꺼져 있으면 샘플 미리 듣기가 무음이었습니다.</strong> 재생에는 불이 들어오고, 플레이어는 재생 중이라고 말하고, 재생 헤드는 0:00에 얼어 있었습니다. 오디오를 끈다는 것은 “MIDI를 내 샘플러로 보내고, 겹치지 말라”는 뜻입니다 — 방금 클릭한 파일을 브라우저가 재생하지 못하게 하려는 것이 결코 아니었습니다.","changelog.b9168982fff3":"<strong>일시 정지된 파형을 클릭하면 재생 헤드가 움직였다가</strong> 0.5초 뒤에 스스로 되돌아갔고, 재생을 누르면 샘플이 이미 울리는 동안 재생 헤드가 최대 0.5초 동안 멈춰 있었습니다.","changelog.86b2b194f286":"수정 — 2026-08-07","changelog.9163da2a1dd7":"<strong>⛔ 편곡 보기 전체가 스타일 없이 그려지고 있었고</strong>, 작성된 이래 줄곧 그랬습니다: 요청한 모든 색이 이 앱이 정의하지 않은 이름이었으므로, 클립에는 채움이 없고, 그리드 선은 보이지 않았으며, 재생 헤드는 투명한 띠였습니다.","changelog.3a92a8640214":"<strong>베이스라인이 드럼이 연주하지 않는 킥 위에 떨어졌습니다.</strong> 킥을 따라 하는 베이스 — trap과 drill 로스터 대부분 — 가 엉뚱한 시드로 다시 만든 킥 패턴을 복사하고 있었습니다: boom-bap에서는 예전에 베이스 노트 13개 중 13개가 실제 킥 위에 있었는데, 평범한 워크플로에서는 그것이 9개로 떨어졌고, UK drill에서는 14개 중 1개로 떨어졌습니다.","changelog.6683ee09105f":"<strong>“offbeat”로 설정한 퍼커션이 모든 x/8 박자에서 박자 위에 그대로 연주되었습니다</strong> — 펄스 사이에 있어야 할 레이어가 펄스를 겹쳤습니다.","changelog.81d18857bf68":"<strong>드럼 보이스 여섯 개가 들을 방법 없이 출시되었습니다.</strong> 라이드, 크래시, 탐, 셰이커, 카우벨이 킷에 있었지만 그것을 연주하도록 작성된 아티스트는 하나도 없었습니다.","changelog.7644b0a943fa":"추가 — 제대로 된 드럼 킷, 샘플 브라우저, 그리고 장르마다 킷, 2026-08-07","changelog.ff8354926c13":"<strong>⛔ 이제 드럼 레인이 다섯 개를 넘습니다</strong> — 퍼커션 보이스 열여섯 개이고, 아티스트가 무엇을 쓰는지는 그 아티스트의 일부입니다. 출시된 모델 열다섯 개가 이미 퍼커션 블록과 함께 <em>작성되어</em> 있었지만 그것을 읽은 것이 하나도 없었으므로, UK drill은 작성된 날부터 우드블록을 요청하고 침묵을 받아 왔습니다.","changelog.90dc63284666":"<strong>⛔ 모든 장르가 자신만의 킷을 얻습니다.</strong> 열한 계열, 각자의 튜닝, 고역, 드라이브. Boom-bap의 상한은 8 kHz인데, SP-1200이 샘플링할 수 있었던 것이 그것이고, 그 빠진 고역이 <em>곧</em> 그 소리이기 때문입니다. 여덟 아티스트가 몇 달 동안 원하는 킷의 이름을 대고 있었는데 모두 trap 샘플을 연주하고 있었습니다.","changelog.2b625ec90b28":"<strong>808 레인의 이름이 이제 Sub입니다</strong>. 베이스 드럼이 아니라 미끄러지는 음높이 있는 베이스이기 때문입니다. 저장된 프로젝트는 예전과 똑같이 열립니다.","changelog.704ed387ab2f":"<strong>⛔ 생성은 기록을 바꾸지 않고 테이크를 변화시킵니다.</strong> 드럼에서 생성을 누르고, 멜로디로 바꿔 다시 누르면: <em>같은</em> 키와 진행 위에 쓰인 다른 멜로디를 얻습니다. 예전에는 두 번째 누름이 무관한 화성을 뽑았고, 두 파트는 서로를 상대로 쓰인 적이 없었습니다.","changelog.ff4a09ab118e":"<strong>두 번째 생성기가 켜져 있으면 끌어 놓은 루프 범위가 무시되었습니다</strong> — 그것이 기본값인데도. 파트 하나가 재생될 때는 동작했고, 둘일 때는 조용히 아무것도 하지 않았습니다.","changelog.41b8497a15e0":"<strong>재생과 정지가 엉뚱한 때에 켜지거나 꺼졌습니다.</strong> 드럼을 생성하고 멜로디를 클릭하면, 드럼이 준비되어 소리를 낼 수 있는데도 재생 버튼이 꺼졌습니다.","changelog.ab49c439eefd":"<strong>위치 표시가 엉뚱한 클립을 세고 있었습니다</strong>: 네 마디짜리 드럼과 여덟 마디짜리 멜로디가 나란히 있으면, 실제 시간 여덟 마디에 걸쳐 1.1에서 5.1까지만 읽혔습니다.","changelog.649c3a0d7720":"<strong>플러그인 창을 다시 열면 루프가 다시 켜졌습니다</strong>. 무엇으로 설정해 두었든.","changelog.ded642647f5b":"추가 — 생성기들을 함께 재생하고, 808이 미끄러집니다, 2026-08-06","changelog.9e2b80b85108":"<strong>여러 생성기를 한꺼번에, 또는 어느 하나만 재생합니다.</strong> 스케줄은 클립 하나만 담으므로, 파트들은 그 전에 하나로 병합됩니다 — 그래서 탭마다 차례로 재생을 눌러서는 이것을 할 수 없었습니다.","changelog.b6951a486c5e":"<strong>⛔ DAW가 돌지 않아도 플러그인이 재생합니다.</strong> 비트를 미리 듣는 것이 더는 트랙을 준비하고 프로젝트 전체를 시작하는 일을 뜻하지 않습니다. DAW의 트랜스포트를 시작하면 곧바로 그쪽이 넘겨받으므로, 둘이 동시에 재생되는 일은 결코 없습니다.","changelog.f10831f4b7f5":"<strong>⛔ 루프 버튼이 동작합니다.</strong> 늘 눌린 채 비활성화되어 있었고, 재생이 항상 반복된다고 주장하는 툴팁이 달려 있었습니다 — 범위를 끌어 두지 않았다면 그것조차 사실이 아니었습니다.","changelog.8d2084738b75":"<strong>⛔ 808 슬라이드가 들립니다.</strong> 생성기는 오래전부터 슬라이드를 써 왔고 MIDI도 늘 그것을 담았지만, 렌더링된 WAV는 모두 그것을 평평한 노트로 연주했습니다. 이제 음높이가 이동합니다. 처음 절반은 시작 노트를 붙잡고 나머지 절반에 걸쳐 미끄러집니다 — 그리고 같은 코드가 미리 듣기, 내보내기, 드래그를 맡으므로, 스템은 그 옆의 <code>.mid</code>와 같은 소리를 냅니다.","changelog.f9fa438e3093":"수정 — 드럼 레인, KIT 패널, 그리고 짧은 오른쪽 레일, 2026-08-06","changelog.e9469a9c1fda":"<strong>⛔ 드럼 오디오의 “모든 트랙”이 읽히는 것과 반대로 표시되어 있었습니다.</strong> 레인마다 파일 하나를 주었고, “한 클립으로”라는 두 번째 항목이 믹스를 주었습니다. 이제 레인마다 항목 하나가 있고, <strong>“모든 트랙”은 모든 레인을 한 파일로 믹스한 것</strong>입니다.","changelog.ab3f925aaf69":"<strong>⛔ KIT 패널이 더는 STEMS 패널 위에 겹쳐 그려지지 않습니다.</strong> 짧은 창에서 KIT 섹션은 높이가 0으로 접혔는데 내용은 원래 높이를 유지했으므로, 그 글자가 아래 패널 위에 읽을 수 없는 얼룩으로 칠해졌습니다.","changelog.b8b2c0b5ce11":"수정 — 에디터 창이 스스로 크기를 올바르게 정합니다, 2026-08-06","changelog.91804d15bbeb":"<strong>⛔ UI 주변의 검은 띠가 사라졌습니다.</strong> 에디터 창의 크기가 나머지 기하와는 다른 순간에 읽은 디스플레이 배율로 정해졌으므로, 앱이 자신을 감싸는 창의 3분의 2가 되어 버렸습니다.","changelog.0e393d0c7690":"<strong>⛔ 크기 버튼이 네 가지가 아니라 두 가지 크기를 제공합니다.</strong> 디스플레이 배율을 누를 때마다 새로 읽었는데 그 값이 에디터 밑에서 바뀝니다 — 창 시스템이 프로세스가 DPI를 인식한다는 말을 듣기 전까지는 100%로 읽히고, 그 말은 에디터의 크기가 정해진 <em>뒤에</em> 전달됩니다 — 그래서 두 프리셋 각각이 조용히 서로 다른 두 창을 뜻했습니다.","changelog.8c4d3b4461cd":"<strong>⛔ 기본 창 크기에서 스템 패널이 더는 사라지지 않습니다.</strong> 레일은 1440px에서 열리고 페이지는 정확히 1440px로 배치되므로, 레일에는 여유가 전혀 없었습니다: 배율이 정확히 1이 되는 한 크기를 빼고 모든 크기에서 레일 전체가 사라졌습니다.","changelog.f3d631ac4ef8":"<strong>⛔ 레인별 드래그아웃 메뉴가 더는 반으로 잘리지 않으므로</strong>, 아래쪽 드럼 레인도 끌어낼 수 있습니다.","changelog.65a1a2828214":"수정 — Ableton에서 플러그인을 돌리다 찾은 결함 여섯, 2026-08-06","changelog.ae0a642482e3":"<strong>⛔ 이제 생성이 정말로 생성합니다.</strong> 생성을 반복해 누르면 영원히 <em>같은 비트</em>가 돌아왔고, 그래서 제품이 아티스트마다 루프 하나만 가진 것처럼 보였습니다: 엔진이 고른 시드가 시드 상자에 그대로 되비쳐 다음 누름에 다시 보내졌습니다. 이제 상자는 당신이 고른 시드와 엔진이 고른 시드를 구별합니다.","changelog.132f99a15823":"<strong>⛔ 놓은 오디오가 더는 엉뚱한 템포로 재생되지 않습니다.</strong> 끌어낸 <code>.wav</code>에는 템포가 전혀 없었으므로, Ableton이 짐작으로 워프했습니다 — 140 BPM 루프가 120 프로젝트에서 96으로 재생되었습니다.","changelog.afcec78896e3":"<strong>스템 패널이 스스로 열립니다</strong>. 세션이 처음 생성할 때. 다시 불러와도 접힌 상태를 기억했는데, 패턴을 밖으로 꺼내는 유일한 방법이 그 안에 있습니다.","changelog.5029b5a24655":"<strong>⛔ 컨트롤이 더는 벨로시티 레인 위에 얹혀 있지 않습니다.</strong> 몇 달 동안 살아 있던 문제입니다: 생성/시드/마디 줄이 편집기 위에 떠 있어서, 그 아래의 벨로시티 막대 머리는 아예 끌 수 없었습니다.","changelog.6b02e0d363a4":"추가","changelog.b62d9b57e008":"<strong>파트를 플러그인에서 바로 DAW 트랙으로 끌어냅니다.</strong> 모든 파트에는 <strong>MIDI</strong> 핸들과 <strong>오디오</strong> 핸들이 있고, <strong>레인별</strong>을 켜면 드럼 파트는 레인마다 핸들 하나가 됩니다. 파일에는 프로듀서가 붙일 법한 이름이 붙습니다 — <code>trap - Snare - 140 BPM - C# Minor</code>. ⚠ MIDI와 오디오는 의도적으로 서로 다른 목록을 제공합니다: 킷이 연주할 수 없는 레인은 노트가 실제이므로 MIDI로는 끌리지만, 무음을 렌더링하게 될 오디오로는 끌리지 않습니다.","changelog.4de5200c76df":"<strong>편곡 전체를 오디오로 끌어냅니다</strong>. 진행 상황을 보고하며, 제스처를 포기하는 순간 멈춥니다 — 빠져 있던 조각은 렌더링이 아니라 그것이었습니다.","changelog.39b376291b8b":"<strong>편곡 안에서 클립을 끌어 옮길 수 있습니다</strong>. 예전에는 재배치하려면 복사하고, 붙여 넣고, 돌아가서 원본을 지워야 했습니다.","changelog.f94f8922bef2":"<strong>드럼 그리드가 편집기입니다</strong>. 예전에는 읽기 전용이었고 자신의 헤더가 그렇다고 말했습니다. ⚠ 편집은 <strong>셀이 아니라 틱 위에서</strong> 동작합니다: 셀은 타격이 16분음표 안의 어디에 있었는지를 이미 버린 상태이고, 잇단음표는 바로 그것으로 이루어집니다.","changelog.eebab717e7db":"<strong>파트를 따로 내보냅니다</strong>. 드래그와 같은 이름 규칙과 바이트를 공유합니다 — 끌어낸 루프와 내보낸 같은 루프는 같은 파일이어야 합니다.","changelog.f1cc8234d750":"<strong>어느 파트에나 나만의 원샷</strong>, <strong>경로</strong>로 저장됩니다. 옮겨진 파일은 조용히 되돌아가지 않고 보고됩니다.","changelog.adbfdc511003":"<strong>드럼 타격의 음높이가 움직입니다</strong>. 아티스트마다 작성한 폭만큼 — rage는 8, Drake는 2, <code>country-train</code>은 0. 기차 비트는 스네어의 음높이를 바꾸지 않기 때문입니다.","changelog.c68e2faaa335":"<strong>생성은 4마디 또는 8마디를 제공합니다.</strong> 2마디는 사라졌습니다 — 두 마디에는 모델이 작성하는 필과 턴어라운드를 담을 자리가 충분하지 않아, 모든 아티스트가 똑같이 들렸습니다. ⚠ 2마디로 저장된 프로젝트는 여전히 2마디로 열립니다.","changelog.992aa08533ad":"<strong>피아노 롤에는 <code>+</code>가 아니라 평범한 포인터가 표시됩니다</strong>: 십자선은 그리기 도구의 것이고, 빈 그리드를 클릭하면 그리는 것이 아니라 선택합니다.","changelog.0b87415f26cb":"수정 — 위 작업에 대한 xhigh 코드 리뷰, 2026-08-06","changelog.a5979ff4f5ab":"검증된 결함 열다섯 개, 그중 넷은 망가진 것을 출시했을 것입니다.","changelog.059b3952ef8a":"<strong>⛔ 편곡에서 클립을 끌면 다른 클립이 지워질 수 있었습니다.</strong> 구간은 파트마다 클립 하나를 담으므로, 같은 파트의 두 클립을 끌면 둘 다 들어 올린 뒤 두 번째가 첫 번째를 덮어썼습니다 — 사라졌는데, 화면의 어떤 것도 그렇다고 말하지 않았습니다.","changelog.e6019aec8c0d":"<strong>⛔ KIT 패널을 한 번이라도 접은 적이 있으면 오디오 드래그 칩이 사라졌습니다</strong>. 킷을 불러오는 것이 그 패널뿐이었으므로 — 스템 패널은 아무것도 연주할 수 없다고 판단해 모든 오디오 핸들을 영구히 숨겼고, 그동안 내보내기는 계속 오디오를 제공했습니다.","changelog.4513b1c417f8":"<strong>⛔ 드럼 파트를 파일 하나로 끌어낼 수 없게 되었습니다</strong>. 버튼이 메뉴 여는 버튼이 되었는데, 메뉴 여는 버튼은 끌 수 없기 때문입니다.","changelog.2eabac1a208f":"<strong>⛔ 놓은 오디오가 6/8, 9/8, 12/8, 7/8에서 엉뚱한 템포로 재생되었습니다</strong>: 템포 청크가 한 마디의 박 수를 분자로 셌는데, 오디오는 4분음표로 측정됩니다. 그 청크가 고치려고 추가된 바로 그 결함이, 박자 선택기를 통해 다시 들어온 것입니다.","changelog.4c29aba1855d":"<strong>잘라 낸 클립을 “모든 트랙”으로 끌어내면 무음 파일이 쓰였습니다</strong> — 여덟 개가 DAW에 떨어졌는데, 일곱 개가 비어 있었습니다.","changelog.4f7838402f37":"검증됨","changelog.02dc39a2cae1":"<strong>⛔ macOS 드래그 소스를 이제 Windows에서 컴파일러로 검사합니다.</strong> 어떤 로컬 빌드도 컴파일하지 않는 유일한 파일이었고, <strong>오류 넷과 린트 실패 둘</strong>이 있었습니다 — 하나하나 CI의 macOS 러너가 푸시 한 번에 하나씩 찾아냈을 것입니다. <code>cargo check --target aarch64-apple-darwin</code>은 Apple 툴체인 없이 macOS용으로 타입 검사를 합니다. 툴체인이 필요한 것은 <em>링크</em>뿐이기 때문입니다. ⚠ 동작에 대해서는 여전히 아무것도 증명하지 않습니다.","changelog.ffd42ed2f7ee":"<strong>macOS와 Linux의 드래그가 더는 호스트를 멈추지 않습니다.</strong> 둘 다 드래그를 시작한 뒤 그것을 돌려야 하는 바로 그 이벤트 루프를 막았습니다 — 10분 동안 멈춘 DAW, 그리고 떨어진 파일은 없음. Windows는 영향을 받은 적이 없습니다. 그쪽의 드래그는 진짜로 모달이며, 바로 그 점이 같은 실수를 두 번 저지르기 쉽게 만들었습니다.","changelog.061558cb7b58":"<strong>플러그인이 처음으로 두 자동 검증기를 모두 통과합니다</strong> — VST3에 대해 최대 엄격도의 <code>pluginval</code>, CLAP에 대해 <code>clap-validator</code>: 통과 33, 건너뜀 10, 실패 1, 그 실패는 검증기 자체의 0으로 나누기입니다.","changelog.1a78eb82eb61":"<strong>Linux를 로컬에서 검증합니다</strong>. Docker 안에서.","changelog.11350441bdbc":"<strong>모든 아티스트가 같은 스네어 롤을 썼습니다</strong>. 모델도 시드도 읽지 않는 하드코딩된 램프로 만들어졌기 때문입니다: <strong>대표 trap 아티스트 열 명 중 여섯이 바이트 단위로 동일한 롤을 만들었고</strong>, 모든 모델이 시드 마흔 개에서 서로 다른 롤을 한 개에서 네 개밖에 만들지 못했습니다.","changelog.c2fd00b3b92c":"<strong>UK drill, NY drill, Pop Smoke는 언제나 킥 패턴을 정확히 하나만 썼습니다</strong>. 시드에 한 번도 닿지 않는 명시적인 네 마디 문법이었습니다. ⚠ 새 변형은 모두 연구가 묘사하는 tresillo 안에 머뭅니다.","changelog.bf5ae982968d":"<strong>808이 필을 가로질러 그대로 울릴 수 있었습니다</strong>: 음소거 목록에는 백비트만 있었으므로, 필이 시작하는 박의 킥이 808을 롤 전체에 걸쳐 지속시켰습니다 — drill이 바로 그것에 맞서 정의되는 것입니다.","changelog.0948365cea7b":"<strong>두 형제 모델이 구별하기에 너무 가까웠습니다</strong>: <code>pop-smoke</code>는 <code>ny-drill</code>과 숫자 넷에서 0.05씩만 달랐고, 시드 200개 중 16개에서 똑같은 비트를 만들었습니다. 이제 로스터 전체에서 비트 충돌은 <strong>0</strong>입니다.","changelog.732bec7f510f":"<strong>내보낸 곡이 더는 악기 하나가 모든 것을 한꺼번에 연주하는 것으로 도착하지 않습니다.</strong> 음높이 있는 파트가 모두 MIDI 채널 0에 있었는데, 많은 호스트가 가져온 SMF를 트랙이 아니라 <strong>채널</strong>로 나눕니다.","changelog.2aebbfe45729":"<strong>화성이 더는 포화되지 않습니다.</strong> 보이싱을 엄격한 최소 비용으로 골랐으므로 보이싱이 코드의 순수 함수가 되었습니다: <code>rage</code>는 <strong>시드 1,000개에서 서로 다른 진행 8개</strong>를 만들었고, 그 멜로디는 823개를 만들었습니다.","changelog.c44613bc0e19":"<strong>송 모드: 아티스트를 고르고, 생성을 누르면, 편곡 전체를 얻습니다.</strong> 엔진은 아티스트 자신의 곡 형식 중 하나를 뽑고 구간마다 파트마다 클립 하나를 만듭니다. 같은 종류의 구간은 클립을 공유합니다. 벌스 1과 벌스 2는 같은 비트이기 때문입니다.","changelog.a6592c5774d6":"<strong>전환</strong> — 훅 앞의 드롭아웃 박, 후반부의 스위치업, 아웃트로의 페이드. 각각은 노트가 아니라 <em>구간이 놓인 자리</em>의 속성이며, 그려지기만 하는 것이 아니라 내보낸 파일에 기록됩니다.","changelog.5829c0281641":"<strong>곡이 재생되며</strong>, 이제 타일링은 플레이어와 내보내기가 함께 읽는 한 곳에 있습니다 — 그래서 <strong>듣는 것과 내보내는 것이 같은 계산에서 나옵니다</strong>.","changelog.c57be389be35":"<strong>구간 하나만 다시 굴립니다</strong>. 나머지는 건드리지 않고. 잠긴 코드나 드럼 파트는 그것을 상대로 쓸 화성과 킷으로 다시 넘겨집니다.","changelog.032c26527262":"<strong>편집한 편곡이 프로젝트와 함께 저장됩니다</strong>. 예전에는 곡 전체를 편곡하고 다시 열면 모두 잃었습니다.","changelog.1d66ba0727df":"⚠ <strong>스템은 오디오가 아니라 MIDI입니다</strong>: 무음 <code>.wav</code> 네 개를 써서 스템이라 부르는 것은 제공하지 않는 것보다 나쁩니다.","changelog.61e0a7809c2d":"<strong>각 생성기가 자신의 클립을 유지합니다.</strong> 다섯 개가 한 슬롯을 공유했으므로, 베이스라인을 생성하면 거기 있던 멜로디가 파괴되었습니다.","changelog.383945d46625":"<strong>전체 생성은 모든 파트를 하나의 시드로 채웁니다</strong>. 그래서 다섯 개가 같은 키의 루프 다섯이 아니라 하나의 음반이 됩니다.","changelog.a16dc6673cf2":"<strong>멜로딕 생성기가 소리를 냅니다</strong>. 예전에는 미리 듣기 킷에 퍼커션만 있어서 그중 넷이 무음을 렌더링했습니다.","changelog.8a132c8da61f":"송 모드는 출시 전에 리뷰를 네 번 거쳤고, 모든 발견마다 먼저 실패하는 것을 지켜본 테스트가 있습니다: <strong>실행 취소가 이제 프로젝트 파일까지 닿습니다</strong>. <strong>아티스트 변경을 넘나드는 실행 취소가 더는 이전 아티스트의 기록을 되살리지 않습니다</strong>. <strong>복제하면 잠금과 루프가 자신의 구간을 따라갑니다</strong>. 예전에는 자물쇠가 엉뚱한 구간에 그려지고, 다시 굴리기가 고정되었다고 말한 바로 그 클립을 다시 생성했습니다. 그리고 <strong>다시 굴리기가 자신이 속한 기록을 존중합니다</strong>.","changelog.696a4b7c3c6f":"<strong>피아노 롤, 그리고 마침내 보이는 네 멜로딕 파트.</strong> 이 파트들은 브리지를 거쳐 생성되어 화면에 한 번도 나타나지 않은 채 호스트의 트랙에 떨어졌습니다. DOM이 아니라 캔버스입니다. 롤은 128행 깊이여서, 드럼 그리드의 방식으로는 노트 하나 없이도 요소가 약 15,000개가 되기 때문입니다 — 노트는 시각적으로 숨겨진 목록으로 게시되므로, 편집기는 화면 낭독기로 닿을 수 있고 테스트로 단언할 수 있습니다. 선택, 크기 조절, 변형, 벨로시티 레인을 Ableton과 FL의 표준 구성에 맞췄고, <strong>스케일 집합이 12개에서 41개로 늘어납니다</strong>. ⚠ 편집한 클립은 프로젝트와 함께 저장됩니다: 엔진이 결정론적이므로 플러그인은 <em>요청</em>을 저장하는데, 노트를 옮기는 순간 그것은 더는 참이 아니게 됩니다.","changelog.326ba70fe140":"<strong>플러그인이 소리를 냅니다</strong>. 노트온마다 나눈 구간으로 렌더링하므로, 타격이 블록 경계로 퀀타이즈되지 않고 정확한 샘플에 떨어집니다 — 블록 경계 오차는 512샘플에서 최대 11 ms, 140 BPM의 32분음표만큼입니다.","changelog.e6b17ec4bff4":"<strong>다섯 생성기 모두 플러그인에서 닿을 수 있습니다.</strong> 멜로디, 카운터, 베이스라인은 줄곧 엔진에 있었는데 브리지가 “아직 구현되지 않음”이라며 거부했습니다 — 거부는 브리지가 보고하는 대상이 아니라 브리지 안에 있었습니다.","changelog.4765927194b2":"<strong>데스크톱 애플리케이션의 크레이트가 사라졌습니다.</strong> <code>src-tauri/</code> — 셸, 트레이, 업데이터, 충돌 보고기, 오디오 경로 — 가 제거되었습니다. 제품은 2026-07-29에 퇴역했는데, 크레이트가 그보다 오래 살아남은 것은 <code>ipc-audio-types.ts</code>를 생성하고 이 프로젝트의 유일한 샘플러를 담고 있었기 때문이며, 샘플러를 먼저 플러그인으로 옮겼기에 이것이 손실 없이 안전합니다. 지나가는 길에 고친 것 두 가지, 둘 다 그저 죽은 코드가 아니라 출시 중인 플러그인에서 망가져 있던 것: 제목 표시줄이 유일한 진입점이었으므로 <strong>설정과 정보에 닿을 수 없었고</strong>, <strong>정보 창이 버전 대신 엠 대시를 보여 주었습니다</strong>.","changelog.c7c7dc30d37e":"<strong>플러그인은 바깥으로 나가는 연결을 전혀 만들지 않습니다.</strong> 문구만 바꾼 것이 아닙니다: 공급망 허용 목록에는 <code>reqwest</code>, <code>hyper</code>, <code>hyper_rustls</code>, <code>hyper_util</code>이 있었고 모두 업데이터를 근거로 정당화되었는데, 이제 그 목록은 <strong>비어 있습니다</strong> — 링크된 크레이트 187개 중 HTTP 클라이언트는 하나도 없습니다. 더는 아무것과도 일치하지 않게 된 RUSTSEC 예외 여섯 개도 지웠습니다. 아무것과도 일치하지 않는 무시 항목은 권고가 눈에 띄지 않게 돌아올 수 있도록 상시 허락해 두는 것과 같습니다.","changelog.3c9e09d2a535":"<strong>WebView2가 없는 기기가 더는 DAW를 함께 무너뜨리지 않습니다.</strong> WebView2 런타임이 없거나, 임시 디렉터리가 읽기 전용이거나, 플러그인의 브라우저 프로필을 이미 다른 WebView2 환경이 잡고 있는 상태 — DAW와 나란히 독립 실행 버전을 열면 바로 그렇게 됩니다 — 에서 편집기를 열면 호스트 자신의 편집기 열기 콜백 안에서 패닉했습니다. 릴리스 빌드는 패닉 시 중단하므로, 호스트는 그것을 잡을 수 없었고 세션도 함께 사라졌습니다. 이제 편집기는 빈 채로 열리고 이유를 말합니다. 관련된 패닉 둘도 같은 길을 갔습니다: 패닉이 되감겨 빠져나올 수조차 없는 프레임에서 돌던 커스텀 프로토콜 핸들러는 이제 500으로 응답합니다.","changelog.6daf228152f8":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-07-29\">2026-07-29</time></span>","changelog.cc6bcb5b7f8b":"추가 — 무제한 실행 취소/다시 실행, 그리고 라이선스 관문","changelog.8566f666d778":"<strong>무제한 실행 취소/다시 실행</strong>(FMM-U01). 모든 세션 변경 — 아티스트, 시드, 마디, 고정값, 자동 동기화, 그리고 각 생성 — 은 <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code>로 뒤로, <code>Ctrl</code>/<code>Cmd</code>+<code>Shift</code>+<code>Z</code> 또는 <code>Ctrl</code>+<code>Y</code>로 앞으로 갑니다. 깊이 제한은 없습니다: 항목은 몇 개의 스칼라와 <em>공유된</em> <code>Pattern</code> 참조이고, 패턴은 저장되는 것이 아니라 시드에서 도출되므로, 한 생성에 걸친 백 단계도 패턴 하나의 비용입니다. 600 ms 안에 한 컨트롤에 가한 일련의 편집은 한 단계로 합쳐지며, 두 생성은 아무리 빨리 다시 굴려도 결코 합쳐지지 않습니다. 동작마다의 호출이 아니라 스토어 구독으로 기록되므로, 앞으로 생길 동작이 등록을 잊을 수 없습니다 — 세션 저장이 이미 펼친 것과 같은 논리입니다. 프로젝트 복원 <em>뒤에</em> 켜지므로, <code>Ctrl</code>+<code>Z</code>가 호스트가 넘겨준 세션 뒤로 물러나 빈 플러그인이 될 수 없습니다.","changelog.31f95ffe2fd4":"<strong>첫 실행 라이선스 관문.</strong> 계약서는 <code>EULA.md</code>에서 컴파일되어 들어가 무엇보다 먼저 표시되며, 동의하기 전에는 아무것도 생성하거나, 재생하거나, 내보내거나, 저장하지 않습니다. <strong>텍스트를 끝까지 스크롤하기 전에는 동의 버튼이 비활성 상태로 남습니다</strong>. “읽기 전에는 사용할 수 없다”가 요구 사항이고, 처음부터 눌리는 버튼은 아무에게도 무엇을 읽으라고 하지 않기 때문입니다. ⛔ UI가 아니라 플러그인의 RPC 경계에서 강제되며 — 다시 불러오거나, 우회하거나, 개발자 도구로 조작한 페이지도 여전히 생성할 수 없습니다 — <em>허용 목록</em>으로 강제되므로, 새 명령은 의도적으로 추가해야만 동의 전에 닿을 수 있습니다. <strong>거부하면 DAW를 닫는 대신 플러그인을 비활성 상태로 둡니다</strong>. 플러그인은 결코 DAW를 닫아서는 안 됩니다. 계약서는 언제든 다시 열어 동의할 수 있으며, 그 즉시 모든 것이 동작합니다. 동의는 사용자별로 프리셋 옆에 저장됩니다 — 프로젝트 파일에는 결코 저장하지 않습니다. 그러면 협업자가 당신의 곡을 열었다는 이유로 다시 동의해야 할 것이기 때문입니다.","changelog.eaa77cffa60d":"<strong>독립 실행 버전이 Windows에서 앱 아이콘을 지닙니다</strong>. 제품, 회사, 저작권 문자열과 함께, 새 <code>plugin/build.rs</code>를 통해. 리소스 컴파일러가 없으면 빌드를 실패시키지 않고 경고합니다.","changelog.56cc4a00bc11":"<code>docs/</code> 아래의 <strong>문서 사이트</strong>: 플러그인이 하는 일, 호스트를 따르는 방식, 시드, 프리셋, 단축키, 개인정보를 검색과 짧은 변경 내역과 함께 담았습니다.","changelog.79779a61c76b":"<strong>Windows 독립 실행 버전이 빈 창을 열었습니다</strong>(TASK-P16). <code>baseview</code>의 <code>open_blocking</code>은 <code>GetMessageW(&amp;mut msg, hwnd, …)</code>로 메시지를 펌프합니다 — NULL이 아닌 <code>hwnd</code>는 그 창과 자식의 메시지만 가져오고 <strong>스레드 메시지는 전혀 가져오지 않습니다</strong>. WebView2는 COM/STA이고 완료 통지를 바로 그 스레드 메시지로, COM이 소유한 메시지 전용 창을 통해 전달하므로, 커스텀 프로토콜 핸들러는 한 번도 디스패치되지 않았고, 탐색은 끝나지 않았으며, 페이지는 <code>about:blank</code>에 머물렀습니다. 이제 벤더링된 어댑터가 <code>on_frame</code>에서 대기열을 비웁니다. <strong>프로세스가 선택하지 않으면 꺼져 있습니다</strong> — <code>plugin/src/bin/standalone.rs</code>가 유일한 호출자이고 DAW는 그것을 결코 실행하지 않으므로, 호스트의 대기열은 결코 건드려지지 않습니다. ⛔ 편집기 창과 그 자식에 속한 메시지는 건너뜁니다: 그것을 디스패치하면 baseview의 창 프로시저가 이미 <code>RefCell</code> 대여를 잡고 있는 동안 다시 들어가, <code>extern &quot;system&quot;</code> 프레임 안에서 패닉하고 프로세스를 중단시킵니다. 초록 빌드가 아니라 창을 촬영해 검증했습니다.","changelog.2589337da507":"<strong><code>v1.0.0</code> 전에는 내려받기가 없습니다.</strong> <code>v0.1.0</code>과 <code>v0.2.0</code> 데스크톱 릴리스는 GitHub에서 철회되었고(초안으로 전환, 자산은 그대로), 문서 사이트는 내려받기 링크를 제공하지 않습니다.","changelog.0ce86044cfae":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-07-29\">2026-07-29</time></span>","changelog.39dc456bb806":"추가 — 멜로딕 생성, 그리고 그것을 몇 배로 늘리는 무드","changelog.54cbe30a27b8":"<strong>멜로디 생성기</strong>(TASK-035, FR-005). 프레이즈 구조(리프 루프, 질문/대답, 콜/리스폰스, 긴 아치), 강박의 코드톤 선호, 색채음, 음정과 윤곽 분포, 옥타브 도약, 끝의 변주, 그리고 장르별 장치: rage의 두세 음 스타카토 모티프, drill의 스네어를 따라 하는 온셋과 겹친 보이싱, 스트레이트 8분음표 마디와 의도적인 침묵. 음높이는 <strong>음계 도수</strong>로 고른 다음에야 MIDI 노트로 만들어지므로, 조 안에 머무는 것은 걸러서가 아니라 구조적으로 보장됩니다.","changelog.ded02e33501e":"<strong>카운터멜로디 생성기</strong>(TASK-036, FR-006). 옥타브 에코, 벨 에코, 아르페지오, 대답 릭, 지속 패드를 나중에 걸러서가 아니라 구조적으로 멜로디의 빈틈에 배치합니다.","changelog.eca3ea3c0cbd":"<strong>무드</strong>(TASK-040V, 엔진 쪽 절반). 모델은 이름 붙은 <code>modes</code>를 작성할 수 있고 — trap은 dark, bounce, melodic, minimal을 싣습니다 — 각각은 생성 <em>전에</em> 모델에 병합되는 부분 덮어쓰기이므로, 모든 생성기가 무드의 존재를 몰라도 무드를 따릅니다. 무드는 <code>extends</code>를 통해 상속되므로, 아티스트는 자신의 계보가 가진 무드만 제공합니다.","changelog.547190faa689":"<strong>플러그인이 소유하는 프리셋</strong>(TASK-P13, 세션 쪽 절반). 바이너리에 컴파일된 팩토리 프리셋 여섯 개, 플랫폼의 사용자별 데이터 디렉터리에 있는 사용자 프리셋, 그리고 오른쪽 레일의 패널. 템포를 고정하는 팩토리 프리셋은 없습니다 — 그러면 불러올 때 DAW를 덮어쓰게 됩니다.","changelog.65770bb90ada":"<strong>Linux 편집기</strong>(TASK-P12). 이제 플러그인의 창이 Linux에서 X11과 WebKitGTK 위에 열리며, 초록 빌드가 아니라 Xvfb에서 촬영해 검증했습니다.","changelog.b0300de13023":"<strong>반복되는 멜로디가 더는 그것이 반복되는 코드와 부딪치지 않습니다.</strong> 이제 리프는 자신의 윤곽과 리듬을 유지하면서 진행을 따라갑니다.","changelog.247d12fdb7be":"<strong>카운터멜로디가 더는 절반쯤의 시간 동안 침묵하지 않습니다.</strong> 옥타브 에코는 지연됩니다. 지연이 0인 옥타브 사본은 그냥 겹침이기 때문입니다.","changelog.313e41270887":"<strong>지속 패드가 코드 루트 이상을 보이싱하고</strong>, 옥타브를 고릅니다.","changelog.8395c17cc35d":"<strong><code>echoOffset: &quot;1/8&quot;</code>이 읽힙니다.</strong> 음가 파서는 <code>&quot;8th&quot;</code>와 <code>&quot;16T&quot;</code>는 알았지만 데이터셋이 쓰는 세 번째 표기는 조용히 무시했습니다.","changelog.be33f8017295":"<strong>시드 상자가 시드 전체를 보여 줍니다.</strong> 20자리 <code>u64</code>에 대해 너비가 12자여서 긴 시드가 잘렸습니다 — 그리고 읽을 수 없는 시드는 다시 입력할 수 없는 시드입니다.","changelog.e93ad35a782f":"변경 — Freally MIDI Master가 플러그인이 됩니다","changelog.e77df776964c":"2026-07-28에 결정했습니다. 형식 자체를 위해서가 아닙니다: 플러그인에는 호스트의 템포, 박자, 재생 위치가 전달되므로, 생성된 패턴이 아티스트가 마침 작성된 템포가 아니라 당신이 실제로 쓰고 있는 곡에 떨어집니다. <code>docs/product-roadmap.md</code>에 그 결정과, 살아남은 것과 그렇지 못한 것이 적혀 있습니다.","changelog.1edfdd003cdf":"<strong>새 <code>plugin/</code> 크레이트</strong>. <code>nih-plug</code> 위에서 <strong>CLAP</strong>을 내보냅니다. VST3와 AU는 패키징 시점에 <code>clap-wrapper</code>가 거기서 투영합니다.","changelog.bf25160e0d26":"<strong><code>engine</code> 크레이트는 그대로입니다</strong>. 셸 타입으로부터 자유롭게 유지한 이유가 바로 그것이었습니다. FFI도 없고 C++도 없습니다.","changelog.a9420b95b887":"<strong>호스트 템포 동기화</strong>, 우선순위는 <strong>사용자 고정값 &gt; 호스트 &gt; 모델</strong>. 140으로 작성된 trap은 92 BPM 프로젝트 안에서 92로 생성됩니다. 고정한 템포는 호스트를 이기고, 아직 보고하지 않은 호스트는 모델에 자신의 값을 남겨 둡니다.","changelog.e33f68653f46":"<strong>노트가 호스트의 트랙으로 내보내집니다</strong>. 드래그아웃을 대체합니다.","changelog.a8f70eb81ba2":"<strong>세션이 프로젝트와 함께 저장됩니다.</strong> 아티스트, 시드, 고정값, 마디, 창 크기가 호스트 자신의 상태 호출을 거칩니다 — 설정 파일도 찾아야 할 경로도 없고, 세션은 기기가 아니라 <em>곡</em>에 속합니다. 노트는 저장되지 않습니다. 노트를 만드는 입력값이 저장됩니다. 엔진은 결정론적이고 프로젝트 파일이 다시 만들 수 있는 노트를 실어서는 안 되기 때문입니다.","changelog.105c98ac6345":"<strong>창에 세 가지 배율이 있습니다</strong>(작게, 보통, 크게). 트랜스포트 바의 버튼으로. 레이아웃은 어느 배율에서든 1440x900을 유지합니다 — 덜 보여 주는 것이 아니라 창을 더 작게 그리므로 — 창이 줄었다는 이유로 킷과 세션 패널이 사라지는 일은 결코 없습니다.","changelog.7e09563eaf78":"<strong>Ableton Live 12(VST3)와 FL Studio(CLAP)에서 검증했습니다.</strong> FL은 투영이 아니라 <code>.clap</code> 자체를 불러오는 첫 호스트입니다.","changelog.824480676fdb":"<strong>이제 릴리스에 플러그인이 실립니다</strong>. <code>.clap</code>과 <code>.vst3</code>를 모두 담은 플랫폼별 zip으로, 초안을 게시하기 전에 <code>clap-validator</code>로 검증하고, 어느 한 형식이라도 빠지면 <code>verify-downloads.yml</code>이 거부합니다.","changelog.2b3dec8da18b":"제거 — 데스크톱 앱이 퇴역합니다","changelog.2e83aecc5538":"Freally MIDI Master는 이제 <strong>플러그인</strong>으로 출시됩니다. 지금부터의 릴리스에는 CLAP과 VST3만 실리고, Windows, macOS, Linux 설치 프로그램은 더 이상 빌드되지 않습니다.","changelog.a99e41cef5bf":"<strong>v0.2.0을 쓰고 있다면:</strong> 설치한 것은 아무것도 멈추지 않고, 아무것도 제거되지 않습니다. 사본은 그저 업데이트를 더는 찾지 않게 됩니다. 업데이트가 없을 것이기 때문입니다 — 업데이트 채널은 망가지는 대신 조용해집니다. 계속 쓰려면 이 릴리스의 플러그인을 설치해 DAW에서 불러오세요. 템포 동기화, 호스트 키, 트랙 위의 노트가 거기 있습니다. 그것이 이 이동의 이유 전부입니다: 데스크톱 앱은 당신이 어떤 곡을 쓰고 있는지 알 수 없었습니다.","changelog.0743cfc41115":"알려진 문제","changelog.4565e7c201a6":"<strong>손상된 프로젝트 파일이 호스트를 중단시킬 수 있습니다.</strong> <code>nih-plug</code>의 CLAP 상태 로더는 길이 접두어를 아무 검사 없이 그대로 할당에 넣으므로, 형식이 잘못된 상태는 불러오기에 실패하는 대신 프로세스를 중단시킵니다. 상류의 버그이고, 관리되는 포크도 똑같이 지니고 있으며, 고치려면 패치한 포크가 필요합니다. 그때까지 <code>clap-validator</code>의 <code>state-invalid-random</code>은 이름으로 제외됩니다.","changelog.8b8422eaf91b":"<strong>UI는 그대로 옮겨 왔습니다.</strong> <code>src/lib/ipc.ts</code>는 늘 유일한 이음매였고 세 번째 분기를 얻었습니다. React 앱, 18개 로케일 카탈로그, 디자인 토큰은 데스크톱 앱이 싣던 것과 같습니다.","changelog.f31c4f9a96b4":"<strong>세션 칩</strong> — BPM, 키, 스케일, 스윙을 오른쪽 레일에서 편집합니다. 비어 있으면 아티스트가 정하고, 값이 있으면 당신이 정합니다. 호스트 안에서 돌 때 템포 칩은 DAW를 따르며 그렇다고 말합니다.","changelog.4c7bcf4c5c18":"<strong>코드 생성기</strong>(FR-004): 진행 계열, 모든 음높이가 구조적으로 조 안에 들도록 하는 온음계 3도 쌓기, 차용 화음, sus와 drill의 가운데 음 빼기, 밀집·개방 보이싱, 당김음이 있는 3–5박 셀.","changelog.4a720cb1c31f":"<strong><code>scripts/assert-plugin-bundled.mjs</code></strong> — UI나 데이터셋이 내장되지 못한 플러그인 바이너리를 거부합니다. 그렇지 않으면 그 실패는 오류 없는 빈 창으로 나타나기 때문입니다.","changelog.1394f31a74f1":"<strong><code>npm run plugin:standalone</code></strong> — DAW 없이 자체 창에서 돌아가는 플러그인. <strong><code>npm run plugin:install</code></strong>은 플러그인을 CLAP 폴더에 심볼릭 링크로 걸어, 복사하지 않아도 다시 빌드한 것이 바로 반영됩니다.","changelog.d4a08bd89830":"<strong><code>vst3-sys</code>는 GPLv3</strong>이고 nih-plug의 VST3 내보내기가 그것을 링크합니다 — 이 독점 제품을 위반 상태로 만들 뻔했습니다. <code>cargo deny</code>가 잡아냈습니다. 이제 VST3는 대신 <code>clap-wrapper</code>(MIT)에서 나옵니다. Steinberg 자신의 VST3 SDK는 2025년 11월에 MIT가 되었지만, nih-plug는 그것을 쓰지 않습니다.","changelog.3c8bb13f96c1":"<strong>생성 오류 메시지는 한 번도 보인 적이 없습니다.</strong> <code>.stage__error</code>에는 CSS 규칙이 없었고, 무대 전체를 덮는 <code>position: absolute; inset: 0</code>인 FX 레이어 뒤에 있었습니다.","changelog.e28adf2882ae":"<strong>고정한 템포는 IPC 경계에서 Ableton Live의 20–999로 제한되고</strong>, BPM 상자는 숫자만 받습니다 — <code>&lt;input type=&quot;number&quot;&gt;</code>는 <code>e</code>, <code>E</code>, <code>+</code>, <code>-</code>를 받으므로 “1e5”가 합법적인 템포였습니다.","changelog.584e92185850":"<code>.github/workflows/{ci,release}.yml</code>이 <code>main</code>에서 <code>format:check</code>에 실패하고 있었습니다.","changelog.a2daa7b868f3":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-07-25\">2026-07-25</time></span>","changelog.a85f00dcce8a":"1단계: 앱이 비트를 만듭니다. 아티스트를 검색하고, 생성을 누르고, 듣고, DAW로 끌어 넣으세요.","changelog.e382399a54df":"스타일 데이터셋은 앱과 함께 묶여 시작할 때 로드됩니다: 모든 모델이 첫 프레임 전에 파싱되고, 상속이 해석되고, 검증되며, 로스터는 새 <code>roster_summary</code>와 <code>resolve_model</code> 명령으로 UI에 제공됩니다. 잘못된 모델은 시작을 거부할 이유로 삼지 않고 건너뛴 뒤 보고합니다.","changelog.e2d9c9671a0f":"휴머나이저: MPC 스윙(50% 스트레이트에서 66% 셋잇단까지), 악센트·메인 타격·고스트 노트의 벨로시티 단계, 레인별 밀리초 단위 타이밍 지터, 그리고 그 지터가 얼마나 살아남을지 정하는 퀀타이즈 강도. 스윙은 타임라인 전체를 휘게 하므로, 더 세밀한 해상도로 쓰인 롤도 자신이 속한 박과 함께 움직입니다.","changelog.a6d5ebac7ba4":"드럼 생성기 코어: 킥 문법(앵커, 밀도, 당김음, tresillo 쏠림, 스네어 앞의 공백, 명시적인 다마디 형식)과 스네어 배치 — 3에 놓는 하프타임, 2와 4의 백비트, drill의 두 마디 3-다음-4, 그리고 컨트리 기차 비트 — 고스트 스네어와 겹친 클랩. Trap은 스네어가 3박에 놓여 나오고, UK drill이 작성한 두 마디 킥 형식은 모든 시드에서 정확히 재현됩니다.","changelog.24a70872e862":"햇 엔진: 기본 세분(8분음표, 16분음표, 또는 tresillo 묶음), 필 밀도, 아래의 햇을 닫는 오픈 햇, 피치 벤드된 두 번째 레이어, 그리고 루프에 걸친 스웰. 박과 엇박 8분음표가 악센트를 지니고, 그 사이의 16분음표는 조용히 채웁니다.","changelog.22fd6d81f370":"롤 어휘: 세분 전환 햇 롤(16분음표부터 64분음표까지, 셋잇단 그리드 포함), 프레이즈 끝·스네어 앞·다운비트 앞에 놓이는 롤, 양방향 벨로시티 램프, 버스트, 공백, 오프셋 클러스터 — 그리고 쌓았다 멈추기와 이중 레이어 변형이 있는 스네어 롤 사다리, 8마디 라이저, 스터터 클러스터.","changelog.18c3919ac052":"808 레인: 모델이 고정한 비율만큼 킥을 따라 타고, 한 노트에서 다음 노트로 레가토로 지속하며, 세션 키에서 루트를 가져오고, 모델이 나열한 음정만큼 미끄러집니다 — 샘플러가 포르타멘토로 읽는 겹친 노트로 쓰입니다. UK drill의 808은 스네어 아래에서 멈추고, trap의 808은 그것을 지나 울립니다.","changelog.50975022f50f":"프레이즈 경계의 필: 두 마디마다 작은 변주, 여덟 마디마다 더 큰 변주, 그리고 마지막 마디의 필로 루프가 뚝 멈추지 않고 어딘가로 이끕니다. 필은 마디의 끝을 차지하고 백비트 — 그리고 고스트 노트 — 는 그대로 둡니다.","changelog.ee8737dc4dcf":"장르 원형 열두 개 추가: Chicago와 NY drill, plugg와 pluggnb, jerk, phonk, west-coast club, boom bap, 2000s R&amp;B, liquid drum &amp; bass, 컨트리 기차 비트, 2000s pop — 모두 열다섯 개이며, 각각 그 장르를 그 장르로 만드는 문법을 단언하는 테스트가 있습니다. 이제 모델은 자신의 808이 레가토가 아니라 스타카토라고, 808이 아예 없다고, 필이 클랩에서 넘어간다고 말할 수 있습니다.","changelog.0015d2f49d55":"골든 결정성 스냅샷: 고정된 시드, 모델, 세션이 이제 바이트 단위로 동일한 패턴 JSON과 MIDI를 만들며, 커밋된 스냅샷으로 고정됩니다. 이것이 시드 칩의 약속 — 시드를 붙여 넣으면 같은 비트를 얻는다 — 을 의도가 아닌 보장으로 만듭니다.","changelog.8ce8ea96f2f6":"앱에서 생성과 내보내기에 닿을 수 있습니다: <code>generate_pattern</code>은 스타일 모델을 드럼 생성기와 휴머나이저에 통과시켜 패턴을 돌려주고, <code>export_midi</code>는 그것을 세션 디렉터리에 타입 0 MIDI 파일로 씁니다. 요청은 템포, 키, 스케일, 스윙, 마디 수, 하프타임 느낌을 고정할 수 있습니다. 요청이 건드리지 않은 것은 모델 자신의 선택이고, 시드를 생략하면 결과를 정확히 재현하는 새 시드를 고릅니다.","changelog.599338a80b32":"장르 베이스 위의 대표 아티스트 모델 열 개 — Metro Boomin, Southside, Pierre Bourne, OsamaSon, Nettspend, Summrs, Pop Smoke, Travis Scott, Future, Drake — 각각 검색용 별칭이 있고, 하나하나가 부모 장르가 만들지 않는 무언가를 생성한다는 테스트가 있습니다.","changelog.b4c20dcbec08":"<strong>앱이 비트를 만듭니다.</strong> 아티스트를 검색하고 생성을 누르면 드럼 그리드에 패턴이 나타납니다. 재생을 누르면 들리고, DAW로 끌어 넣거나 폴더로 내보낼 수 있습니다. 검색은 퍼지하고 너그럽습니다 — “osa”는 OsamaSon을, “drizzy”는 Drake를 찾고, 오타가 있어도 찾아갑니다 — 키보드만으로: ↑↓로 이동, Enter로 선택, Esc로 닫기.","changelog.4ffc65702fcb":"재생: 합성된 미리 듣기 킷, 샘플 단위로 정확한 시퀀싱, 루프, 따라 움직이는 재생 헤드, 그리고 빽빽한 패턴이 출력을 깨뜨리지 않도록 하는 리미터를 갖춘 실시간 오디오 엔진. 사운드 카드가 없는 기기도 여전히 생성하고 내보내며, 클릭했을 때 조용히 실패하는 대신 재생할 수 없는 이유를 말합니다.","changelog.2a7f05d53d42":"시드는 생성할 때마다 표시되며, 다시 붙여 넣으면 같은 비트를 다시 얻을 수 있습니다.","changelog.e948705bc342":"패턴이 만들어지는 동안 생성 물결이 그리드를 훑으므로, 비트가 깜빡 나타나는 대신 도착하며, 노트가 실제로 떨어지는 곳에서 가장 밝게 빛납니다. 시스템의 모션 줄이기 설정을 켜면 짧은 크로스페이드로 바뀝니다 — 다시 시작하지 않아도 즉시.","changelog.7f96e11b8d6b":"이제 시작할 때 스타일 모델을 건너뛰면 설정에서 파일과 이유와 함께 알려 줍니다. 건너뛴 모델은 사라진 아티스트이고, 지금까지는 콘솔만 그것을 언급했습니다.","changelog.62ce473bf733":"세션 도중 오디오 인터페이스를 뽑아도 앱이 더는 조용히 귀가 먹은 채 남지 않습니다. 장치가 사라졌다고 말하고, 열 수 있는 장치가 생기자마자 스스로 다시 열며 — 걸리는 만큼 계속 재시도합니다 — 돌아오면 그렇다고 말합니다. 재생이 저절로 다시 시작되지는 않습니다. 재생을 누르면 다시 동작하는데, 멈췄던 것이 바로 그것이었습니다.","changelog.1d647238b180":"모양 아래의 <strong>모션 줄이기</strong> 설정. 시스템에 그런 환경 설정이 없는 기기, 또는 다른 모든 것은 움직이되 이것 하나만은 멈춰 있기를 원하는 사람을 위한 것입니다. 체크하는 순간 적용됩니다.","changelog.1b03300b577b":"내보낸 MIDI에 이제 조표가 담깁니다. 파일이 묘사하지 않던 유일한 세션 필드였으므로, 클립이 자신의 808이 어떤 키인지 말하지 않은 채 프로젝트에 떨어졌습니다. 모드는 같은 으뜸음의 장조나 단조로 쓰이며, 형식이 말할 수 있는 것은 거기까지입니다. <strong>이를 위해 골든 <code>.mid</code> 스냅샷을 다시 생성했습니다</strong>: 파일마다 6바이트, 새 메타 이벤트뿐이고 다른 것은 없습니다 — 패턴 JSON은 그대로입니다.","changelog.ef6c13561f1f":"808 슬라이드가 이제 모델의 음역 안으로 다시 접히지 않고, 시작한 노트보다 한 옥타브 위까지 닿을 수 있습니다. 옥타브 글라이드 — phonk의 시그니처 — 는 예전에는 자신의 루트에 떨어져 버려졌습니다.","changelog.eba636f4a895":"상속 해석이 더는 사슬의 각 단계마다 누적된 모델 전체를 복사하지 않으며, 그 덕분에 모델 1,000개 로드가 330 ms에서 219 ms로 줄었습니다 — 시작 예산 300 ms 안입니다.","changelog.a287a4382167":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-07-22\">2026-07-22</time></span>","changelog.221bea271dc0":"첫 태그 빌드: 0단계 토대. Studio 셸, 순수 생성 엔진, 스타일 모델 데이터셋, 그리고 CI 뼈대 전체가 자리를 잡았습니다. 생성기 자체는 1단계에 도착하므로, 트랜스포트와 생성은 동작하는 척하는 대신 의도적으로 비활성화되어 있습니다.","changelog.44d12397d83d":"Cargo 워크스페이스 위의 Tauri v2 + React + TypeScript 셸, 그리고 순수 <code>engine</code> 크레이트(Tauri 타입 없음, 네트워크 없음, <code>unsafe</code> 없음).","changelog.22cecd1d88c2":"Studio 레이아웃: 왼쪽 레일, 생성기 탭 여섯 개, 그리드 무대, 오른쪽 레일, 트랜스포트. 모든 패널을 따로 접을 수 있고 상태가 저장됩니다.","changelog.6c76ad6437f8":"다크와 라이트 테마, 둘 다 WCAG 2.1 AA 대비를 검증했습니다.","changelog.654cc0ec749e":"엔진 코어: <code>Pattern</code>/<code>Note</code>/<code>Lane</code>/<code>Song</code>, <code>SessionContext</code>, 그리고 도메인별 스트림 파생을 갖춘 시드 있는 ChaCha8 RNG. 그래서 한 파트를 다시 굴려도 다른 모든 파트는 바이트 단위로 동일하게 남습니다.","changelog.b59482b3b460":"스타일 데이터셋: JSON Schema, 순환 검출을 갖춘 상속 깊은 병합, 의미 린트, 그리고 첫 장르 원형 셋 — trap, uk-drill, rage.","changelog.d7edc4251d89":"<code>datasetc</code> CLI — 검증, 린트, 통계, 커버리지.","changelog.3305f4e20d1f":"Havoc 표준에 따른 충돌 보고기: 선택 사항이고, 민감한 정보를 지우며, 클릭 없이는 결코 전송되지 않습니다.","changelog.179fa09246b2":"세 OS의 CI, 공급망 관문, 그리고 AI/네트워크 의존성 거부 목록.","changelog.c8dd551642f8":"단일 이음매에서 IPC를 목으로 대체한, <code>vite dev</code> 대상의 Playwright E2E.","changelog.723cf83ffaea":"자체 최소화 / 최대화 / 닫기 컨트롤, 가운데 정렬된 제목, 여덟 가장자리 모두에서 끌어 크기 조절이 가능한 테두리 없는 창.","changelog.3fb0f4c44595":"제목 표시줄에서 닿을 수 있는 설정과 정보, 그리고 시스템 트레이 옵션(트레이로 최소화와 트레이로 닫기, 둘 다 기본값은 꺼짐).","changelog.a03b8762dc6b":"버그 보고기와 Havoc 표준 업데이터.","changelog.671f83dcff8b":"<strong>열여덟 개 언어</strong> — 영어와 아랍어, 중국어(간체), 네덜란드어, 프랑스어, 독일어, 힌디어, 인도네시아어, 이탈리아어, 일본어, 한국어, 폴란드어, 포르투갈어(브라질), 러시아어, 스페인어, 튀르키예어, 우크라이나어, 베트남어. 전환은 즉시 이루어지고 유지되며, 아랍어는 레이아웃 전체를 좌우 반전합니다.","changelog.331da1149c6a":"<strong>전체에 Noto</strong>, 함께 묶어서: CJK, 아랍 문자, 히브리 문자, 인도계 문자, 태국 문자, 크메르 문자, 조지아 문자, 아르메니아 문자, 에티오피아 문자 등을 아우르는 546개 서체로, 어떤 언어도 기기에 마침 있는 글꼴로 대체되지 않습니다. 실행 중에 받아 오는 것은 없습니다 — 앱은 여전히 업데이트 확인 외에는 네트워크 요청을 하지 않습니다.","changelog.6cfc2a93f8cf":"CI가 세 OS 모두에서 실행 중인 앱과 모든 언어의 설정 모달을 내려받을 수 있는 아티팩트로 캡처합니다. macOS 캡처는 부분적이며 작업이 그렇다고 밝힙니다(Live-To-Do 참고).","changelog.a3c71b90162b":"알려진 제한 사항","changelog.c2fce6ca915a":"생성기, 재생, 오디오 내보내기는 아직 구현되지 않았습니다. 그 컨트롤은 반응 없는 상태가 아니라 비활성화되어 있습니다.","changelog.82af19f3d55a":"네이티브 드래그아웃은 만들어져 있지만 <strong>실제 DAW에서 검증되지 않았습니다</strong> — 그것이 0단계의 결정 관문이며 사람이 필요합니다.","changelog.58fced7db00c":"트레이 메뉴(표시 / 종료)는 번역되지 않았습니다.","changelog.169051a58b53":"설치 프로그램은 서명되지 않았습니다: Windows에서는 SmartScreen, macOS에서는 Gatekeeper가 나타날 것입니다. 플랫폼별 단계는 릴리스 노트를 참고하세요."};
